/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230703-8","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"建設委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を144件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４３号議案、品川区手数料条例の一部を改正する条例","agenda":"第４３号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１個目の容積率の認定制度の創設というところで、別紙１などを見ると、省令に定める基準に適合していれば認定だということですが、省令に定める基準というのはどういうものなのかということにも関わってきますが、これが省エネ設備にした場合に容積率を緩和するというものなのかというところを確認させていただきたいです。","respondent":"長尾建築課長","answer":"１点目、今回の法改正の対象となる建築用途が何なのかというところです。建築物の容積率の特例認定申請手数料に関わる部分に関しましては、別紙１－１の資料の上段に記載しておりますような住宅であるとか老人ホームなどといったものが対象となります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"省エネ設備になる場合ということで、省エネ促進になるということだと思いますが、今回、新しく創設されるのが、容積率の場合は２万８,０００円の手数料がかかるということですが、従前の手続の場合の手数料は幾らになるのかを伺いたいのと、高さの制限の特例許可ですが、これを拡充するということで、屋上に省エネ設備を設置する場合などが対象ということですが。","respondent":"長尾建築課長","answer":"今回、大規模な修繕、模様替えというところが対象行為として追加されましたので、今後は認定の申請をお受けできるようになるというところです。今回の大規模修繕・模様替えの内容につきましては、特に省エネ設備の設置や省エネ改修というものに限定しているものではございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"総合的設計制度のところですが、別紙１－３の資料で見ますと、省エネ改修をやる場合に、これを受けて省エネ改修が可能だと書かれていますが、それは絶対条件ではないということでした。そうすると、実際問題、これで省エネ改修が進んでいくという感触というのか見込みというのは、区としてはどのように捉えているのか伺いたいと思います。","respondent":"長尾建築課長","answer":"省エネがこの制度によって進むかどうかというところですが、一団地の総合的設計制度等の活用実績というのが、現時点では品川区の中でもそれほど多くはない状況がありまして、この制度ができたから、既存建物の省エネ化がどの程度進むのかというところは。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今まで総合的設計制度を受けていたところでもできるし、この例でいきますと、接道しない敷地のところで総合的に考えて修繕ができる。新たにそうしたことができるようになるということだということですね。分かりました。今、区内では活用例が少ないということですが、ちなみに何件かを伺いたいのと、区が実際に総合設計制度の活用のされ方をどう見込んでいるのかを伺いたいと思います。","respondent":"長尾建築課長","answer":"１万m2以上の延べ面積の建物ですと、東京都のほうで管轄する制度になりますので、それもあって品川区での実績というのは少ないような状況があります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"なかなか理解が難しいなというところがあるので、確認をいたします。別紙１－１のところです。この手数料１６万円が２万８,０００円になるというのがメリットなのでしょうか。同様に、１－２のほうは、要はおっしゃっていたように、太陽光パネルなどを設置すると当然ながら上に出てしまうと。１－３については、これはよく分からないのですよ。だから有利なのですよというところを教えてください。","respondent":"長尾建築課長","answer":"品川区として、こういった省エネ改修を行う場合の金銭的な優遇策というところは、例えば太陽光パネルの設置とかということですと、環境課のほうで一定助成制度というのはもともとございましたが、何か新しくつくるかというと、そういったことは今のところ予定はございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"ありがとうございました。１－１のほうで、１６万円が２万８,０００円になるということではなくて、別建てですよという理解でよろしいですか。安くなったらすごくうれしいのですが、別建てですよというのは、またプラスアルファかかるのねというような認識なのかなというのがあるので、その確認をします。１－３については、結局、民民になるわけではないですか。なければよろしいのですが。","respondent":"長尾建築課長","answer":"近隣の方への対応というところですが、区内では、それなりの規模の建築計画に対して認定を受けているというような実績がありますので、自然と紛争予防条例の看板設置や近隣への説明会といったところの届出の対象にもなってきます。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"法律が変わってくると、それはやはり住民の人たちには分かりません。もめてからだと非常に無駄なもめ方になってしまうのです。往々にして、なぜ区がやっているのだみたいな、民民の話なのに区のほうに責任をかぶせられるというような状況も多々あるので。ただ、それは、事情をお話しすれば理解できるということも十分にありますので、今後それを意識していただきたいなと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"現行がどうで、今回の創設に対して、その基準に適合していれば１６万円は必要なくなるわけですよね。２万８,０００円というのは上乗せではなくて、今まで１６万円だったのが、適合していれば２万８,０００円になりますよという理解でよろしいのですよね。国会の中での審議なのかもしれませんが、その辺の状況というのは、どういうふうにご理解されているのでしょうか。","respondent":"長尾建築課長","answer":"もともとは許可の制度がございました。こちらは建築審査会の同意を経て許可するということで、手数料は１６万円です。今回創設された認定制度につきましては、この特例許可制度を廃止とか変更するのではなくて、また別の制度として認定制度をつくることとなったものです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"それを受けまして、２万８,０００円の根拠といいますか。品川区ではこの制度をより推進していこうとすれば、手数料の金額設定もいろいろ考えられるのかなと思えますが、他の自治体、近隣の２３区と比較したときに、２万８,０００円という金額について、ほかはどうなのかということ。その辺のお考えをお聞かせいただきたいと思います。","respondent":"長尾建築課長","answer":"安くできるのかというところですが、手数料自体を安くするという話も当然あるかとは思いますが、助成制度等の活用等も併せてご案内しながら、問合せがあった際に、制度の活用を促していくことが考えられると考えています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"大分様子が理解できてきました。その上で、別紙１－１は、事業系という言葉もありましたが、これは住宅等ということで、例えば区立、民立も含めた住居系の特別養護老人ホームなど公共的な入所系といいますか。そういったところにも使えるのかの確認をさせていただきたいと思うのが１つです。これの意味は何でしょうかというのが３つ目です。","respondent":"長尾建築課長","answer":"別紙１－３のところですが、一団地の総合的設計制度等を区のほうで認定した実績は数件ありますが、そちらに個別に今回の対象拡充の話を通知することは考えておりませんが、やはり大規模修繕・模様替え等を検討する際は、建て主の方は建築士にまずご相談されて。","voiceIndex":25,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"最後の区域内の通路は、以前は、その区域内通路がなくても、一団地また連担建築を含めて認可できていたけれども、今後は大規模改修に合わせてというか、こういうときにこの区域内の通路もその要件に入ってくるという理解なのでしょうか。","respondent":"長尾建築課長","answer":"こちらのイメージ図でなかなか全て表現し切るのが難しいところではあるのですが、もともと認定を受けている場合ですと、左側の図で、特に区域内の通路に通路の表示はございませんが、当然こちらの通路が確保されている前提になります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"のだて委員","kind":"意見","question":"再生可能エネルギーや省エネを促進するためということと、総合的設計制度のほうは、今まで改修などができなかったのができるようになって、建物を使い続けることができるという点で、環境などの面で考えても重要なことだと思いますので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"第６１号議案、区民住宅の火災に係る損害賠償等の請求に関する民事訴訟の提起","agenda":"第６１号議案、区民住宅の火災に係る損害賠償等の請求に関する民事訴訟の提起","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"現状、入居されていた方と連絡は取れているのかというところを伺いたいのと、連絡を取るために、文書の送付や電話、訪問などを何回行ったのか伺います。ご説明の中でもありましたが、５か月分の使用料を滞納しているということなので、請求したとしても返済能力があるのかどうか。生活状況というのは把握されているのかどうか伺います。","respondent":"竹田住宅課長","answer":"返済能力ですが、昨年４月に本人を呼び出して話を聞いたところ、生活に困っているような状況ではないと。ただ、ご家族内での意見の不一致、意見の相違から、納得できないから支払わないのだとおっしゃっております。","voiceIndex":41,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"今、連絡の問題では、昨年の４月２２日から連絡が取れていないということで、連絡が取れなくなってからは、どれぐらい連絡を取ろうとしたのかというところも伺いたいと思います。大体８００万円ぐらい出ていないと思うのですが、それはなかなか大きな額ですので、なぜこういったことになったのか伺います。","respondent":"竹田住宅課長","answer":"当該建物は建設されてから１７年が経過していることから、１７年分の経年減価を行い、もろもろの計算結果がこちらの共済金の支給額の根拠になっております。","voiceIndex":43,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"なるほど。今回起こった火災も、区としては原因を把握していないと思いますが、外部のところで故意に起こした火災ではないのではないかという中で、こうした８００万円ほどの損害賠償を求められるということになってしまっているわけなので、言葉はあれですがかわいそうというか、残念な状況になっているということで、そこについては区としてはどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"先ほどご説明しました原状回復に要した費用から共済金の支給された金額を引きますと、７９０万円ほどになります。そのうち、先ほど申し上げた躯体への影響調査、設計あるいは応急処置を除きますと３００万円余となります。","voiceIndex":45,"id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認します。先ほどのご答弁の中で、家族間で納得いかないというくだりがあったと思います。区に対してなのか、家族内のことなのか、教えてほしいのですが。それと、元使用者の方のご住所も書いてありますけれど、そこに今現在住まわれているという認識でよろしいのですか。連帯保証人の方もいらっしゃいますよね。その見立てというか見通しを教えてください。","respondent":"竹田住宅課長","answer":"当該住居の使用権の継承の手続を引き続き居住する配偶者に任せておりましたが、配偶者はその手続をしなかったため、使用者はそのままですし、引き落とし口座の変更もなかった状態ですので、令和３年１０月から延滞が始まったです。２点目です。","voiceIndex":48,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"事情がちょっと分かってきました。要するに、火災を起こした方というのが違うのですよね。だから、使用者というふうに書いてある方と実際そのときに火災を起こした人というのは違っているという理解ですか。どこまで区が関与できる感じなのか分かりませんが、そこは弁護士等に速やかに理解していただければなと思いますが、そういう理解でよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"火災が発生した２月１日現在では使用者は居住しておりませんし、ご家族の方ももう既に退去しておりまして、当日は居住者はいなかった状態なのです。しかし、当日午後、使用者が廃品回収業者とともにそちらの建物に行き、その部屋を出入りしたことが確認できております。","voiceIndex":50,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"今までの質疑を通じて、ますます問題点が出てきているのかなと思えるのですが。どう質問していいのかもあれですが。使用者が出入りをされていたと。では、日常的にベランダで例えばバーベキューみたいなことをやっていたとかということではないわけでしょうかね。この黒塗りの情報が出てきたことに対して、それ以上の情報開示請求というのはしていないわけですか。どうでしょうか。","respondent":"竹田住宅課長","answer":"私も、原因を大家である区が把握する義務というのはあると思いますので、今回規則にのっとって請求しましたが、消防署側としては、規則に基づいて黒塗りでしか回答できないということを電話でも確認しておりますので、裁判を通じて真実を明らかにしていきたいと考えております。","voiceIndex":53,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"そこは私もちょっと解せません。例えば令和４年２月までは入居されていて、３月以降退去されていらっしゃるので家賃は発生していないということでありますが、本来火災がなければ、翌月からは新たな入居者に入っていただいて家賃を得られるところ、これで言うと改修工事などが行われたために、すぐには新たな入居者は入っていないと思います。併せて、使用できなかった期間はどれぐらいだったのでしょうか。","respondent":"竹田住宅課長","answer":"仮に火災がなかったとしても、新規の募集はもともと９月からでしたので、火災の影響はありませんでした。区としても、弁護士と得べかりし利益の請求ができるかどうかを検討しましたが、そういった制度ですので、その点については請求しないという結論に至ったものです。","voiceIndex":55,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"そこも民間の感覚とは違う、募集のタイミングということもあったのでしょうけれども、では、８月以降は入れる状況になっていたと。９月以降の募集でそこが使える対象になっていたと。こういう事故があったということは、重要事項説明の項目にも入るのかもしれませんが、そういったことが今後の入居に当たって影響しているということはないのでしょうか。","respondent":"竹田住宅課長","answer":"８月までに工事は全て終了しておりまして、９月の募集の際には、こちらのお部屋を含めて募集しておりますので、募集への影響はございません。入居予定者の方には状況を十分ご説明して、ご納得の上、入居していただく手続を進めております。","voiceIndex":57,"id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"分かりました。消防署の対応は私はちょっと解せませんので、そこは事あるごとに区も主張すべきではないかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"現状、連絡が取れないということなので賛成しますけれども、滞納分を払うというのは当然ですが、外部のベランダの火災で、恐らく故意ではないと思うので、それを全て入居者に請求することには疑問を感じているということだけ言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-022"}]},{"id":"topic-03","title":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、耐震化の対象拡大をするということです。この間、熊本地震で明らかになった新耐震後の住宅でも被害が出るということで、これまでも共産党としても助成の対象拡充を求めてきたので、今回拡充されてよかったと思いますが、なぜ補正で組んだのかというところを伺いたいと思います。それと、耐震化のところで、区内で新耐震以降、２０００年までという対象物件は何件あるのか、伺います。","respondent":"長尾建築課長、平原防災課長","answer":"今の見込みですと約１万棟あると考えております。この中で実際に耐震性が不十分ではないかと推計されておりますのが、東京都の耐震化率を参考にしますとその中の２割ですので、２,０００棟ほどと見込んでおります。災害対応力向上支援事業のところの時期の話です。","voiceIndex":75,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回組まれている補正予算の棟数を見ると、２,０００棟までいくのはなかなか大変そうだなと思いますので、ぜひそれは推進していただきたいと思います。そのためにも、しっかり住民の方に周知していただきたいと思いますが、いかがでしょうか。この間、耐震化については、私たちが求めても実施するとは言わなかったと思いますが、方針を変えたということなのか、伺います。","respondent":"長尾建築課長","answer":"東京都の補助が４月１日からスタートしたことも踏まえてというふうにご説明しましたが、最初の説明の中でもお伝えしましたが、令和４年５月に東京都のほうで被害想定の見直しをした中で、今回の対象拡充する部分の耐震化によって。","voiceIndex":78,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"被害想定を受けて方針が変わったということなのかなと受け止めましたが、ぜひこれは推進していただきたいと思います。防災のところでは、今回簡易トイレを約１３万回分購入するということです。これは約９,０００人分ということですが、実際、首都直下地震が起きた際には、避難する方というのが、数か月、半年、１年というふうに変わってくると思います。それで足りるという想定なのか、伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"４日目以降、避難生活が長期化した場合に関しましては、国等から救援物資が参りますのでそちらで対応するというところと、簡易トイレ以外に仮設トイレも各避難所に設置しています。そういったものも使いながら対応していくということになると思います。","voiceIndex":80,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"仮設トイレもあるということですが、トイレの問題は、結構この間も災害発生時にはいろいろ取り沙汰されておりますので、それが不足しないよう、ストレスを与えるような避難生活にならないようにしていただきたいと、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-026"},{"speaker":"渡辺委員","kind":"確認","question":"Ｗｉ－Ｆｉおよび発電機の購入費用のところを伺います。予算の数字上のところで、米印で上限が１団体当たり７万５,０００円となっています。計算上は、発電機を１５万円相当の２分の１を購入したらそこで区切りなのか、あるいは可搬式のＷｉ－Ｆｉの機材と発電機は同時には難しいという考えなのか。その確認です。この辺の想定はどのようになっているのか教えてください。","respondent":"平原防災課長","answer":"Ｗｉ－Ｆｉについてのご質問です。上限金額７万５,０００円については、発電機とＷｉ－Ｆｉを合わせた金額で７万５,０００円となっております。","voiceIndex":84,"id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問・要望","question":"先ほどの上限のところの考え方で、対象にしているのが防災区民組織なので、その方々が独自にそれぞれが発電機を購入、リストというか推奨することはあるのでしょうか。逆に言えば、これが想定の中で金額もある程度推奨するというのですか。私も以前の行政視察の際に札幌で停電を経験したときに、札幌市役所の１階では、物すごい人が電源を求めて、充電を求めて、それに対応していました。","respondent":"平原防災課長","answer":"今回の補助事業につきましては、委員ご指摘の電源タップは補助対象外になっておりますが、例えば私ども区のほうで用意しています防災資機材整備助成金といったものを活用していただきながら、都の補助金での例えば電源の用意。","voiceIndex":86,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"２分の１といっても、上限があると思うのです。それを教えてください。それから、対象建築物ということで、２階建て以下は分かりました。町会参加がないところもあるので設置しにくい部分もあるかと思いますが、それを含めて現状として、非常用の発電機の普及度と言ってよろしいですか。今回これはどういう分配をするのですか。そこら辺は、どういう手順を踏んで準備していくのか教えてください。","respondent":"長尾建築課長、平原防災課長、羽鳥防災体制整備担当課長","answer":"実際ご相談に来られた方が住んでいらっしゃる建物が在来軸組工法に当たるのかどうかというところは、ご相談いただくとき、また周知のときも。そこをしっかり調べた上で、今回の補助事業を地域にご説明する中で。それ以外の分に関しましては、各避難所の周辺にあります災害対策備蓄倉庫に保管して、不足した分を随時補充していくという流れを考えております。","voiceIndex":88,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"発電機については、やはり現状把握ですね。それは認識を高めながら、こういう助成金があるのでと促していただきたいということと、やはり町会会館を持っていないところは、なかなか難しいと思うのです。簡易トイレの設置も、いろいろと町会などがしっかり訓練などをやっていますが、まだまだだと考えていますので、そこは増やしていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"木造住宅の耐震化支援拡充についてお伺いします。先ほど対象数についてののだて委員からのご質問に対して、全体で１万棟あるうちの２,０００棟ということでした。もう一度確認ですが、要は、２０００年以前のものが全体で１万棟あって、そのうち診断結果によって倒壊のおそれがあるものが２,０００棟ということなのでしょうか。そこだけ確認をまずします。","respondent":"長尾建築課長","answer":"棟数ですが、基準が変わりました１９８１年から２０００年までに建てられました木造の２階建て住宅が１万棟ほどあると見込んでおります。そのうち、耐震性能が不十分であると見込まれる棟数が２,０００棟ほどあると試算しております。","voiceIndex":94,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"そうすると、２,０００棟は新耐震基準で建てられたにもかかわらず、もう既に倒壊のおそれがあるものだというのは、すみません、私の素人感覚では少し多いのかなと思えるのですが。木造住宅を解消して、いわゆる不燃化の建物にして、火災を食い止めるという取組があります。トータルで考えたときには、そういう切り分けをしてもいいのではないかなと思えるのですが、そこら辺はいかがでしょうか。","respondent":"長尾建築課長","answer":"は現行の制度もそうですが、ご相談いただいたときに、使える制度にはどういった制度があるのかというところと、どれをお使いいただくと一番支援につながるのかというところは、職員のほうで丁寧にお聞きしながら対応していきたいと考えております。","voiceIndex":96,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"それも一つの考え方として、それぞれの建築課とか木密整備推進課というお立場だとそれぞれの事業の推進となりますが、トータルで判断したときの品川区の住宅といいますか、安全・安心の実現においての住宅のありようを考えたときのまた１つ別の切り口があるように思えますので、そこはすみません、結論も出ないような質問で恐縮でありますが、様々なメニューを活かしながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"何点か。今の質疑を聞いていて、私の理解が。ということを確認したほうがいいかなということが１つです。在来軸組工法について、今ここで理解できるように詳しくお聞きしようと思いましたが、時間がかかるので調べます。それから、あなたは２,０００棟ではない、倒壊のおそれがない建物ですねということで、診断で振り分けられるという理解でよろしいのかというのをお聞きしたいと思います。","respondent":"長尾建築課長","answer":"今回、区内に１９８１年から２０００年までに建てられた木造住宅が１万棟ほどあると見込んでいる中で、在来軸組工法のものがどの程度を占めているかというところに関しましては、確定的なデータがございませんので、割合については不明です。","voiceIndex":100,"id":"exchange-034"},{"speaker":"若林委員","kind":"意見","question":"そうしますと、今１つ懸念が出てきました。不燃化エリアでの改修まで行った際には、同時に不燃化もという、でも、そこのエリアのは、要件は分かりませんが、それは旧耐震が対象という制度になっているのでしょうね。そうすると、新耐震での改修時には耐震化が進みますと。同時に不燃化もしっかりやりましょうねと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"オーナーの理解を、しっかり協力を得るという取組を進めていただきたいと思います。最後に、来年度という話もありましたが、東京都は今年度こういう補助制度を自治体に対して提供していますが、東京都の姿勢としては、来年度もこの制度を続ける見込みなのかというのも確認をしておきたいと思います。","respondent":"長尾建築課長、小川木密整備推進課長","answer":"都の支援制度につきましては、今年度始まったばかりですが、今年度で終わりというふうなところは聞いておりませんし、東京都も被害想定の見直しの中で。不燃化特区の区域内である建物であれば、諸条件はありますが、平成１７年３月３１日以前の木造建築物等であれば、特区の助成事業を活用することができますので、そういったものをご利用いただいて。","voiceIndex":103,"id":"exchange-036"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"この木造住宅のこの８１－００ですね。私も大分前から質問させていただいて、また会派からも要望していたことがようやくかなったのかなということで大変うれしく思っています。そこで１点だけ、耐震化の診断費用の中で一般耐震がありまして、たしかその後もう一回耐震検査があるのですよね。それがあってから、要は耐震事業に結びつくと。たしか私が勉強した中ではそうでしたが、その確認だけお願いします。","respondent":"長尾建築課長","answer":"副委員長おっしゃるとおり診断には２段階あります。最初の耐震診断につきましては、建物の壁や基礎といったところに穴を開けたりせずに、目視で確認できる内容と図面で確認できる内容を基に、建築士が診断される一般診断というものを行います。","voiceIndex":107,"id":"exchange-037"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"精密診断ですね。例えば、今回は耐震化の助成金の話なので踏み込んだ話はしないですけれど、一般診断で７万５,０００円かかって、また精密診断でも検査でお金がかかってしまうのです。これからの先の話ですが、例えばほかの自治体では、一般診断からすぐに耐震につなげるというケースもありますので、品川区でも耐震化が進むように、引き続きあらゆる手を打っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-038"}]},{"id":"topic-04","title":"および(12)につきまして、関連する内容のため、一括して議題に供します。進め方としまして、一括して説明・質疑を行い、その後、その取扱い","agenda":"および(12)につきまして、関連する内容のため、一括して議題に供します。進め方としまして、一括して説明・質疑を行い、その後、その取扱い","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"大成建設は参加組合員ですので、いろいろ話はすると思うのですけれども、説明を受けているのか、どうかというところを伺いたいと思います。第２地区の準備組合では、大成建設が参加組合員になっているということで、その際に、どのような審査を行ったり、また、様々な問題が起こっていることについて、どう対応しているのかということを、準備組合から説明はあったのかを伺います。","respondent":"中道都市開発課長","answer":"公益社団法人、一般社団法人といったところに、選定を依頼いたしまして、このようなところから、公募を行い、また、学識経験者などで構成されている審査機関で一定程度を審査し決定したものを、準備組合に答申をしています。","voiceIndex":125,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"大成建設は、様々なトラブルを持っていることは、ニュースで把握しているということでしたけれども、札幌市での施工不良は、なかなか大変な問題で、１回、解体してやり直すということになっております。このような事態を起こしている大成建設は、区内でも工事をいろいろやっているわけですけれども、そのことについて、区はどのように捉えていらっしゃるのかを伺いたいと思います。","respondent":"中道都市開発課長","answer":"繰り返しになる部分もありますが、国土交通省から、このような特定業務代行者を選定する際は、透明性、競争性、客観性といったところをもって、選定するようにということの通知がありますので、各準備組合は。","voiceIndex":127,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"工事費用の増大など、そのような様々な心配もされているのですけれども、総事業費が、当初から上がっているのか、どうかというところが分かれば、伺いたいと思います。この間、物価高騰が続いているので、上がっているのだろうとは思うのですけれども、どれだけ上がっているのかを伺います。","respondent":"中道都市開発課長","answer":"事業費につきましては、今、組合に向けて検討しているというところで、そのような中で、建物や事業費を照査している段階になりますので、事業費は、区に正確に報告があったわけではございません。今、物価高騰等、いろいろとあります。","voiceIndex":129,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"まちづくりを行っていくに当たって、国交省のほうにも書いてあるということで、関係する人や関心を寄せている人たちに広く参加を求めるものだということなのですけれども、区は、どのように考えているのかを伺いたいと思います。","respondent":"中道都市開発課長","answer":"そこには、権利外の方々をお呼びすることは、なかなか困難です。やはり、そのような状況も踏まえて、適宜、その都度、また対象者を分けて、説明会などを行っているです。","voiceIndex":131,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"この地区に入っている一つのマンションのところで、再開発意見交換会が、管理組合で行われたということで、１８名が参加をして、１２名の方は欠席届を出したそうです。面積を１００％求める権利があるということで、意見が出ています。現時点でも、このような意見が出されているということが、やはり、十分な説明や情報提供がされているとは言えないと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"区としましては、このような形で、地域とともに、まちづくりを進めてきました。ですので、地域で、１０年以上かけて、このようにやってきた取組につきましては、区としましては、今後も支援していきたいと考えております。","voiceIndex":133,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間も、準備組合の対応がひどいというところで、様々な陳情なども出されていました。そのような準備組合の対応が悪いというところは、この間、住民の方からも何度も出てきているというところですので、そこは、区としても、指導をすべきではないか、しっかり、住民の方が情報を知ることができる対応を求めることが必要ではないかと思うのですが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"先ほどのとおり、説明会等は、適宜、開催しています。周知範囲におかれましても、一定程度、武蔵小山周辺の中で、ビラ等を配って、周知はしてきているです。このようなまちづくりに関しまして、今まで行政と事業者で連携して、『まちづくりニュース』というものも配布しています。","voiceIndex":135,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"やはり、そのような中で、しっかりと具体的な情報提供がされずに、進められてきたという下で、３分の２の同意があれば、強制的に権利を奪われるということが、再開発の仕組みだと私は思います。この実態が、どこが、自分らしく暮らしていける品川になっているのか、区の考えを伺いたいと思います。","respondent":"中道都市開発課長","answer":"そのような中で、区にも相談があって、様々な打合せを経て、このような形で、１０年越しで、まちづくりは進められているですので、引き続き、区としましても、このような地域主体で行うまちづくりを支援していきたいと考えています。","voiceIndex":137,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"進めていきたいという説明であったのですけれども、武蔵小山の実態を見て、「自分らしく暮らしていける」流れになっているのですかという質問だったので、そこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"やはり、商店街の方々も、このような再開発を契機に、今後も、一定程度、売上げを伸ばしていきたいという声も聞いてあります。区としては、このような地域の声を聞いて、地域主体で進めているまちづくりを支援していきたいと考えています。","voiceIndex":139,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"「自分らしく暮らしていける品川」なのかという答弁は、なかったと思います。再開発で、超高層ビルが建って、武蔵小山の場合、どうなのか。この商店街に買物をする方が引っ越してくるのかというと、なかなか、そうではないのではないかと私は思います。やはり、そのような声を聞いて、一旦、立ち止まり、中止にすべきだと私は思うのですけれども、最後に伺いたいと思います。","respondent":"中道都市開発課長","answer":"繰り返しになりますけれども、地域で進められているこのようなまちづくりとしまして、区としては、今後も支援していきたいと考えています。","voiceIndex":141,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"聞きたいことは、１０年と言っているのですけれども、そもそも、この地域の再開発のスタートは、いつだったのですかということなのです。発案者は誰ですか、誰が発案してきましたかということなのです。透明性のあるやり方をやっていたのですかということです。そもそも、ここの部分については、スタートはいつか、発案は誰か、どこから始まったのですか。そこが分かれば、教えてください。","respondent":"中道都市開発課長","answer":"小山三丁目第１地区・第２地区につきましては、既に前例がありますので、そのような権利者同士、既にやっている中の権利者と、今どのようにやっているのかというお話があって、そのような事業者を紹介してもらって、そのようなところで。","voiceIndex":144,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"だから、その前から、意識的にこの地域をどうしていくのですかという話を、それぞれの地域で勉強をしていかなければいけないことなのかと思います。では、それを区はどうするのですかという話です。住民サイドで、もう２０年、３０年かかるようなものを、自分たち主体でやれるかといったら、なかなか、そうはいかないと思います。その辺のこれからの進め方は、どのようにお考えになっていますでしょうか。","respondent":"中道都市開発課長","answer":"取り組んできましたけれども、やはり、このような請願・陳情が出てきておりますので、今後も、どのようにして区民の方々と一緒にまちづくり参画にしていけるかを、より一層、検討していきたいと考えています。","voiceIndex":146,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、マスタープランの在り方は、やはり、丁寧に周知していく必要があるだろうと思うし、住民には、ある程度、安心感を与えていただきたい。住民たちは、これからどうなってしまうのか。ですから、それをしっかり伝えながら、少しでも不安を取り除いて、初めから関わってもらうという、そのような品川区にしていただきたいと考えていますので、これは、意見として、申します。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-050"},{"speaker":"木村委員","kind":"意見","question":"結論を出すでお願いいたします。不採択でお願いをしますけれども、様々な意見を聞き、この再開発準備組合についてですが、法的にきちんとしっかりと進められていることと考えています。地元住民が主体となっていることから、この請願に関しては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-051"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、趣旨採択を主張します。大成建設もいろいろトラブルを起こしているということは事実ですし、このような業者が施工することに関して、不安や疑問があることはよく分かりますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。先ほども意見を申しましたけれども、この第三者機関が、今、組合等々が進められているということもありますので、やはり、なるべく自分たちで解決するという方法で、それをサポートするという体制を取っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問","question":"これまでの質疑を伺っておりまして、先ほどの第三者委員会に対しても、対応が取れているということを認識しました。大成建設の対応については、地権者の方も理解をされていて、直接、遅滞なく事業を進めるようにという思いは、当然、伝えられると考えていますので、そのような意味では、この請願の願意は十分満たされていると考えていますので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択です。この陳情者は、再開発を否定しているものではないと読み取れます。いずれにしても、１０年以上、この地域と一緒にまちづくりを行ってきたというご説明もありました。これまで以上に丁寧な説明に努めていただきたい、引き続き説明をということは求めて、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-055"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。再開発はやめるべきだと思いますが、少なくとも十分な説明や情報提供は必要なことですので、区としても、指導すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-056"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。この陳情の内容は、これからの進め方のヒントといいますか、参考になるところが非常にたくさんありますので、それを大切にしていきたいと思います。ただ、小山三丁目ということになってくると、現状としては、厳しいと考えていますが、非常に参考になる陳情だと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-057"},{"speaker":"田中委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いしたいと思います。これまでの質疑を伺っておりまして、陳情者の求めている地域での説明、あるいは都市計画決定の告示がされているということで、インターネットなどを通じても、情報発信もされていると思われますので、そのような意味では、願意も満たされており、不採択としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"陳情第１６号の第１項のところにあるものは、大体、大崎ルートと同じルートだと思うのですけれども、やはりこのような要望がありますし、区としても、この３ルートを示しているわけですから、ぜひ、早期に実施をしていっていただきたいと思うのですけれども、いかがでしょうか。この間のこの大井ルートの運行している実績について、どれぐらいの方が乗っているのかを含めて、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今、大井ルートについて試行運行を開始したわけですが、残り２ルート、大崎ルートと荏原ルートにつきましては、大井ルートの試行運行の状況を見て、試行運行を開始するかどうかという判断をしていくという状況です。","voiceIndex":174,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、大井ルートを見てからということなのですが、そうすると、今回、１年たったわけですから、あと２年で見ていくということだと思うのです。この陳情の中でも、大井町を起点に様々なルートを出されておりますけれども、大井町を通って、大崎駅、五反田駅、目黒駅を通っていくルートですから、やはり、需要はあるのではないかと思うので、ぜひ早期に実施をしていっていただきたいと思うのです。","respondent":"鈴木都市計画課長","answer":"当初、様々な想定を検討し、過程を立てて、採算性も含めて検討しましたが、やはり、何分、事業としての初めての取組というところもあって、運行経費が、どの程度かかるのか、あるいは、運行経費の中でも、どの部分がパーセンテージを多く占めるのか、そのようなことが、一切。","voiceIndex":176,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"１９万人の利用だということで、これは、なかなか多いのではないかと思うのですけれども、区の受け止めを伺いたいと思います。これは、強く要望しておきたいと思います。そのような点でいくと、やはり、一つ、大井町駅を起点に、区内をいろいろ回るルートが何個もあって、大井町駅で乗換えができるというような形が、便利なルート設定にもなってくるのではないかと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"コミュニティバスについては、先ほども冒頭のご説明をしましたが、このような公共交通を補完することが、コミュニティバスの役割であるというところで、今、３路線を抽出して、大井ルートを実施しているという状況です。","voiceIndex":178,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、高齢者、ベビーカーの子育て世帯など、そのような方々の移動もしっかりと保障していくという福祉の視点を持って、ルート設定をしていっていただきたいと思いますけれども、そのような視点について、伺いたいと思います。今回、２項目めで、区としても、そのような増便を働きかけてほしいということが書かれているわけですが、この間、どういった働きかけをしてきたのかを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その後の意見交換といいますか、状況のやり取りですが、コミュニティバスをいろいろ運行していくに当たって、これから、ルートの見直しも、今、どのような形が望ましいかというところを検討しています。","voiceIndex":180,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、そのような面でも、力を尽くしていただきたいと思います。今、特に物価高騰が続いているときに、特にこの２２０円の料金を値下げということは、やはり、誰もが利用しやすい料金にしていくということで、下げるべきだと考えるのですけれども、いかがでしょうか。やはり、料金を引き下げれば、利用者も増えるということにもつながってくるのではないかと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"シルバーパスで、無料で乗っていただき、さらに、今現在、子育て、妊産婦などについて、通常料金を頂いている状況ですが、これを半額等にできないか等々について、そのような取組も検討を進めているという状況です。","voiceIndex":182,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"料金については、このような値上げを考えていないということです。妊婦の方への割引も、今、検討中ということで、ぜひ、様々ことを前に進めていただいて、最終的には、この陳情では、１００円程度に引き下げてくださいということですので、誰もが利用しやすい、このような低廉な料金に引き下げていくということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-064"},{"speaker":"西本委員","kind":"確認","question":"その途中経過ではあるにせよ、先ほどの利用の数からして、評価はどうなのでしょうか。大井ルートは、本来、それまでを含めて、図４の青いところですよね。これは確認なのですが、赤いところの路線が、今現行で運行している道になっているのですけれども、赤いところと青いところは、つながるのですか。別々なのですか。そこを教えてください。そこら辺は、どうだったのか、確認をしたいと思います。","respondent":"鈴木都市計画課長","answer":"そのうちシルバーパス半数ということは、当初の想定ですと、３割程度がシルバーパスなのかというところで、他区の状況も、いろいろお聞きしながら想定を立てたところなのですが、その見込みの中では、シルバーパスの利用が非常に多かったというところです。","voiceIndex":186,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"順調にといいますか、利用されている方が多いのかという思いがあります。皆さん、いい使い方をされている。なので、これは分離してもいいのかという考えもあるかと思っています。ただ、切り離すと、使いたい人たちが、２倍にお金がかかってしまうという部分があるので、そこは、新たに調査してほしいのです。使い方も含め、どちらがいいのか。それに関してのご意見をお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"その辺は、乗っていただく方が、お間違いのないように、案内、運行便数の割り振りで、いろいろ工夫をしていければです。循環ルートの実施に向けて、警察と鋭意協議を進めていきたいです。","voiceIndex":188,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問・要望","question":"運用する当初と利用者の状況を考えると、少し変えたほうがいいという部分もあるかもしれませんので、そこは協議をしていただいて、なるべく皆さんが利便性の高い状況にしていただきたいと思います。止まる場所も少なくて、本当にいいのか。利便性をもう少し考えて、本数を増やすなどということは、区からもアドバイスをしていただきたい、ご意見を言っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろありがとうあります。そのために、陳情者からのほかのルートに対する要望は、もう少しお待ちいただきたいという部分があります。仮に本稼働して、でも、その結果として、収支率５０％に至らなかった場合は、どのような対応が求められてしまうのか。５０％を切ってしまったときの対応は、どのようなことが予想されるのかをお伺いをしたいと思います。","respondent":"鈴木都市計画課長","answer":"今後、そこに何も設けないで、そのまま進めるのではなくて、本格導入後も、しっかりその数字に基づいて、運行の継続あるいは判断をしていきたいという状況です。","voiceIndex":192,"id":"exchange-068"},{"speaker":"田中委員","kind":"意見","question":"これまでの諸先輩方の長年の検討結果での今回の３ルートではあります。一方で、逆に、そのようなところは、既に既存の民間のバスルートが設定されているのかもしれませんが、そこは、この３ルートにとらわれずに、また、将来的には、今回の試行も踏まえた上で、ぜひ、前向きにいろいろと検討をしていただけたらという思いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":194,"id":"exchange-069"},{"speaker":"若林委員","kind":"質問・要望","question":"やはり、採算性のことも踏まえて、確認なのですが、これを独立、切り離して、２路線にすると、運転手というのか、バスの数というのか、いわゆる経費、人件費が、また変わってくるのか。今、２つを取り上げましたけれども、全然、別個の問題ですが、それぞれ、区としての見解を聞いておきたいと思います。","respondent":"鈴木都市計画課長","answer":"実施を決めたわけではございませんが、しっかり検討していきたいところなのですが、やはり、ここは、そのような方々への支援という側面と、今までバスに乗らなかった方が、半額であれば、乗って、移動したいという方も、妊産婦の方には出てくるでしょう。","voiceIndex":196,"id":"exchange-070"},{"speaker":"若林委員","kind":"質問・要望","question":"質疑も若干させていただきましたけれども、今の現行試行ルートをしっかりと検証していただいて、拡大をしていただきたいということを申し上げながら、陳情については、結論を出すで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-071"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。今やっているものを、まず、しっかり検証していただいて、その中で、拡大の方向にできるような状況であれば、ぜひ拡大の方向でと考えていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":203,"id":"exchange-072"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。内容は、試行ルート運行をしっかり踏まえた中で、今後の展開は期待すべきだと思っており、今回においては、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-073"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。大崎ルートも早期実施すべきですし、臨海斎場も行きやすくなる。物価高騰の中でも、誰もが利用しやすいような低廉な料金にすべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-074"},{"speaker":"田中委員","kind":"意見","question":"結論を出すで、不採択でお願いします。陳情の１、２、新ルートにつきましては、先ほどと同じような試行結果を踏まえて展開すべきだと考えます。３の料金に関しましても、採算性をまずはしっかり見なくてはいけませんので、ルート存続を主に考えるべきだと思いますので、３番に関しても、願意に添えないということから、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":213,"id":"exchange-075"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。大井町を起点に、いろいろなところに行けるようにしてほしいということで、そうなれば、やはり、とても便利なコミュニティバスになると思いますので、採択です。料金については、陳情第１６号と同様です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":220,"id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"今回、陳情第１２号で、区長に実際に騒音などを含めて体験をしてほしいということで出されております。実際に感じてもらうということは重要だと思います。区民がどういった被害に遭っているのかというところで、直接区民からも意見を聴くということが必要ではないかというふうに思うのですけれども、現地での体験と意見を聴くということについて、区の考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"お尋ねの実際の体感といいますか、体験といいますか、そうしたところですが、これは我々職員、それから所管とする都市計画課、私も含めて、それから区長もそうですが、品川区、令和２年度の本格運用開始以降、実際上空を飛んでいるという状況ですので。","voiceIndex":240,"id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"やはりこの間、羽田新ルートが実施されてから４年目に入ったわけですけれども、ずっと騒音にさらされ続けてきているわけです。ほかにも落下物の恐怖ですとか、墜落の不安ということを抱えている方もいらっしゃいます。そして、国に交渉をしていくということが必要だというふうに思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の方との意見交換の場というお話もございましたが、このたび、区として初めて、品川区全域において、１５歳以上の方が対象になりますが、区民アンケートという形の手法も今準備を行っていて、実施に向けて作業を行っているところです。","voiceIndex":242,"id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回出されているのが、ほかにも防音工事の助成金の問題も出されておりますけれども、その中では対象施設は全て完了したということですけれども、その関係について、先ほど若干ご説明がありましたけれども、区内の施設９か所は終了したということで、ここの陳情には２０件と書いてあるのですが、区はどれだけ工事が行われたかということは把握をされているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"本格運用開始前に国が調査をかけまして、対象施設について助成を活用して防音工事が行われたところで、区の施設については、先ほど冒頭でご説明した９件と、民間施設については１１件実施されたというふうに聞いているところです。","voiceIndex":244,"id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"そうした中で、自分の子どもが通っている学校とか、そういった利用している方が、その施設が実際に防音工事がされているのかということなど、こういう助成があるということは実際に知らないし、施設の方も知らないのかもしれませんけれども、そうしたところで情報提供していくということは必要なことではないかというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区有施設につきましては、これまでの委員会の場でも施設名についてはご答弁申し上げておりますし、基本的には、対象となる施設の区有施設、学校等については、工事が終了しているというような状況です。","voiceIndex":246,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"もう１件、陳情第２０号では、この羽田新ルート即刻中止をということで書かれております。今回ご説明があった中でも、区に寄せられた意見の中でも、撤回・改善要求が１４７件寄せられて、その他を除けば一番多く寄せられた意見だということです。やはり住民の皆さんは、羽田新ルートを中止してほしい、やめてほしいというのが一番の願いだというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としては、こうした声をその都度、直接国に届けるとともに、今回、区民アンケートという形で、地域特性を踏まえた区民の声を改めて区内全域でお聞きする予定です。そうしたアンケート結果を整理をして、国のほうにしっかり届けていきたいです。","voiceIndex":248,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"それを実現していくという立場に立てば、やはりこの羽田新ルート中止を品川区として求めていくということが必要だと思いますけれども、この間、品川区は一度も中止を求める、反対するといったことを言っておりません。なぜこうした中止を求めることができないのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"令和２年３月末の本格運用開始以降、または国が新飛行ルートの計画を打ち出して以降もそうですが、区として、国の責任において実施されている羽田新飛行ルート計画について、賛成あるいは反対という立場で議会の場で申し上げたことはないというような状況です。","voiceIndex":250,"id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々対策を求めてきたということなのですが、それでも飛び続けているわけです。３年以上たって、ずっと住民には被害が押しつけられ続けているということで、やはりもう品川区として、この羽田新ルート、中止をするという立場に立つべきではないかというふうに思うのです。やはりそうしたことを許すわけにはいかないというふうに思いますけれども、区の考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区としましては、先ほど来ご答弁申し上げている今回初めて実施する区内全域での区民アンケートの結果をもって、地域特性も踏まえながら、しっかり結果を取りまとめ、国のほうに届けていくというようなことです。","voiceIndex":252,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"当初は、住民の理解を得て進めていくと、安倍元首相が言っていたわけですけれども、その住民の理解は得られないままに、今、強行されているという状況ですので、その下で、この間も被害がずっと押しつけられているという状況ですので、この羽田新ルートは、やはり中止をする、撤回を求めていくということが必要だと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今現在、準備を進めている区民アンケートにつきましては、賛成、反対の二者択一のお尋ねをすることは考えてございません。新飛行ルートに関する地域特性ごとの具体的な影響について、アンケートの中でしっかりお聞きして、それを整理分析をして国のほうに届けていきたいです。","voiceIndex":254,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした状況を把握していただくことはいいのですけれども、その改善に向けて、一番の解決策がやはり羽田新ルートを中止するということだと思いますので、ぜひそういった立場で区民の暮らしを守るという立場に立つならば、中止を求めていただきたい、これは強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問","question":"陳情第１２号のほうです。それで、今まで、これは延べですよね、６０４件というのは延べの数だと思うのですけれども、これ、全部目を通したのですか、いや、通していますとさっき言っていましたけれども、本当に通していますか。羽田に関してはすごい議論をしています。この第１９号の陳情の中身は、少し誤解されているのではないかなということをすごく感じるのですけれども、それに関していかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区長の受け止めといいますか、今回の陳情も含めて、請願・陳情は、区長になられて以降、当然ながら全ての請願・陳情等に目を通しておりますし、区民の声については、１件１件、区の回答も含めて目を通していただいているというような状況です。","voiceIndex":258,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"第１２号のほうですけれども、区長が体験しているというのであれば、もっと議会の中での一般質問などでも、その気持ちを表現してもよかったのではないのですかと言いたくなるのです。そういう人たちに対して、どう説明するのですかと。そういう温度差が地域の中に出ているわけですから、それをどう精査して、アンケートに反映をしていくのでしょうかということをお聞かせいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"アンケートですが、地域個別のところにつきましては、これまでも区民の方から寄せられた声については、電話あるいはメールの中で、ご自身のご住所をお伝えいただく方もいれば、なかなか住所等は遠慮するという方もいらっしゃいましたが。","voiceIndex":260,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"アンケートを地域も含めて分析の中で考慮するということだと思いますが、例えば、品川区の１００％のアンケートが来たとして、その中で、極端な話、２割がこの辺だった、８割は新ルートではないところから来たという場合に、やはりそれを、２割しかないので、品川区民の皆様方の意向としては、多数決からすると賛成になるというようなことは決してやらないでほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":262,"id":"exchange-088"},{"speaker":"田中委員","kind":"提案","question":"当時、国交省の方からのこういう理由だから外国人観光客が来ないけれども、航路の開設だけは維持したいのだという明確な説明は、当時、私、聞いていなかったのですが、その後も含めて、国交省から、要は、再三言いますが、外国人観光客が今は増えてきておりますけれども、当初の予想のほどはまだ来ていない中にあって、何ゆえ航路だけが残ってしまったのか。","respondent":"鈴木都市計画課長","answer":"区のほうでも令和２年３月末の本格運用開始以降、ちょうどコロナが発生して蔓延し出した頃の状況ですので、区としても、運用開始の５月には区長が直接国交省に行きまして、コロナ禍における運用についてと、それから、落下物、騒音環境。","voiceIndex":264,"id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"地域の声を区役所を通じて国に届けるのではなくて、やはり国政マターなので、本来であれば、直接国に地域の方の声をお伝えいただくことがいいのかな、その中間に立つ品川区に、どこまでの権限というか、役割というか、区民の声を伝えることも区政の大きな役割かもしれませんけれども、やはり直接は私は国のマターだと思いますので、本来であれば、今回の陳情も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"ええ、もちろんその声は伺った上で、それを区政にお届けいただくことを全く否定はしませんけれども、これは国政案件としてしっかり取り上げていくべきではないかというふうに思っております。その辺も踏まえて、いかがでしょうか。聞き方が変ですけれども。","respondent":"鈴木都市計画課長","answer":"これまで運用開始以降、区民の方から届けられた声は国のほうに直接届けておりますし、今回のアンケートにつきましても、しっかり実施し、内容を分析把握をして、国のほうにしっかり区民の声を直接届けてまいりたいというふうに考えております。","voiceIndex":267,"id":"exchange-091"},{"speaker":"若林委員","kind":"質問・要望","question":"この騒音の状況、これはやはり数値等の客観性が非常に重要。区長個人のことではなくて、区の組織としてしっかりと対応していただきたいということが１つですし、繰り返しご答弁にあるように、今後の区民アンケートの声を基に、また国に申し上げていくということも予定されておりますので、しっかりとそのように進めていただければというふうに思いますので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-092"},{"speaker":"木村委員","kind":"意見","question":"不採択でお願いします。実は私の家の近くでも上空を飛んでいるわけですけれども、確かに国の方針、また、国が動かなければやはりどうにもならないことであろうというふうなところを思っているのです。もしできれば、本当に国が動いてくれることを私たちは望んでいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":273,"id":"exchange-093"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。羽田新ルートは撤回すべきだと思いますし、区長が区民の被害を体験することも重要だと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":275,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"本日結論出すということで、採択でお願いいたします。区長は区民の代表であります。今回、私、一般質問でも質問いたしましたが、再三、自分らしくということを盛んにおっしゃるのです。だから、こういうことを住民の声を聞いてくれよ、住民の実態を知ってくれよという切実な思いが入っているのではないかなと私は思っておりますので、ぜひこれは採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-095"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきと考えます。私の態度は不採択です。理由は、先ほども述べましたように、区民の方の思いはしっかり受けた上で、これは国政マターであるということで、それに対しまして、区の果たすべき役割としては、固定化回避へ向けての国への、今、要請をされている段階で、その検討結果待ちというような状況でありますので、まずは国の出方を見るべきだということから、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":277,"id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。羽田新ルートは中止すべきですが、情報を周知することは必要だと考えていますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":284,"id":"exchange-097"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いします。先ほど意見で申し上げましたけれども、これをとって国のほうから品川区は容認だと言われてしまうような要素があって、私は非常にこれは慎重に進めていくべきではないかというふうに思っておりますので、この陳情については不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":285,"id":"exchange-098"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきで、不採択です。理由は、先ほどの陳情第１２号で述べたとおりであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":286,"id":"exchange-099"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。やはり住民に被害をもたらしているこの羽田新ルート、すぐにでも中止をすべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":293,"id":"exchange-100"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということで、採択でお願いします。今までも固定化回避の検討中だということで、継続審議をずっとやっていて、昨年は廃案になっているのです。やはりそれは議会としていいのだろうかということを非常に私は疑問に思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":294,"id":"exchange-101"},{"speaker":"西本委員","kind":"意見","question":"この陳情も切実だと思うのです。その切実な思いをしっかり議会は、特に委員会は受け止めて審議をする。そして、すぐやれることはすぐやっていくということが私は必要だと考えていますし、この羽田新ルートについては、即刻中止を主張していきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":295,"id":"exchange-102"},{"speaker":"田中委員","kind":"意見","question":"今日、結論を出すべきと考えます。不採択で、理由は、陳情第１２号で述べたとおりであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":296,"id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"こうした個別の建築計画についてなのですけれども、不当な利益を害するおそれがあるということですけれども、やはり計画段階から住民に示していくということが、先ほども再開発の問題等で議論がありましたけれども、周知をしていくという意味でも必要だと、まず住民の方が、どういった計画なのかと、自分に関わる問題等を知っていくためにも、やはり公開をしていくことが必要だというふうに思いますけれども。","respondent":"鈴木都市計画課長","answer":"それについて非公開ですが、基本的には、区の情報公開条例の中でも、その第７条第３項において、「法人その他の団体に関する情報または事業を営む個人の当該事業に関する情報であって」、次に掲げるものとして、「公にすることにより、当該法人等または当該個人の権利。","voiceIndex":303,"id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"この千代田区のものを見ると、その場に事業者とか設計者の方も来て説明をしたりですとか、これは傍聴もできるのですけれども、傍聴者は発言はできないということなのですが、意見は提出できるということで、最後に、会長が要旨を読み上げるということもやっているということで、やはりそうした形にしていく、公開された場にしていくということが品川区でも必要ではないかと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的に、個々の計画に対する公開、非公開の考え方は、先ほどの情報公開条例に基づいているとご説明しましたが、景観計画、これから状況においては改定の場面も迎えることが想定されますし、そうした中で、しっかり傍聴していただき、意見もいただきながら、公開していきながら。","voiceIndex":305,"id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"結局、特定大規模建築物等については公開はしないということなのですが、そうすると、これは特定のある一定の規模以上の建築物は公開しないということですけれども、その一定の規模以下のものは公開をされるのか伺いたいと思います。もし公開されるのであれば、この特定大規模建築物等との違いは何なのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"高さが４５ｍ以上または延べ面積１万m2以上の建築物、こうした対象の建築物については、景観審議会で意見をお聞きし、景観のさらなる向上に向け、事業主に検討していただくという取組です。","voiceIndex":307,"id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"この一定規模以上のものが景観審議会に諮るということですね。千代田区の事例も少し紹介させていただきましたけれども、そうした形で開かれた審議会になるように、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":309,"id":"exchange-107"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認したいのですが、先ほど、このご指摘によってホームページも変えたということなのですけれども、それはいつ変えられたのですか。最近ですか。多分、６月２１日にこの陳情が来ているのですが、その前なのか、後なのか、いかがですか。そこをお聞きしたいです。","respondent":"鈴木都市計画課長","answer":"この１８日にメールでお寄せいただいたご意見について、内容を確認し準備を進めてきたところで、６月２１日に陳情がなされたというところで、結果、ホームページの修正は６月２８日に行ったところです。","voiceIndex":311,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"できれば、ホームページを変えましたという報告はしてあげたほうがいいのかと思います。お願いしたいと思います。だけど、これが、この景観審議会の目的ではないと思うのです。であるならば、この審議会委員は、９名おりますけれども、学識経験者が６名なのです。なので、この陳情者の言っていることと、実際ここの景観審議会の役割は違うのではないかと思うのですが、その辺はいかがですか。","respondent":"鈴木都市計画課長","answer":"ですので、ある意味、その景観計画に基づいて、学識経験者等の方から、例えばですが、水辺に面しているところでの建物は、対岸からの見え方ですとか、連続したときの水辺で映える色ですとか、あるいは景観のデザインですとか。","voiceIndex":313,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"そうであるならば、今後、公開という形、なるべく個人情報的なところは伏せるにしても、ある程度、公開できる範疇を広げてあげたほうが、景観上こういうふうに、要は、感覚的なところが大きいということになれば、こういう審議があって、こういう観点のもとで、こうなりますみたいな、そういうものをやはり公開するということが必要なのかなというふうに今感じましたので、ぜひ。","respondent":"鈴木都市計画課長","answer":"公開の仕方は、傍聴、議事録による公開、それから、審議会で使用されている図面等の公開、様々だと思うのですが、例えば図面などは計画段階の図面ですので、例えば黒塗りといいますか、全てを黒塗りにしてもあまりよろしくないような状況もありますので、それから。","voiceIndex":315,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、大規模の開発をやるときに、どういう議論があってこういう状況になっているのですかということがやはり気になって、こういう陳情になっていると思うのです。なので、もちろん全部を出すことはできないかもしれませんが、やはりその経緯は、透明性のあるまちづくりという観点からすれば、努力はしていただきたいというふうに思っておりますので、これを意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-111"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出すで、不採択でお願いします。ご説明にもありましたように、それぞれ指摘いただいた課題に対して、対応であったり、これからの改善の見込み等が多々見られる。そういうことも踏まえて、そういった意味での不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択です。原則公開、ただし、非公開の部分もあるという原則を、一部ホームページ等に区民からのご指摘を速やかに改善されたというところは、また今後もしっかり進めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-113"},{"speaker":"木村委員","kind":"質問・要望","question":"結論を出すということをお願いします。本日結論を出すのですが、しながわ未来としても、景観審議会の公開は区として進めていただきたいと思っています。区も公開の方向で考えているようなので、この陳情については、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-114"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。計画策定段階から、やはり区民にも公開すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":322,"id":"exchange-115"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。希望としては、できる限り透明性のあるまちづくりを私も目標としておりますので、いろいろと、その場の状況によってになるかと思いますけれども、努力していただきたいという希望を持っておりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":323,"id":"exchange-116"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきで、不採択でお願いします。今回の陳情者の方のご指摘によって、ホームページの公開など改善された部分もある一方で、やはり特定大規模建築物等の非公開の趣旨も分かりますので、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":324,"id":"exchange-117"},{"speaker":"のだて委員","kind":"質問・要望","question":"区営住宅の新規建設を求めるということで、この間の応募状況を伺いたいと思います。そうした中で、やはり区営住宅の役割が発揮されるときではないかというふうに思いますので、ぜひ増設していくべきだと思うのですけれども、増設をしなくて区民生活の安定ですとか社会福祉の増進に寄与することができるのか伺います。","respondent":"竹田住宅課長","answer":"物価高騰の中というお話ですが、先ほどご紹介したとおり、公営住宅法は、低廉な家賃で賃貸し、社会福祉の増進に寄与するということが目的ですが、第３条には、低額所得者の住宅不足を緩和するため必要があると認めるときはとなっておりますので。","voiceIndex":332,"id":"exchange-118"},{"speaker":"のだて委員","kind":"質問","question":"不足を緩和するためということで第３条に書かれているということでしたけれども、今この応募状況を聞いた中で、低くても３５倍、高いと４７倍ということですので、これは緩和すべき状況ではないかと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"こちらは以前よりは倍率は低くなってあります。現在の住宅戸数を適切に維持管理しながら、社会福祉の増進に努めてまいりたいと考えております。","voiceIndex":334,"id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"以前よりは低くなっているということですが、それでいいのですか。区として、やはり低所得者の方へ住宅を供給するということが、今こそ私は必要だというふうに思いますけれども、いかがでしょうか。それと、以前より低くなっている原因を伺いたいと思います。","respondent":"竹田住宅課長","answer":"民間ストックの有効な活用を図っていくという観点からも、区営住宅だけではなくて、民間住宅も有効に活用しながら、全体として住宅施策を展開していくべきものだと考えています。それから、倍率ですが、倍率は状況により増減するものと考えております。","voiceIndex":336,"id":"exchange-120"},{"speaker":"のだて委員","kind":"質問","question":"倍率は募集戸数と募集者数で増減するわけですけれども、その原因をなぜ下がってきているのかというところで、区の分析はないということですか、そこを伺いたいと思います。そうした方々に区が住宅を提供していくということが必要だと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"先ほど申し上げた事業でも、８０の不動産事業者の方から、協力店に加盟していただいて実績が出ているところですので、民間賃貸住宅も含めて住宅施策を考えていきたいと考えています。","voiceIndex":338,"id":"exchange-121"},{"speaker":"のだて委員","kind":"質問・要望","question":"民間を含めてということなのですけれども、民間住宅が十分あることが区営住宅を増設しない理由にはならないと思うのです。やはり役割が違うと思いますし、応募している方は、やはり区営住宅を希望して応募しているということですので、そうした要望に区としても応えていくことが必要ではないかと思いますけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"最近は、高齢者も大きなマーケットですので、高齢者の方等にもお住まいいただくことに積極的にお考えになられているオーナーも多くありますので、そういった方々のご意見も聞きながら住宅施策を考えていきたいと考えています。","voiceIndex":340,"id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"それで、連帯保証人のほうなのですけれども、かねてから連帯保証人をなくすべきだということで、私たち、言ってきておりますけれども、保証会社を使えばいいのではないかというようなご説明でしたけれども、やはりそういった負担が増えるということにもなりますし、やはり低所得者の方には、そうした負担も大変になってくるということですので、そうしたことを受けて。","respondent":"竹田住宅課長","answer":"一時的に収入が減ったときに、個人または法人の連帯保証人にご協力いただいて、その間に実現可能な分割案を一緒に考えていくなど、入居者のご事情に配慮し、入居者の方に寄り添った対応をとっていきたいと考えています。","voiceIndex":342,"id":"exchange-123"},{"speaker":"のだて委員","kind":"意見","question":"連帯保証人をなくすことが寄り添っていないような答弁なのですけれども、これは低所得の方を、つながりがない方も含めてということになりますけれども、そうした区民の方に寄り添って、この連帯保証人を廃止すべきだと言っているので、また改めてご答弁いただけますか。","respondent":"竹田住宅課長","answer":"品川区では、安易に訴訟になることのないように、使用者の方と分割等の可能性を十分探りながら丁寧に対応していきたいと考えております。","voiceIndex":344,"id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"都の説明がよく分かりませんでしたけれども、品川区ですぐに裁判にならないようにということなのですが、それは区として丁寧な対応をしていけばいいことだというふうに思うのです。やはりそれこそが区民に寄り添った対応になるのではないかなというふうに思いますので、連帯保証人は、ぜひ廃止していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":346,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"１点だけ。保証人がいない人は保証協会を利用するというふうに書いてあるのですけれども、これはどのぐらいかかるものなのですか。その金額だけ教えていただきたい。","respondent":"竹田住宅課長","answer":"年間１万円の保証料をお支払いいただいております。","voiceIndex":348,"id":"exchange-126"},{"speaker":"若林委員","kind":"意見","question":"結論を出します。不採択です。連帯保証人については、東京都の考え方はあると思いますけれども、今ご説明のあったように、民間も法人も含めた連帯保証人をしっかりと立てて、何かあったときには、しっかりオーナーとして責任をとるように努めていくということですので、これもしっかり連帯保証人を立てて進めていただくのがふさわしいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":352,"id":"exchange-127"},{"speaker":"木村委員","kind":"質問・要望","question":"本日結論を出すでお願いします。陳情の内容である区営住宅の新設には、建物建設、それから建設期間に時間を要するため即効性がない。多額の費用、取得用地の選定など、課題がたくさんあります。そのため、例えば居住費等の助成金支援、支給などの別の支援策のほうが即効性があり、有効であると考えます。別の支援対策を求めていくこととして、本陳情は不採択としたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":353,"id":"exchange-128"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。応募倍率が高くなっていますし、物価高騰も続いていますので、増設すべきですし、連帯保証人についても、本来必要な方が申込みを断念することがないように廃止をしていくべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":354,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。住宅施策を、私は今の答弁の中でも、民間を非常に活用していただきたいというふうに強く思っております。そこで、いろいろ丁寧にお一人お一人対応していただいて、これからもそういう進め方をぜひお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-130"},{"speaker":"のだて委員","kind":"質問","question":"説明会については、マシンが故障したことについての説明は、これまで行われていないということで、各地域で教室型説明会を実施してほしいということで、少なくとも、こういった説明はやっていくべきだというふうに思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海からは、令和４年１２月から令和５年２月にかけて実施いたしましたオープンハウス型説明会、こちらは計１２回開催しておるのですが、品川区におきましても、中央新幹線の沿線の地域センターにて３会場、計６日開催されてあります。","voiceIndex":364,"id":"exchange-131"},{"speaker":"のだて委員","kind":"質問","question":"オープンハウスのところで説明されたということなのですけれども、オープンハウス型というのは、その工事が止まったことについての説明会ということではなくて、リニア全体のための説明会ということで行われましたので、やはり特に品川区内も通るわけですから、その上に住んでいる方は、今どういう状況になっているのかと不安を抱えていると思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の説明会が各地域で必要ではないかというお話ですが、区といたしましては、教室型、オープンハウス型、各町域で実施するか否かにつきましては、教室型、オープンハウス型ともに、長所短所があることは認識しているところではありますが、開催方法、開催頻度につきましては。","voiceIndex":366,"id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした地震が起こった際に、リニアが止まると、急ブレーキするのだと思いますけれども、そうすると減速をしていくということだと思うのですが、通常というか、高速の場合は浮いているわけですけれども、減速をして１５０キロ以下になると、車輪が出てレールを走るということになりますので、やはりそうしたところで揺れが起これば、様々、レールとかに当たったりとか、被害が出ると思うのですが。","respondent":"大石まちづくり立体化担当課長","answer":"このため、異常時につきましても、しっかりとＪＲ東海は検討されているものと認識しています。","voiceIndex":368,"id":"exchange-133"},{"speaker":"のだて委員","kind":"質問","question":"実際に地震の専門家の方が、こうしたリニアについても大きな被害が出るということで指摘をしているわけですから、そこは区としても受け止めるべきではないかというふうに思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、引き続きＪＲ東海に対し、区民の不安払拭をできるように、丁寧な対応を求めていくものです。","voiceIndex":370,"id":"exchange-134"},{"speaker":"のだて委員","kind":"質問","question":"仮に、リニアに強いということで安全に組まれたとしても、トンネルの中ということで、陳情にも書いてありましたけれども、全体の８６％がトンネルということですので、そこからまた、特に大深度となると、相当深い、４０ｍよりも深い地下の中で取り残されるということですから、そこから避難をしなければならないということになると、その避難をするのも一苦労ということで。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の大深度からの避難が大変というお話だったかと思うのですが、どういった非常時の対応がとれるかということは説明会の中でもお示ししていますので、それらが適切に実施されることが大前提のものになっておりますので、これは安全に施工、避難ができるように。","voiceIndex":372,"id":"exchange-135"},{"speaker":"のだて委員","kind":"質問","question":"活断層について配慮しているということなのですが、そうすると、そのまま措置をしたことによって、もし活断層がずれた場合には、リニアには影響がないということなのでしょうか。そこを伺いたいと思います。そうしたことを考えると、しっかり対応していくというのは、完全に安全なものを確保するということは無理ではないかというふうに思うのですが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"避難につきましては、委員ご指摘のとおり、大深度地下のところで非常停止等々発生した場合に、通常より時間がかかるというのは容易に想定はできるところですが、こちらはＪＲ東海がしっかりと案内サインや、事前の避難訓練等々、そういったものを確実に実施して。","voiceIndex":374,"id":"exchange-136"},{"speaker":"のだて委員","kind":"意見","question":"最後に１点だけ。この活断層は適切に対応というのですけれども、やはりそこを通れば、そこがずれれば大きな影響が出るということになりますので、やはりそういった面も含めて、様々問題点が７点指摘されておりますけれども、そうした面で、このリニア新幹線を中止すべきだということで言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":376,"id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"１点だけ確認させてください。東京都との関係はどうなっているのですか。責任の範疇であったりとかです。それと、国、東京都と品川区の関係性、これに関して。もちろん品川区は住民の要望とか心配事があれば、それは当然、国のほうに上げていくのですか。そこら辺の関係性がよく分からないので教えていただけますか。","respondent":"大石まちづくり立体化担当課長","answer":"今、東京都との関係性というご質問だったのですが、本事業は、あくまでＪＲ東海が実施している民間事業になりますので、基本的には、品川区とＪＲ東海は、説明会だとか、そういったことに対して周知をしっかりと連携していく。","voiceIndex":378,"id":"exchange-138"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、東京都としては、結局、通るのは品川区だけではないではないですか。そこを集約するとかと、そういう役目は全く果たさないということなのでしょうか。あくまでも品川区の不安な住民の声は、品川区がＪＲ東海のほうに話をするということであって、それは国に対してはどういう関係性があるのですか。この要望は、あくまでも実施者であるＪＲ東海に伝えるというだけになるのでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"もう１点が、直接国に求めるのかということなのですけれども、今回の事業が国によって承認されている事業ですので、そこはしっかりと、今回の陳情にもありますとおり、求めていくのであれば、ＪＲ東海と国になるのかなというふうに認識しています。","voiceIndex":380,"id":"exchange-139"},{"speaker":"西本委員","kind":"質問","question":"これ、同じような住民の不安は起きているのですよね、お隣さんであったりとか。それぞれ国に対してとか、大体、国に対して一自治体は結構大変なので、だから、そういう問題点は、東京都がまとめて、国に対して、それからＪＲ東海に話をするとかと、そういう役割を果たしてもいいのではないかと思うのですけれども、そういう動きは全くないという認識でよろしいですか。","respondent":"大石まちづくり立体化担当課長","answer":"現時点では、そのようなお話は出ておらないのですが、今後、状況を見て、東京都に情報提供するかどうかということは判断していきたいと考えています。","voiceIndex":382,"id":"exchange-140"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。地震の危険性もありますし、品川区でも陥没事故などを起こしかねない。ほかにも様々問題を抱えるリニアは中止すべきですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":388,"id":"exchange-141"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。これ、品川区だけの問題ではないので、近隣の地域との協力を図るとか、やはり住民運動の中でもそういう視点も必要なのかなという思いがあります。もう少し東京都が動いてくれたらなという思いもありますので、今後そういう視点も含めて、要望を言えたら言っていただきたいというふうに思っておりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":389,"id":"exchange-142"}]},{"id":"topic-05","title":"専決処分の報告について（報告第２０号）","agenda":"専決処分の報告について（報告第２０号）","exchanges":[{"speaker":"若林委員","kind":"確認","question":"すみません、確認だけ。２の事故の概要の安全確認を怠った、後方で停車した普通貨物自動車に接触しと、後方で停車したというのは、要するに、建築課の車両が後進した。停車したというのは、同時に後ろで普通貨物自動車が動いていたということなのですか。それとも、後方に停車していたということなのか。動か静なのか、その確認だけ。少し読み取れない。","respondent":"長尾建築課長","answer":"ただ、こちらの庁有車が後方確認が不十分な状態でバックで入庫しようとしたところでぶつかってしまった、そういう状況です。","voiceIndex":405,"id":"exchange-143"}]},{"id":"topic-06","title":"専決処分の報告について（報告第２１号）","agenda":"専決処分の報告について（報告第２１号）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"誤収集があったということで、私も地域の方から、他区だったのですけれども、自分の荷物が持っていかれてしまったということがありましたので、ぜひこれは気をつけていただきたいというふうに思います。何か答弁があれば。","respondent":"品川品川区清掃事務所長","answer":"今後このようなことがないように、こういった事例は必ず収集作業職員に周知して、こういう事例がありました、今後も気をつけてくださいということで、今回の件についても全員に徹底しておりますので、今後また気をつけていきたいと思います。申し訳ございませんでした。","voiceIndex":411,"id":"exchange-144"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":96772,"voices":419}},{"id":"r05-20230703-9","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"文教委員会","time":"午前１０時００分～午後 ０時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"教育職員の給与に関する条例の一部を改正する条例、(3)第４６号議案、学校教育職員の旅費に関する条例の一部を改正する条例、(4)第４７号議案","agenda":"教育職員の給与に関する条例の一部を改正する条例、(3)第４６号議案、学校教育職員の旅費に関する条例の一部を改正する条例、(4)第４７号議案","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと３点目は、こうした異性パートナーと同性パートナーとの差というのですか、それを具体的になくしていくという制度改正は大変重要だと思いますし、それをできる限り、品川区も関わる民間の子ども、学校、教育施設などに広げていくことは大切ではないかなと思うのですけれども、例えば来年、児童相談所設置に伴って、認可外保育施設なども区に権限が移るとかありますので。","respondent":"中谷指導課長","answer":"最初の２つのご質問に答えさせていただければと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね、人権啓発課を中心に、ただ、子どもとか教育とか学校を所管する部門としても、ふだんの中で、こういうことを区としても進めているので、皆さん民間のほうとしてもぜひということで、情報提供等を実施していただきたいと思います。要望にします。もう少し、一言、分かりやすく旅費とは何ぞやというのを教えていただきたいです。","respondent":"中谷指導課長","answer":"金額について、まず交通費については実費額ということで申し上げたとおりなのですけれども、後半の旅行雑費、宿泊料、食卓料、着後手当といったものは、年齢によって金額が異なっておりまして、１２歳以上の者については職員相当の３分の２。","voiceIndex":8,"id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"新旧対照表の学校教育職員の給与に関する条例の第１４条で、新たに職員となった者に扶養親族等がある場合または職員に次の各号のいずれかに該当する事実が生じた場合においては、直ちにその旨を教育委員会に届け出なければならないということで、これは幼稚園教育職員についても同じように書かれているのですけれども、直ちに教育委員会に届け出なければいけないとなると。","respondent":"中谷指導課長","answer":"その手続をしていただければ、今申し上げているこの給与の制度もしっかり不利益なく活用できるということで、この辺りが私たちとしては一番重要なところになってくるのかなと考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今の件で１件と、もう１件、２件です。それは要望も兼ねて、もし何かご意見があれば、言っていただきたいと思います。もう１件なのですけれども、今回の改正に関して、経緯や改正内容を見せていただくと、東京都がパートナーシップ宣誓制度をつくったので、それに準じて区有の先生方の部分に関しても改正しましょうと。なぜ改正になったのかという中で、どういういきさつなのかというのを確認させてください。","respondent":"中谷指導課長","answer":"お一つ目の守秘義務を守るということは、やはり我々行政としては当然のことだと考えています。こういった申出があったときには、そのほかもそうですけれども、全て個別的に対応しますので、その辺りはご安心いただきたいと考えています。","voiceIndex":15,"id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それは教育委員会としても遭遇してくる場面が教育の中でもあるのかなと思うので、そこはぜひ品川の子どもたちも含めて、今の時代にしっかりと合ったような教育体制もこれに含めて、進めていっていただきたいなと。これは要望で終わります。もし何かあれば言ってください。","respondent":"中谷指導課長","answer":"その意味でも、子どもたちに性的マイノリティについてどう教えていくのかということがやはりこれからとても重要になってくると思いますので、人権教育の観点から、特に市民科でしっかり充実した取組が展開できるようにしてまいりたいと思います。","voiceIndex":17,"id":"exchange-005"}]},{"id":"topic-02","title":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"子ども未来部の予算なのですが、バースデーサポートですけれども、このタイミングで補正に計上した理由があれば伺いたいのと、また、ちょっと説明があったような気がしますが、なぜ今年度は１万円で、来年は６万円で、これは来年度以降も継続する事業なのかというのを伺います。伺います。","respondent":"染谷子ども家庭支援センター長、石井保育支援課長","answer":"今後の実施の部分につきましては、とうきょうママパパ応援事業、こちらの補助事業につきまして、現状では東京都は令和６年度までの実施を決めているところでして、それ以降につきましては、現状は、今後、効果検証を行い。そのほか、例えば施設内での見守りのためのセンサーカメラですとか、ドアセンサー等の設置についても費用補助の対象としていますので、こういったことで安全対策に対する補助を進めてまいりたいと考えています。","voiceIndex":52,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"それと、部活動のほうも併せて質問しますけれども、１枚目の資料と参考資料についてなのですが、地域移行等、「等」とあるのですけれども、これは参考資料でいうところの地域連携と地域移行ということを指しているのか、「等」について伺いたいのと、あと、先ほどご説明あったところの、アンケートというか意向調査で、校区教育協働委員会、保護者からの意見を受けて。","respondent":"石井保育支援課長、立木保育課長、今井保育教育運営担当課長、中谷指導課長","answer":"ヒアリングを実施したところ、認可保育所では約７割程度の保育園が活用したいと考えております。こういった置き去り防止とか見守りに関しましては、職員がしっかりとマニュアルに基づいて見守りをしているというようなところと。公設民営園の部分の活用の見通しということですけれども、こちらも事前にアンケートをとらせていただきまして。特に協議会のところで、２種目のスポーツ協会への委託であったり、民間委託への委託であったりということだけではなく。","voiceIndex":55,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどのは要望です。なぜ地域移行が学校教育の質向上になるのか、伺いたいと思います。生徒アンケートにあるように、部活動をやっている方は、部活動ですごく充実しているという実感があるわけですから、その当事者の声を協議会に入れないでどうするのだと。それは子どもの権利条約の観点でもあるので、そこら辺、ぜひ入れるべきだと思うのですけれども、お考えを伺いたいと思います。","respondent":"立木保育課長、中谷指導課長","answer":"園外保育においてもそういうような状況でございまして、そうした中で、補助的に使うというところを全く否定するものではございませんし、いいものがあれば導入したいと考えていますが、今現在は。最後の、協議会にお子さんの声を入れるということについては、ぜひ検討していきたいと思っています。","voiceIndex":60,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。ですから、検討していくに当たっては、より指導力といいますか、あるいは、これまで指摘されてきたような安全性の問題をしっかりと、地域でやっていくということになると、なかなかこれは大変な課題なのではないかなと思うのですけれども、そこら辺についてお考えがありましたら伺って、終わりにしたいと思います。","respondent":"中谷指導課長","answer":"試合については、公式の大会というのは８年生からということが決まっているということなので、これに合わせまして、いらしてくださったお子さんの学年に応じたメニューが展開できるように工夫してまいりたいと考えています。","voiceIndex":63,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"（３）でアウトリーチを実施するということになっておりますが、アンケート未回答者に対しても実施ということで、何を要望しているか分からない方に対して、どのようなアウトリーチをされていくのか、どう支援していくのかというお考えがあれば、お考えをいただきたいと思います。","respondent":"染谷子ども家庭支援センター長、石井保育支援課長、中谷指導課長","answer":"その５％のうち、保育園に通園しているですとか、健診を受診済みとか、医療証を利用されているとか。今後、設置の見通しですけれども、やはり暑くなる季節を迎えますので、それまでには設置できるように働きかけてまいりたいのですが、先般。けががあった場合の補償というところでして、まず、学校部活動の場合、ご指摘いただいたとおり、スポーツ振興センターなどで。","voiceIndex":66,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"バースデーサポート事業を活用した在宅子育て支援ということで、アウトリーチに関しましても、粘り強く、今後とも電話等での対応を続けていただければと思います。こちらは要望でお願いいたします。災害共済給付制度、今まで使われていたそれ以外のところでも、学校の部活動地域移行のことに関しましては、こちらは保険料も含まれての予算ということなので、こちらも引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"端的に質問します。そもそもこの事業、在宅子育て支援でやっているのかどうか、教えてください。それと、第１子、第２子、第３子などの記述があるのですが、第２子、第３子の定義を教えていただきたいと思います。このことに関して、第２子、第３子などの記載の定義を教えてください。","respondent":"染谷子ども家庭支援センター長、中谷指導課長","answer":"おっしゃるとおりで、子育てギフトをお配りすることが目的の事業ではございませんで、先ほど今回事業を実施する理由のところで少しお話をさせていただいた、補助額の増額が予定されているというのも一つありますけれども、もう１点。２つ目のご質問としまして、教員の３割が指導していきたいという回答をしているのですけれども、現在、土日に教員が部活動指導すると、特殊勤務手当というのが出るのですが。","voiceIndex":72,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"だから、ここはしっかり分けてやっていただきたいなと。これは要望で終わります。これはほとんど私的で、うちはちょうど１歳の子どもが誕生日を今月迎えて、来ているのかどうか確認していないのであれですけれども、そういうのがあるので、ぜひそこは現場の方たちの声も聞いていただきながら取り組んでいっていただきたいと思います。もし何かあったらあれですけれども、別になかったら、いいです。","respondent":"染谷子ども家庭支援センター長","answer":"カタログが届くときに既に持っているとか、定価というところにつきまして、まさに昨年度、子ども家庭支援センターにおいて家事用品購入支援事業をやらせていただいた際に、全く同じご意見をいただきまして、家電に関しては市場価格が結構大きく動く部分があるかと思いますので。","voiceIndex":75,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"今、ほかの委員がたくさん質問したので、私からは小さいところの確認と要望なのですけれども、バースデーサポートで、今お話があったギフトなのですが、これは、１月の補正予算で品川区出産・子育て応援給付金事業のところで使っていた、東京都の専用サイトを使った電子クーポンみたいなのとはまた違ったところということですよね。","respondent":"染谷子ども家庭支援センター長、立木保育課長","answer":"バースデーサポートにおきまして、ギフトのサイトの考え方ですけれども、こちらにつきましては、東京都としましても、バースデーサポート事業は各区・自治体の独自事業であるということから、ギフトサイトの構築に関しましては。東京都の補助金としては区立も対象としているところですけれども、先ほど申し上げたとおり、午睡のときのＳＩＤＳチェックをする体制ですとか、園外保育のときの体制ですとか、そういったところを考えた上で。","voiceIndex":79,"id":"exchange-014"},{"speaker":"せお委員","kind":"提案","question":"児童の安全のところは、区立もこれからいろいろなことを検討してくださるだろうなとは思っているのですけれども、区立も、施設の事業者が違っていても子どもの事故は起こるので、今まで起こっていないかもしれないですが、区立でもいろいろなお話を聞いたりするので、私も今まで子どもの事故のことで様々提案させていただいたのですけれども、今まで起こったインシデントだったりアクシデントだったり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私からは、部活動のことをお聞きしたいと思います。それで、これは申請、審議の後に、これから、スケジュール的にいうと、８月下旬に募集・周知があって、１０月から活動を実施したい旨の記載がありますけれども、あらかじめ競技会場というのですか、やる場所は、ホッケーだったら大井ホッケー競技場なのかなと私は個人的に考えていますが、具体的に今決まっているのであれば、教えていただきたいと思います。","respondent":"中谷指導課長","answer":"それから最後に、地域連携のところでサッカーがないのはなぜかというご質問だったのですけれども、こちらにつきましては、前年度に各学校の校長から、１校１取組以上の地域連携をやっていこうということで、学校が選んだものになっております。","voiceIndex":87,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"会場のことなのですけれども、区としては、今、この辺を考えているとか、そういう主だったところというのがあれば教えていただきたい。今後の協議で、会議体で何か示していくだろうと思いますが、その会議体の中で示していくのか、あるいは教育委員会のほうでこういうところを会場として想定していますよみたいな、そういうのがある程度お考えがあるのであれば、教えていただきたいと思います。","respondent":"中谷指導課長","answer":"そういった中で、まずはホッケーとラグビーという競技をやるということも含めての協議会でのご提案があった後に、どういった場所でやっていくかといった決定になっていくかなと考えていますので、ご指摘いただいたとおり。","voiceIndex":89,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこの関係をどういうふうに捉えて、部活動を、地域との関わりという意味で、移行と連携含めて、どういうふうに進めていこうとお考えになっているかというのが一つと、もう一つは、移行のほうは大きな話になるので、進めていっていただきたいと思うので、それはいいのですけれども、そうすると、民間事業者に委託と書いてあるのですが、これはやはり何らかのスポーツの教室を運営しているところとか。","respondent":"中谷指導課長","answer":"それから最後のご質問で、民間委託の３０名の活動の在り方ですけれども、こちらは９つの中学校と６つの義務教育学校全てのお子さん、そして小学校３１校全てにご案内をかけていく予定ですので、必然的に他校のお子さんたちと活動するというような形態になっております。","voiceIndex":92,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後に、これは要望というか、それについて一つだけ。","respondent":"中谷指導課長","answer":"ご指摘いただいた各学校の取組、現在は、今こちらにご覧いただいているような取組からスタートしたというところになっておりますが、こちらも増えていくような取組として、教育委員会として支援していきたいと考えています。","voiceIndex":96,"id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"やはりこういうことに取り組んだら、その後、効果の測定はやるべきだと思っておりまして、先ほども言いましたけれども、事故報告書を毎年きちんとまとめていただいていて、そういうこともどういうふうに、こういうことに取り組んだ結果、ヒヤリハットも含めて、減っていく方向であるべきだと思うのですが、そういうことも含めると、こういう補正予算にて、事業が拡充したのを機会に。","respondent":"石井保育支援課長","answer":"先ほど委員からご指摘ございました、ＩＣＴの活用をすれば全て事故が防げるというものではなく、現場の保育士がきちんとマニュアルに沿って安全を確認すること、これが一番であるという認識は我々も持ってあります。","voiceIndex":98,"id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"部活動の地域移行なのですけれども、いろいろと皆さんからもご質問が出て、少しずつ理解はできたつもりなのですが、そもそもこのアンケートが、２校でしたか、設問の仕方もどうしてこういうふうになったのかなと思うのですけれども、部活動に加入している生徒の５８％が、現在の部活動とは別に、興味がある活動を週１回程度できた場合、参加したいと考えているかというような設定だと。","respondent":"中谷指導課長","answer":"これがいかに達成できたかということを、児童・生徒だったり、保護者の方だったり、校区教育協働委員会であったり、教員であったり、要は主体となるお子さんだけでなく、関係してくださっている皆様にもアンケートをとっていく形で。","voiceIndex":100,"id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"だから、やはり中学生当事者が部活動に何を求めているかということをしっかり確認して、地域移行を進めていっていただきたいなと思っています。最後、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成ですが、児童福祉費のほうは、いずれも児童の安全対策、孤立化防止など、子育て支援につながる内容です。教育総務費のほうは、協議会の設置等、地域に新たな選択肢を模索する経費だということなのですけれども、地域移行に当たっては、生徒も含め、関係者で十分話し合って、現在の部活のメリットを維持しながら検討を進めてほしいと、改めて要望して、賛成とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-023"}]},{"id":"topic-03","title":"第４４号議案、品川区立幼稚園条例等の一部を改正する条例","agenda":"第４４号議案、品川区立幼稚園条例等の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれ文言整理だと思うのですけれども、担当大臣の表記が変わっていますが、このことで、区として条例を通して提供する事業が変わるとか、そういったことがあるのかないのか、それぞれ伺いたいなと思います。","respondent":"石井保育支援課長","answer":"今ご質問ございました、今回、担当大臣が替わることによって、事業の内容等が変更になることはございません。","voiceIndex":120,"id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認したいのですけれども、改正する条例が１２ありまして、ここで品川区が持っている区立の、いわゆる名称ぷりすくーるですが、品川区立就学前乳幼児教育施設条例がどうなるかというのがないのですけれども、そこについてはどういう状況なのでしょうか。","respondent":"今井保育教育運営担当課長","answer":"ぷりすくーるの条例もありますけれども、今回の条例改正の中には、ぷりすくーるの条例改正は含まないと判断させていただいたものです。","voiceIndex":125,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"含まないということは、今の文言整理とかは品川区立就学前乳幼児教育施設条例に関わりがないということでよろしいでしょうか。関わりがないからここの１２の中に入っていないということですか。一つは保育部門があって、もう一つはいわゆる通称幼稚園があるのですけれども、そこに変更がないということでよろしいでしょうか。","respondent":"今井保育教育運営担当課長、立木保育課長","answer":"今、提案しています条例改正の内容に基づきまして、ぷりすくーるの条例の中で改正する部分というのは、ないということで所管として判断させていただいているものです。今回の国の法律改正に伴う条文改正と突き合わせた結果、ぷりすくーるの関係の条例に関しましては、該当する条文、当たっているものがないということで、今回は改正の必要がないです。","voiceIndex":127,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問","question":"分かりました。該当するところがないので、こちらの条例は変えなくて済んでいるということですね。あえて変える必要はないというか、要するに、今、３番目にある品川区保育の実施等に関する条例が変わるので、そこが変わったのにぷりすくーるの条例もそこを適用しますからということだから、あえて断る必要はないということですか。ぷりすくーるの条例を変える必要がないということでよろしいですか。","respondent":"今井保育教育運営担当課長","answer":"失礼いたしました。委員のおっしゃるとおりでございまして、今回の条例の中に含まれております保育所に関する条例の部分を適用するということで、ぷりすくーるの条例については、今回は改正の必要がないということで判断させていただいたものです。","voiceIndex":130,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成ですが、態度表明するのですが、共産党としては子ども家庭庁設置法自体には反対した立場なのですけれども、その理由は、岸田政権が、子どもの権利条約や国連子どもの権利委員会の勧告に真摯に向き合わずに、これまでの教育施策の検証や反省を示すことがなかったという点、あと、子ども施策の予算も具体的に示されなかった点、かつ、子育ての自己責任・家庭責任を求めかねない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-028"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、西本たか子区議の区立幼稚園の廃園ではなく発展をみたいな質問があったと思うのですけれども、ここでも１点お伺いしたいのが、子ども未来部で決定したというのは、区立幼稚園の廃止の方針であって、廃止を決定したわけではないという点と、廃止の決定の権限というのはあくまで教育委員会にあるという、以上２点、改めて確認させていただきたいと思います。その点、いかがかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"意見","question":"学校給食の無償化で、未納の方がいらっしゃって、学校が徴収するという話だったのですけれども、現時点でどれぐらいの未納の金額があり、どのくらいの人数がいるかということと、今後、督促を具体的にどういうふうにしていくのかということをお尋ねします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"意見","question":"西本議員です。すみません。それからもう一つは、すまいるスクールの仕出し弁当の試行ですけれども、これも西本議員だと思うのですが、試行を進めていかれるということは分かったのですが、第一日野小学校で行われるということなのですが、幾つかの条件があったと思うのですけれども、どういうことがクリアされてそちらの小学校で進めていこうということになったのかということをお尋ねします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":42803,"voices":154}},{"id":"r05-20230703-5","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"総務委員会","time":"午前１０時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"まとめて伺います。この議案に限らず、夏場の公共工事全般についてですけれども、熱中症対策です。工期や工法の中、また積算の中でも、様々対応が盛り込まれているとは以前から伺っておりますけれども、今年の夏の暑さもかなり尋常ではないと思いますので、事故のないように進めていただきたいのですが、熱中症対策について、全般的な対応策をご説明いただきたいと思います。","respondent":"小林施設整備課長","answer":"ご質問２点です。１点目ですが、特別養護老人ホームを運営しながら対応する工夫という点ですけれども、今回荏原保健センター、健康センターにつきましては、旧第一日野小学校の跡地に仮移転いたします。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"特別養護老人ホームについては、居ながら工事となりますので、運営者と密に連絡を取って進めていただきたいと思います。熱中症対策については、区のほうも巡回するというお話ですけれども、元請、下請、２次下請、様々な方がいらっしゃいますので、皆さんの健康がしっかり保障されるように、しっかり連携を取っていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"辞退のところで、配置予定技術者の配置が困難になったということで、この配置基準の見直しをということは、以前から、大分皆さんのところにもお話が行っていると思うのだけれども、特に今人がいなくてという話が多くて、各事業者が必ずその、全てべったりというか、少し掛け持ちでも日にちが分かれればどうなど、いろいろ話があると思うのですが。","respondent":"佐藤（聡）経理課長","answer":"今ほど委員のご指摘があったところは、今回のこの資料の電気設備工事の辞退理由のところ、配置予定技術者の配置が困難というところかと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"基本的なところをお聞きしたいのですが、この荏原保健センター、現在のものは平成９年２月にできたと記載されていますけれども、今回、大規模改修工事に至った根本的な理由というものは何なのでしょうか。それで、実際年数的に、本来ならまだ大規模改修に至るまでにはいかないと思われるのですが、その辺について少しお聞かせください。","respondent":"小林施設整備課長","answer":"建物の、いわゆる躯体、構造体につきましては、当然ながら２５年で耐力が落ちるものではございませんが、どちらかというと設備であったり、内装材だったり、そういったところの劣化によって今回大規模改修につながったです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"空調や電気設備、２０年、２５年というスパンだと思うのですけれども、現在もそうです、当時もそうだったかもしれませんが、できるだけ、やはり耐用年数が長くなるような、やはり工法ですか、そのようなこともできると思いますし、機器に関しても、やはりこれだけの費用をかけてまた入れ替えるということはどのようなものなのかなと思うので、本来なら、今課長がお話ししたように、やはり２０年。","respondent":"小林施設整備課長","answer":"当然費用につきましても、今回何か特殊な機器を入れるものではなく、当然汎用品を用いながら、今回設計のほう、それから工事を進めていくところですので、そのようなところをしっかり見極めながら、特殊なものを使わないなどというところも工夫しながら。","voiceIndex":14,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"この改修に当たって、防災面で気をつけていることというか、新しく変わることなどがありましたら教えていただきたいということと、あと、災害発生時にエレベーターなどが止まってしまったりなど、そのようなことが起きたりすると思うのですが、例えば太陽光発電とか、蓄電池でためてとか、分からないですけれども、何かいろいろな方法などを考えていらっしゃるのかなと思いまして。","respondent":"小林施設整備課長","answer":"災害時ＢＣＰの対応ですが、概要等にも記載されておりますように、今回太陽光発電のほうを設置しています。","voiceIndex":17,"id":"exchange-006"}]},{"id":"topic-02","title":"第６２号議案、片袖机他の買入れ","agenda":"第６２号議案、片袖机他の買入れ","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"学校運営用品・製品一式ということですけれども、これまではあまりこのような議案を見た覚えがなくて、今までの契約の仕方と今回とどのように変えたのか、その狙いや目的についてもご説明いただければと思います。","respondent":"柏木学務課長","answer":"というのも、納品の関係などという部分がありますので、どうしても分けざるを得ないという部分がございましたが、今回につきましては、改めて、やはり同じ物品については同じ契約の中でするべきだろうというお話もございまして、今回教職員用で使う物品について。","voiceIndex":50,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"今まで別々だったものを、今回まとめてということですけれども、それについての効果をどのように評価しているのかという点を改めて伺います。それと、今まで別々だったものをまとめてとなると、逆にそれぞれの教室、先生方が必要なものがどこまで希望どおり通るのか、逆にそこが、考慮して選定したとは書いてあるものの、物品の引取りとか、把握とか、どのように進められたのかも併せて伺いたいです。","respondent":"佐藤（聡）経理課長、柏木学務課長","answer":"幾らぐらい減額になったかというところは、なかなか難しいところではありますが、一般的にそのように申し上げられると思います。購入する際、今回契約する前にも最終的な確認ということで担当者が学校のほうに行きまして、学校の職員と一緒に必要なものを精査しているという状況になります。","voiceIndex":52,"id":"exchange-008"},{"speaker":"松本委員","kind":"質問・要望","question":"もう１点ですけれども、多分数を見ると、児童が使うものは入っていないのかなと思うのですけれども、逆にそちら側、児童が使うものについては一括してやらなかったのかなと思うのと、児童が使う、数としては児童が使うものが多くなると思うのですけれども、この辺りはどのように購入されているのかお伺いいたします。","respondent":"佐藤（聡）経理課長、柏木学務課長","answer":"ただ、学務課長からもありましたけれども、それぞれ納品の時期について調整しなければいけないですとか、そういったところもありますので、今後も物品の入札金額については、そういった視点も持って研究していきたいと考えています。数としては足りるのですが、当然壊れている、あと児童数の増加分につきましては、こちらは今回のこのような契約ではなくて、毎年年度末に、老朽取替えと児童生徒用の増加分の予算を措置していますので、そちらのほうで対応しています。","voiceIndex":56,"id":"exchange-009"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。そこについて、今回新たにこれだけのものを買うということになっているので、前のものを引き継ぐことをもう少し頑張っていただいて予算を下げるとか、いろいろとできる部分も場合によってはあるのかなと思いますので、今回それが適切かどうかということは特に申し上げませんけれども、使えるものはできるだけ使っていただくということでお願いしたいなと思います。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"それをどうか。だからそれを分離で今までやってきているというと、学校だって校長先生の権限で幾らまでといったら、それだったら地元で使ってくださいということがあったわけだから、今もあるのだけれども、それをどうしていくのだということだって考えられるので、まさにこのようなメーカーがあるような物品、これが一番分かりやすいので、どうされていくのかなという考えをお持ちなのかと聞きたいです。","respondent":"佐藤（聡）経理課長","answer":"金額面でということですけれども、これは入札という形式を取っている以上、それぞれの事業者がどういった形で仕入れるかというところは、こちらからは申し上げないところですので、そういった健全な価格競争の中で図られるものだというふうに考えております。","voiceIndex":61,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、ごめんなさい。私が不勉強だからごめんなさい。ここだけ。よく予定価格というものを出しますよね。予定価格というのは、このような物品は出すのですか、出さないのですか。今の話だと、一般競争入札だから、もちろん入札の制度は分かるけれども、予定価格を出すといったら、どういう積算で予定、だからこの物品の金額は何％とすぐ出てきてしまうではないですか。その辺のやり方を教えてほしいです。","respondent":"佐藤（聡）経理課長","answer":"予定価格の取り方ですけれども、いわゆる工事であると積算に基づいてやっておりますが、こういった物品でありますと、事業者等からの見積りを基にして、あとはこれまでの実績等を踏まえて、契約担当部署、経理課のほうで出しております。","voiceIndex":63,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"すみません。使えないわけではないのですが、新しく新校舎になれば、新しい設備を、そこに机を導入するということは分かるのですけれども、それはあれですか、そのまま今までのものは廃棄するのか、それとも、リサイクルなどのようなところに、業者にお渡しして売却等をするのか、それについて、もし分かれば教えてください。","respondent":"佐藤（聡）経理課長、柏木学務課長","answer":"前段の何が何台というところですけれども、資料の５４ページのところの、片袖机５４台、あるいは少し飛びまして、会議用テーブル４６脚というところが主な内容です。移設しない物品の取扱いですが、基本は再利用ということを考えてございまして、まず各学校、ほかの学校等にもお声がけしまして、不用品の交換会ではないのですけれども、そのような形で、使うところがあればそちらのほうで活用すると。","voiceIndex":65,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"買入れ品目については、すみません、見落としてしまいました。ちょっと１点だけ、要望ですが、今小学校、中学校でタブレットを使っていますよね。そうすると机が狭いのです。それを置くと。それにノートを置いて、また教科書類も置いている。その辺も、もし今後検討していただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-014"},{"speaker":"塚本副委員長","kind":"確認","question":"今回の物品購入、一括で同じものは同じ、同類で購入しましょうという話になったという説明が最初にあったのですけれども、１点ちょっと確認ですが、これは今回のケースに関してはそのような判断をしてそうしました。","respondent":"柏木学務課長","answer":"今回限りではなくて、今後につきましても、まとめられるものはまとめた形で契約していこうということで、内部では確認を取って、すみません、ちょっと文書等では確認していませんけれども、そのようなことでやっていくということでの確認は取れているものです。","voiceIndex":70,"id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問","question":"こういったことというのは、もしかしたらよその所管にもあったりするのかもしれないと考えたり、所管外の話はあれですけれども、そのようなことでいうと、何かきちんとした客観性や明文化したものがあったほうがいいのではないかなと思うのですが、その辺まで至っていないところの話はどうしてかということを最後にお聞きしたい。","respondent":"佐藤（聡）経理課長","answer":"は具体的に、納品の時期を別々にしないと難しいですとか、あるいは同じ事業者だと、例えば給食室の設備ですとか、購入できないですとか、そういった細かい調整がありますので、全部が全部というわけではなくて、所管課と経理課のほうで調整してやってまいりますので。","voiceIndex":72,"id":"exchange-016"}]},{"id":"topic-03","title":"第５４号議案、総合体育館および日野学園空調設備改修工事請負契約","agenda":"第５４号議案、総合体育館および日野学園空調設備改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"もうすごい金額がかかっているではないですか。これはある意味で、私は社会資本だと思うのですが、これは国からか、都からかは分からないですけれども、しっかりその分は、区というよりも、やはり国民の社会資本、子どもたちの社会資本に対する設備なわけだから、更新するわけだから、それ相当の額というものはきちんともらえているのですか。どれぐらいの金額を、実際区としてはもらえるのでしょうか。","respondent":"森学校施設担当課長","answer":"今のご質問ですけれども、大体国、都からの補助金はおよそ１０％程度ということで、ほぼほぼ区の予算を使って改築をするということになってあります。要望といたしまして、国、都のほうには、もっと補助金を上げてほしいというように上げてはあります。","voiceIndex":99,"id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"だから今後、やはり２３区もしっかり心を一つにして、都や国にしっかりお金を出すようにしてほしいと私は思うのです。だって法人税は取られて、固定資産税取られて、所得税取られて、それでそちらにいっぱいお金がたまっているはずです。行っているはずです。１０％では今後２３区でも、やはりほかの自治体でも大変だと思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-018"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今、工事金額変更という、契約金額変更というお話です。国でも、都でも、積算の段階でそのようにしなさいという話です。逆に物価が下がったときに、今度逆スライド条項というものもやはりつくるべきではないかなと思うのです。上げるときだけ上げて、下げるときは一切そのような条項がないということは、私は不思議だと思うのですが、その辺、もし何かご見解がありましたら教えてください。","respondent":"佐藤（聡）経理課長","answer":"今申し上げた第２５条の中身は、インフレーションまたはデフレーションということを言っておりますので、今後の日本経済の中でデフレーションというような事態になれば、具体的な手続について、国のほうも検討するということかなとは考えますけれども。","voiceIndex":133,"id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"意見だけですが、私が総務に来て、まず国全体も経済がデフレになっていたと思うのですが、そのときにも一切下がったということはなかったです。それでちょっと申し上げた次第です。今後、どのような方向性に対して対応するか、私は見ていきたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"例えば４月２８日よりもう少し待っていれば、これが２.７７％になるのか、２.８８％になるのか、それとも、いやいや、そこまで待ってしまうと影響額が大変で、現場の影響もあるからこの辺の日にちで見たのか、その日にちというのは、いや、これぐらいが今取りあえず平均かなという判断でこのような日にちが決まってくるのか、ちょっとそこの考え方を、考え方というか。","respondent":"森学校施設担当課長","answer":"おっしゃるとおり、上がっていく基調の場合もあるのですけれども、期日が過ぎれば過ぎるほど工事が完了していってしまいまして、インフレスライドの対象にならないということになりますので、そのバランスを業者と区のほうで見ながら。","voiceIndex":137,"id":"exchange-021"}]},{"id":"topic-05","title":"専決処分の報告について（報告第２４号）","agenda":"専決処分の報告について（報告第２４号）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３点目、この資料の真ん中の「パートナーシップ関係とは」というところの３行目に、任命権者が証明書等により確認できた関係と書いてあるのですけれども、これは東京都パートナーシップ宣誓制度でなくてもいいのか、それとも東京都パートナーシップ宣誓制度に限定した任命権者となると東京都知事なのか、ちょっとここが制度上よく分からなかったので、ご説明いただきたいと思います。","respondent":"崎村人事課長","answer":"全国の実施状況について、特に手元で調べているところではないですけれども、全国でもそういったパートナーシップ関係の宣誓制度というものをやられている自治体はあるかと思うのですが、そういった給与の部分、職員の給与等についてやっているというのは。","voiceIndex":146,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ民間企業にも波及していただきたいと私は願っているのですけれども、品川区として、例えばこのような取組を進めておりますと。品川区独自のパートナーシップ宣誓制度をつくっていくと、そのような方向にも、これを機に進めていただきたいと思うのですけれども、既に答弁いただいていますが、現状ではどうなのか、改めて伺いたいと思います。","respondent":"加島人権啓発課長","answer":"２点目の区独自のパートナーシップ制度をつくってはどうかというところですけれども、こちらにつきましては、東京都の証明書の中の特記事項に子どもの名前を記載することができまして、子どもに関する困り事にも対応していること、また、東京都の対象要件が。","voiceIndex":148,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"ということは、民間企業への波及効果ということですけれども、性的マイノリティの、特に当事者の方々を中心としたこの取組が、社会や、その姿を近年大きく動かしていると思います。今回品川区や東京の各自治体もそれについていくということですけれども、ぜひ様々な自治体間で交流とか、また、企業との交流の機会の際には、こうした視点を広げていただけたらと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-024"},{"speaker":"松本委員","kind":"質問・要望","question":"それで少しお伺いしたいのですけれども、東京都パートナーシップ宣誓制度ですが、これ見た感じ、一緒に同居している必要があるかどうかということを、どうもあまり問題視していない、要件として挙げていないようにお見受けするのですけれども、例えば類似のものでいったら事実婚があるかと思います。お願いいたします。","respondent":"崎村人事課長","answer":"今ご説明させていただいたのは、パートナーシップ関係の相手方を配偶者と同様に認める際に、パートナーシップ宣誓制度の証明書、それを必要とするといったお話をさせていただきました。","voiceIndex":152,"id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"確認ですけれども、入り口のところでこれは使うけれども、その後の実態的な審査というものはまた別にやられるということでよろしいかというところを、確認させていただきたいと思います。もう１点ですけれども、先ほど中塚委員からもありましたが、証明書等のところの等です。","respondent":"崎村人事課長","answer":"委員からお話がありましたとおり、証明書以外のものでも、受給する相手方なのかというところはしっかりと調べるようにしておりますので、そこについては、しっかり人事課として取組んでまいります。","voiceIndex":154,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお願いだけしておきます。多分人事課長は大変かもしれませんが、概要の４行、上４行がポイントで、それと東京都パートナーシップ宣誓制度があった４行ですけれども、これは職員なので、ぜひ性善説で、あとはポジティブに、ネガティブな考えは持たずに、職員をぜひ信じていただいて、ポジティブと性善説でやっていただきたいということだけお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-027"},{"speaker":"塚本副委員長","kind":"質問","question":"１点教えてほしいのですけれども、これは大分このような制度も進んできて、世の中でＬＧＢＴなど、そのようなことについての理解が深まってきていると思いますが、やはり中には自分が性的マイノリティだということを言わずに、だけれどもこの制度は利用したい、このような方々がまだいらっしゃっても不思議ではないかなと思うのですけれども、そのような意味で、いわゆる一般的な職場とか。","respondent":"崎村人事課長","answer":"職場に知られずということは、なかなかこの申請をする際に、やはり上長の確認を取った上で、本人から人事課のほうに申請をしていただくということになりますので、職場全員に知られることはないですけれども、やはり、例えば一職員であれば係長ですとか、課長が。","voiceIndex":159,"id":"exchange-028"},{"speaker":"塚本副委員長","kind":"意見","question":"分かりました。これから始まる制度でありますので、どうしてもそういった弊害のようなことが運用の中で出てくるところもあるかと思います。一定程度、これは守秘義務というものはもちろん守られるべきものなので、なされるのが前提だとは思いますけれども、その上でまた、そういったことについてもよく注意していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":161,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"すみません、最後に。そうしないと、ここは言ってもいいかなと思っていたところが、実は言ったら駄目だった場合に、上長の方も後々大変な目に遭ってしまうので、改めてここのガイドラインを整理していただきたいなと思いますが、この点、最後よろしくお願いします。","respondent":"崎村人事課長","answer":"基本的にはそういった個人情報といいますか、先ほど人権啓発課長のお話もありましたが、アウティングにつながるようなものになりますので、そういった情報を上長が得たからといって、周りの職員に簡単に、簡単にというか、勝手にお話しするということは。","voiceIndex":163,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"なるほどなと思いまして、今、人事課長のほうからハラスメントに当たるということで、管理職も含めて徹底するというお話があって、それはぜひそう進めていただきたいと思うのですけれども、結婚もあれば離婚もあるわけで、パートナーシップも結ぶこともあれば解消されることもあるわけで、そこに性差がないことは今回進んだものの、個々人の生き方という面では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほども何度も言いましたけれども、性善説で、それでポジティブに、ネガティブな話をしていけば幾らでも話が、このようなものは出てくるような気がしてならないので、このような事例があった、どういうこと、これが今言ったあれになるのか、何になるのか分からないですが、そのようなことが必ず起きてくると、こういうネガティブなことがボンボン出てくると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-032"},{"speaker":"澤田委員","kind":"質問・要望","question":"先ほどカミングアウトの件についてお話があったと思うのですが、一部管理職の方たちなどがほかの人たちに広めないように管理していく、管理していくというか、お話ししていくということですけれども、できればカミングアウトをすることによって差別されないような環境づくりというか、職員の方たちが、それが当たり前。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-033"}]},{"id":"topic-06","title":"第３７号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第３７号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ご説明ありがとうございました。資料にある、この廃止する特例措置の内容ですけれども、職員の方がＰＣＲ検査をしたり、その検体を運んだり、また検体に接して行う業務などなど、今まで手当が支給されておりましたが、現状２類から５類に変わったことで、この業務というものは、今あるのかないのか、そこのご説明をいただきたいと思います。","respondent":"崎村人事課長","answer":"具体的に、例えばＰＣＲ検査の対応業務ですとか、ＰＣＲ検査センターが区にも設置されましたけれども、この受付の業務ですとか、ＰＣＲ検査を実施した際にその検体を運ぶ業務といったものは、現在行われていないところです。","voiceIndex":202,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"現在は５類に変わったことで、行われていないということなので、もちろん賛成はいたしますけれども、コロナの感染状況については、今沖縄がまた増え始めていると。定点観測も少し上昇傾向だということが指摘されておりますので、コロナなのか、また別の感染症がはやるのか、そこはもちろんよく分からないですが、十分な警戒はしていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-035"}]},{"id":"topic-07","title":"第４０号議案、職員の高齢者部分休業に関する条例","agenda":"第４０号議案、職員の高齢者部分休業に関する条例","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"職員の高齢者部分休業ということですけれども、取得する際は、その取得の理由というものが問われるのか問われないのか、その点を確認させてください。それと、この際なので伺いたかったのですけれども、定年が引き上がるということは、職員の方にとってうれしいことなのですか。","respondent":"崎村人事課長","answer":"ただ一方で、この定年年齢が引上げになると同時に、定年前再任用短時間制度というものができまして、６０歳を超えた方が、定年年齢を迎える前に早期に退職して、以降６５歳まで再任用として働いていただけるという制度もありますので。","voiceIndex":218,"id":"exchange-036"}]},{"id":"topic-08","title":"第４１号議案、品川区特別区税条例の一部を改正する条例","agenda":"第４１号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"キックボードですけれども、テレビを見たりなどして、７月１日から法律が変わって、ヘルメットだったり、どこを通るかだったり、免許証だったり、いろいろ変わったという報道があって、やはりすり抜けるように走っているのが、事故に遭わないかどうか、事故の原因になるのではないかなど、それは非常に心配なのですけれども、今回年２,０００円というところで、安全対策というのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に自転車の方がけがをしたり、死亡したり、重大事故につながるということがずっと傾向としてあるわけで、それをまたキックボードというもので、やはり車に巻き込まれると、けがをされるのはキックボードの方だと思いますので、ぜひとも販売会社はもちろんのこと、交通安全の課とも十分連携して、事故のないように、巻き込まれることのないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは国で決めたのでしょうが、なぜこれを許可したのか、私には非常に疑問なのですが、もう既に昨年３５人ほど死亡者が出ているということで、この大都会でこのような車が運行する、使われるということには、私は非常に疑問を感じますので、所管は違いますけれども、区としてできるだけけがや事故が起きないような、何か対策は取っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２点だけ伺います。品川区の中で。ということを教えていただきたい。事業者については。だからこれ、造成と来ているのだけれども、この辺の法的な部分があるので、これ区で出てきてどうです、延長してと、それに何か文句をつけているようで悪いのですが、これは一体どう捉えてどのような現実が起きているかということを理解されているのかなということを教えていただきたい。区で考えるところがあれば。","respondent":"提坂税務課長、遠藤財政課長","answer":"〔同日後刻に「４,５９０万円」と答弁訂正あり〕具体的な活用予定としましては、早川町のマウントしながわ活用事業や住宅改善工事助成、国産材を活用する工事の助成や学校改築推進経費の国産材活用と。使途につきましては、こちらは必ずホームページで公開するという形になっておりますので、現状、令和３年度まで公開させていただいていまして、例えば学校改築や児童相談所の改築など。","voiceIndex":240,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"分かりました。それから、先ほど言った土地建物、これ、もう１回私も勉強しますが、多分このようなことをやっているから、土地は消費税がないから、いろいろなこういう造成だというような話になってきて、造成のお金がどうのこうのとか出てきてしまうのです。これは確かにいいのだけれども、優良住宅はいいのですが、これはもう１回私も勉強させていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"第４１号議案、品川区特別区税条例の一部を改正する条例に反対いたします。理由を述べします。最も環境負荷を与えている法人にこそ、第一義的に課税をすべきだと思います。軽自動車税のグリーン化特例の延長など、こうしたものは基本的には進めていただきたいと思いますが、全体としては反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-042"}]},{"id":"topic-09","title":"令和５年請願第５号 安保関連３文書・防衛財源確保法に反対する意見書提出に関する請願","agenda":"令和５年請願第５号 安保関連３文書・防衛財源確保法に反対する意見書提出に関する請願","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今、委員長からも委員間討議をとのお話ですので、ぜひ率直な意見を交わし合えたらと思います。その前に、１点だけ品川区に確認ですけれども、いわゆる安保３文書、反撃能力、５年間で４３兆円、ＧＤＰ比２％の軍事費増と。こうした流れは、非核平和都市品川宣言で掲げている恒久平和に反する事態だと私は思うのですが、品川区の認識だけ確認させてください。","respondent":"せりざわ委員長、勝亦総務課長","answer":"冒頭に説明したとおりでありますので、基本は委員間討議で行っていただければと思いますが、区としてご説明が特段あれば、ご意見をお願いします。今ご質問ありました防衛の関係の安保３文書等々につきましては、国で検討する課題かと存じます。","voiceIndex":290,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"品川区に、恒久平和に反する事態とは思わないのかと伺いましたが、結局、国が考えることで、区としては態度表明はないということだと思います。だから違うのだ、必要なのだという話を私は伺いました。私なりに考えを述べさせていただきましたけれども、冒頭、委員長からも委員間討議でという話もありましたので、皆さんのお考えを聞かせていただけたらうれしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":293,"id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"今回の請願は、安保関連３文書・防衛財源確保法に反対するという趣旨の話ですが、防衛とか外交については、本来はこの品川区議会ではなくて、やはり国会の場で、私は議論していただく問題だと考えております。財源、特に軍拡財源のための増税はしないと、国のほうでも岸田総理が話しているわけですから、私は今、この状況を見ますと、今回の意見書を提出することはふさわしくないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"意見","question":"この請願については、意見書は、本来これは国の議論であって、出すべき話ではないし、区議会でどうという話ではないけれども、先ほど委員間の議論、議員同士のという話があるから、あくまでも私個人の見解を言います。だけれども、しっかり我々の国を守るには、今この状況に置かれている中で、私は、安保関連３文書はしっかり行っていくべきだと個人的には思っている。態度まで言ってしまったかな。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":297,"id":"exchange-046"},{"speaker":"中塚委員","kind":"意見","question":"こういうテーマは国会でやるべきで、区議会でやるべきではないという意見がありましたけれども、それは一つの意見だと受け止めたにしても、区議会議員は区民から選挙で選ばれて、区政に関することも、時には国に関することもしっかり議論して、結論に違いはあるにしても、議論をする、意見を述べるということは、区民から負託されている我々の大事な役割ではないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":299,"id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、皆さんぜひ、中塚委員が今そうおっしゃって、答えているのは私ぐらいだけれども、私は別に区議会でやるというのは、この議会でやるのは違うと思っているから、さっきも何度も、私の個人的な見解を言うと。外国人参政権の話も、私は、別にホームページだろうと何だろうと、反対だとしっかり言っている。国境離島を守るのだと、きちんと言っている。だから、いいのではないか。それは議員として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":300,"id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"紹介議員がついているところをどう考えるか、そして区民から出てきたものに対して、区議会議員としてしっかりと議論するべきということは、私もそのとおりだと考えていますので、意見を申し上げすると、果たして、そもそも軍拡という表現も使われておりますが、私ども議員の立場としては、国会議員は国民を守るということが第一義でありましょうけれども、区議会議員としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":302,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"なかなか議会という場で絡まって話ができない雰囲気の中で、３人が意見を表明してくれたことには、敬意を表したいと思います。日本を守るために、防衛費を増やすことには賛成だという意見がありましたけれども、それが果たして戦争を回避すること、また憲法９条でいえば戦争放棄それ自身につながるのかと私は思います。ですから、冒頭、抑止力では平和をつくれないと。話せば分かる国だけではないですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"意見","question":"中塚委員に誤解だけ解いてほしいのは、私は何度も言っているけれども、我々は区議会議員であって、さっき、区議会議員の仕事はどこまでというのもあると。国会議員の仕事とは何か。もちろん、これは国会議員の仕事だ。それは内部的な話。しかし、先ほど話が出たように、区民の皆さんからこういう請願が出てきているので、あくまで私個人の見解はこうだと。そこだけはよく理解してほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":305,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"少なくともこの請願については、意見書を出してほしいという請願で、区議会で議論して意見書を出すという仕組みがあるわけだから、こうして議論していると思います。もう私もあまりごちゃごちゃ言いませんから、ぜひ、ご発言されていない各委員の意見を聞かせていただけたら伺いたいし、少なくとも戦争という惨禍を繰り返してはいけないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-052"},{"speaker":"須貝委員","kind":"質問","question":"ただ、ここまで３原則云々、それから防衛財源確保云々とか書いてありますが、今のところ政府としたら、増税もしない方向で、財源をこれから切り詰めて、行革等をして、皆さんに負担をかけないようにして進んでいきますということを公言しているわけですから、それは、私は見守っていいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":307,"id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"区議会の役割のところが出ていますけれども、例えば、これは紹介議員で、議員がなられているわけですから、少し検討される際に考えていただきたいのが、防衛予算は必ずしも敵基地攻撃能力に限られているわけではない。私たちは区議ですから、区民の生命・安全を守っていくというのが重要かと思います。国連憲章を守るという流れがあったのに、侵略がなされた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":309,"id":"exchange-054"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出すでお願いします。不採択でお願いいたします。理由としては、私も戦争反対ですし、お気持ちはお察しいたしますが、国の政策ですし、一部を取り上げて、区で議論する立場にないため、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-055"},{"speaker":"塚本副委員長","kind":"意見","question":"理由は、安保関連３文書・防衛財源確保法に反対する意見書ということですけれども、国の専権事項といいますか、大事な安全保障政策であるということで、安全保障政策というのは、戦争か平和かといえば、もちろん平和ですけれども、現実的な近隣諸国との軍事的な緊張関係において、それに対する現実的な、防衛的な対処というのは、時に応じて、相手の脅威に応じて考えられ、なされていくべきだし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":313,"id":"exchange-056"},{"speaker":"大倉委員","kind":"意見","question":"そういった意味で、しっかりと日本をどう守っていくか、また区民をどう守っていくかというところは、国なら国で、区議会なら区議会で、しっかりと話し合っていくことが必要だと思いますが、先ほどからお話があるように、安全保障の部分とか、外交・防衛のところをどのようにしていくか、税金も含めてというお話がありましたが、まさにそうした観点から、しっかりと国の方でも話合いをして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":314,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、反対する意見書提出に賛成ということで、採択を求めたいと思います。もっと議論を深めたいと思うところもありますが、一言、相手国の軍事的脅威を理由に国民が不安を感じる、その気持ちは私も分かります。同じ地球上で、ロシアがウクライナに戦車で国境を渡って、罪のない民間人を殺すわけですから、こういうのを見たときに、不安だと思う国民の気持ちはよく分かります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":315,"id":"exchange-058"},{"speaker":"松本委員","kind":"質問・要望","question":"これは、本議会でもこれまでありますように、例えば選択的夫婦別姓の問題とか、離婚後の共同親権・共同養育の問題とか、そういうことについて、区民からご意見があったときに、全く議論しないかといったら、私はずっと議論してきた立場ですので、区民の方から国政について、区議会として要望を上げてほしいという話が出た場合には、積極的な議論があってもいいのかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"意見","question":"今のお話があったのだけれども、次のインボイスの話も、国でやっていることなので、これもきちんとこのように出てくれば、きちんと議題には上がってくるし、やるわけだから、別にそれは、安保のお話は先ほど言ったように、特に安保の話は国会議員がやる話であって、我々区議会の話ではないと私は思っているので、先ほど何度も言ったように、全てが違うと言っているわけではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":318,"id":"exchange-060"}]},{"id":"topic-10","title":"令和５年請願第９号 適格請求書等保存方式（インボイス制度）の実施延期を求める請願","agenda":"令和５年請願第９号 適格請求書等保存方式（インボイス制度）の実施延期を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど同様、私の意見を話して皆さんの意見も聞かせていただきたいと思いますが、まず、区に１点だけ伺います。インボイス実施延期を国に求める考えがあるのか、ないのかということと、区のほうでも、意見書採択を地方議会で進められているということですけれども、その議会の様子などは把握されているのか、そこだけ確認させてください。","respondent":"遠藤財政課長","answer":"売手の方が買手にきちんとした税率、それから税額を指示する、伝えるものだと認識していますので、こちらは国のほうで議論されると考えているところです。それから、ほかのところの議会の状況というところですが、私どもの方では、そのところまでは把握していないところです。","voiceIndex":324,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"そんなことは決してあってはいけないと思いますので、ぜひインボイス制度を、ここには実施中止を求めることと、私はそもそも反対ですから、反対は反対なのですけれども、せめて実施延期を求めるということは、少なくとも今、コロナ禍の下、物価高の下、必要だと思いますので、各委員におかれましては賛成していただくことと、委員長おっしゃるとおり、委員間討議ということもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-062"},{"speaker":"須貝委員","kind":"質問","question":"５００万の事業者のうち、１割しかまだ登録していない。ですが、今回の請願に対しては、インボイス制度の実施を延期するということですから、現在のこの制度を国が進めていくということならば、もうしばらく、それが１年なのか２年なのか分かりませんが、今の制度だったら延期して、しっかり多くの個人事業主、国民から理解されるようになるまで、私は待つべきだと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":328,"id":"exchange-063"},{"speaker":"松本委員","kind":"質問・要望","question":"これも国に対するものですけれども、先ほど須貝委員からお話があったように、そもそも免税事業者というもの自体が、制度の始まりのところからいろいろと問題があった制度だと思います。その上で、今回、延期・中止を求める方々の声があるというのも事実だと思うのですけれども、私もアニメや漫画が好きなので、声優の岡本さんの会見とかは伺わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":330,"id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"意見","question":"理由も言ったほうがいいか。討議だから。だけれども、本来は全員を課税対象にするべきだったのだろうと。それでないと現実は使えない。その人たちをどうしていくのかという問題もあったりする。こういうことは、課税業者も免税の方も、副業でそういうことをやったり、少しお手伝いをしている方々も、全てこれを今やっているので、これは必ずどちらとも、私はやるべき。そういう考えなので、請願は不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":332,"id":"exchange-065"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。理由としましては、インボイス制度は国としての政策であることから、区議会が決める権限はないですし、国で議論されるべきだからです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":334,"id":"exchange-066"},{"speaker":"塚本副委員長","kind":"意見","question":"本日結論を出します。結論は、不採択でお願いいたします。今後も経過措置ということで、免税業者の方々の仕入れの８０％控除というのが３年間かな、あと、そこから先３年間は、５０％控除ということでの経過措置もされている中で、ここでまた延期というのは、いつまで延期なのかという話にもなりますので、これはやはり予定どおりすべきものと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":335,"id":"exchange-067"},{"speaker":"大倉委員","kind":"意見","question":"そういう意味では、ここに書かれている実施の延期ということでは、非常にタイミング的には、延期をする要素がかなり多くあるなというのを感じているところでありますし、こうなったときには、ぜひ区でもいろいろと手続とか、費用の面とかも工夫しながら応援していってほしいと思っているものの、実際、延期をしたほうがいいのかどうかは、状況はそろっているものの、延期も含めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":336,"id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということと、私は採択でお願いします。先ほど申したとおりですけれども、コロナの影響と、そこに物価上昇が加わり、そしてインボイス増税と。アニメやクリエーターを含めて、とてもではないけれども、廃業せざるを得ないという声が上がっている中、少なくとも実施は延期すると。私は中止してほしいと思います。それは一言述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":337,"id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、本日結論を出すということと、採択でお願いしたいと思います。品川区は小規模事業者と、それから一人親方という方がたくさん身近にいらっしゃる。そういう品川区です。今回、先ほどもありましたけれども、インボイス発行を求められない小さな会社もあるのですが、なかなかそれすら周知されていない現状を見ると、今回は国にしっかり言っていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":338,"id":"exchange-070"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、不採択と申し上げします。ただ延期だけ求めて、それで終わらせるというのも、私は少し無責任なのかなと。であれば、具体的にどのタイミングまでというところまで想定した上で、延期という話をしていかなければ、それは言いっ放しになってしまうと考えていますので、私どもとしては、不採択と申し上げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":339,"id":"exchange-071"},{"speaker":"大倉委員","kind":"意見","question":"趣旨については非常に分かるところがあるので、趣旨採択ということだったのですが、もし態度を出さなくてはいけないということであれば、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":343,"id":"exchange-072"}]},{"id":"topic-11","title":"専決処分の報告について（報告第１９号）","agenda":"専決処分の報告について（報告第１９号）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今の専決処分で、車に衝突のブザーといいますか、アイサイト、そういうのはつけてあるのですか。","respondent":"加島人権啓発課長","answer":"今、当課で管理しております庁有車につきましては、アイサイトはございません。","voiceIndex":361,"id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2268#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":63221,"voices":366}},{"id":"r05-20230704-6","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"区民委員会","time":"午前１０時００分～午前１０時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年度 文化センター等工事による休室・休館予定","agenda":"令和５年度 文化センター等工事による休室・休館予定","exchanges":[{"speaker":"山本委員","kind":"質問","question":"ちなみに、所管されている施設の中で、順次ＬＥＤ化をやっていらっしゃるということは、どれぐらいの進捗になっているのですか。","respondent":"篠田文化観光課長","answer":"こちらは、先ほど申し上げた施設整備課で全体の調整をしているもので、今、文化センター等で進んでいるところです。それから、きゅりあんに関しましては、全体のリニューアル工事もやってありますので、今回で全て終わるような形になってあります。","voiceIndex":7,"id":"exchange-001"}]},{"id":"topic-02","title":"デフスポーツ応援事業","agenda":"デフスポーツ応援事業","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"今年度、区内で強化合宿というのは、いつ頃とか場所というのが、もし決まっていれば教えていただきたいです。","respondent":"三井スポーツ推進課長","answer":"強化合宿の場所ということで、今回、日本ろう者サッカー協会から聞いていますのが、７月２８日から７月３０日で、天王洲公園サッカー場でやりまして、そのうち７月２９日については、区民の方に開放していただいているということで聞いております。","voiceIndex":14,"id":"exchange-002"},{"speaker":"えのした委員","kind":"確認","question":"合宿中にこのイベントを行うということですね。確認が取れました。もう１点だけ、交流会なのですけれども、どういった内容で、例えば手話の講習のようなものが含まれているとか、内容が決まっていればお教えいただけますでしょうか。","respondent":"三井スポーツ推進課長","answer":"今、日本ろう者サッカー協会と交渉中なのですが、手話までどうするかというのは、まだこれからなのですけれども、選手に対する質問コーナーとか、一緒にボールを蹴るとか、そういうことを予定しております。もう少し詳細については詰めていきたいと考えています。","voiceIndex":16,"id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"私もこういった交流会に参加したことがあるのですけれども、やはり代表の選手の方と、質問ですとか、一緒にプレーするというのは、本当にお子さんたちにいい体験の機会になると思いますので、よい交流会になるかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区でこういうデフスポーツの機運を醸成していくというのは、非常にすばらしいことだと思います。デフリンピックもあることですし。品川区としては、たくさんの方に来ていただきたいというお考えなのか、その辺りを教えていただければと思います。","respondent":"三井スポーツ推進課長","answer":"もう一つのご質問ですが、区として多くの人に来てもらいたいということかどうかというところかと思いますが、基本的に、デフスポーツの普及啓発ということもありますので、なるべく多くの区民の方に来ていただきたいと考えていますが。","voiceIndex":20,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"意見","question":"そもそも事前申込不要で入退場自由というのは、それほどの集客がないという前提での話だと思うのです。ブラインドサッカーなども、私も初めて見たときは、その迫力というか、激突音というか、そういうものを実際に感じて、これはすごいスポーツだなと感じましたので、品川区でも多くの区民が実感できるような形で周知をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"観覧席の設置を考えているということで、どういう感じで天王洲公園サッカー場に、何人ぐらい入れる形のものにしていくのか。段々にしていくのか、そういうものは設置が可能なのかということをお聞かせください。","respondent":"三井スポーツ推進課長","answer":"それが難しいようですと、パイプ椅子とか、そういうものになってしまう可能性はありますが、一応それで考えております。そうすると、２００席から３００席程度かなと予定をしております。","voiceIndex":24,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。確認なのですけれども、内容のところで、（１）のトレーニングマッチ、強化試合が事前申込不要、入退場自由ということで、交流会も同じように、特に人数制限とか申込とか、その辺りはどのようになっているのかだけ確認をさせてください。スケジュールですとか、そういったところも、もしイメージがあれば確認させてください。","respondent":"三井スポーツ推進課長","answer":"もう一つが、デフスポーツ啓発動画の活用方法ですが、デフスポーツの応援事業はこれで終わりませんで、デフリンピックの啓発ということで、１０月にイベントを予定しております。","voiceIndex":26,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ、様々、今後予定されているイベントですとか、そういう機会を捉えて積極的に発信をしていただきたいと考えています。今回、これから観覧席を設置するということで、その辺りの調整が終わり次第というところかと思うのですけれども、そこも確認させてください。","respondent":"三井スポーツ推進課長","answer":"周知方法は、基本的には広報しながわとＳＮＳを使って、そういう方たちにもどのように来ていただけるかというのは日本ろう者サッカー協会と相談の上、広報できる範囲でしていきたいと考えています。","voiceIndex":28,"id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"ご覧になりたい方、ご興味ある方がなるべくご覧いただけるようにぜひ、現実的な観覧席等の部分もあると思いますので、日本ろう者サッカー協会とよくご相談いただいて進めていただきたいと思うのですけれども、その辺り、いかがでしょうか。","respondent":"三井スポーツ推進課長","answer":"日本ろう者サッカー協会とそこはよく相談しながら進めていければと思います。区内には明晴学園もありますので、そちらとも連携が取れればいいなと思って、そちらも考えていければと思います。","voiceIndex":30,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、デフリンピックのデフの意味を教えていただけますか。","respondent":"三井スポーツ推進課長","answer":"デフは英語で、耳が聞こえない人とか、聞こえにくい人という意味があります。","voiceIndex":32,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうすると、デフリンピックというのは、パラリンピックとは別で、そういう意味で特化しているということですね。分かる範囲でいいのですけれども、デフリンピックにはどういう競技があるのか教えていただきたいです。今後、強化合宿を行うということで、サッカーという形になっていると思うのですけれども、まずそこまで伺います。","respondent":"三井スポーツ推進課長","answer":"デフリンピックの競技についてのご質問かと思われますが、サッカー以外ですと、デフリンピックの競技として決まっていますのが全２１競技あります。例えば、陸上、卓球、バレーボール、バスケットボール、ハンドボールなどがあります。","voiceIndex":34,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこで、子どもたちの参加とか、普及啓発等をしていっていただきたいと思うのですが、そこは教育委員会等が入ってくると思うのですけれども、２０２５年にデフリンピックを行うということを契機に、この２年間やっていただきたいと思っているのです。その辺については、もう教育委員会と話していたりしているのかということも含めて答弁いただけますか。","respondent":"三井スポーツ推進課長","answer":"サッカー以外の競技のことについてですが、まだほかの競技については何も予定をしておりませんで、特にコンタクトを取っているという状況にはございません。","voiceIndex":36,"id":"exchange-013"},{"speaker":"藤原委員","kind":"確認","question":"品川区が今、開催されることもまだ決まっていないとおっしゃっていたから、また東京都があって、東京都デフリンピック委員会みたいなものができて、そこで各区がこうしてくださいというか、東京２０２０大会のときのような形になっていくのでしょうか。今は確実な答弁ができないかと思うのですけれども、一番伺いたいのは、主体は東京都なのですかという確認をしたいので、その辺をよろしくお願いします。","respondent":"三井スポーツ推進課長","answer":"東京都とデフリンピックの関係性までは、すみません、不勉強で、現状、把握はできていませんが、東京都でも基本的には普及啓発に力を入れていくということで聞いております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"デフリンピックは、東京で開催することは決定しているのですよね。どこが主体でやっていくのですか。","respondent":"三井スポーツ推進課長","answer":"デフリンピックは、一般財団法人全日本ろうあ連盟スポーツ委員会というのがございまして、そこと東京都で一緒になってやっていくというのは聞いております。","voiceIndex":40,"id":"exchange-015"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"日数等に関しては、相手の視察先のこともあるので、予定を組まなくてはならないのは分かるのですけれども、日数ありきではなくて、その辺はぜひ委員長、副委員長に考えていただいて。もう一回言います。相手先があるのですから、２泊３日のスケジュールというのを決めてということよりも、コロナ感染等に関してということも考えの中に入れていっていただきたいと、私は個人的に思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"私も、委員長にも直接お伝えしているところですけれども、この区民委員会でも何度も言っているところですが、やはりコロナの感染拡大の状況というのはしっかり見ていかなければいけないと思いますし、感染力が弱まっているわけではないというところでは、議会としては慎重に対応していくべきだとは思っています。感染拡大した際にはそういう対応をしていくということで、ぜひお願いしたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"これが基本であると思います。先ほどあったとおり、各委員から様々な視察の提案があったということが委員長から報告がありましたけれども、私も何が何でも行きたいとか、そういうタイプではないのですが、そこを履き違えると、前後が逆になってしまうのではないかと思いますので、そこのところは、何のために行政視察に行くのかというところを確認した上で、ご調整をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"ですから、その時々の状況ですとか、あとは視察に関しては、受入先の受入れ状況ですとか、先方の状況、そしてまた議会全体の方針など、そうしたところというのは、現段階では想定が不可能であると私は考えています。ですので、本日の時点においては２泊３日ということで、しっかりとお仕事をしていくということが、区民の皆さんにとってベストなのかなと私は考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-019"},{"speaker":"えのした委員","kind":"意見","question":"私も、今、あくつ委員と横山委員がお話しされていましたけれども、もともとの行政視察の意味が一番重要で、区民のよりよい生活につながる視察が可能であれば、もちろん先方の状況も鑑みなくてはいけないとは思いますが、今、地域も含めて、従前どおりになっていますので、２泊３日ありきというよりは、やはり行政視察の意味。それで、もともとのやり方に戻すということで、私はいいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"方面がどこかというよりは、事例がどういうものが学べるかというところが、まず大事かなと考えております。他自治体の先進事例というところで、テーマが観光であったりとか、そして官民連携というのは、まさに品川区としてもよく研究し、検討していく必要があると思いますので、そういった事例が視察できるということであれば、ぜひ進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"},{"speaker":"あくつ委員","kind":"提案","question":"今のは私もそのとおりだと思うのですけれども、この前、期限までにということで、多分、各委員から幾つか提案があったと思うのですが、それを今、改めて申し上げたほうがいいのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-022"},{"speaker":"山本委員","kind":"質問","question":"幾つか個別の事例も挙げさせていただいておりましたが、私も九州方面にも幾つか挙げているのですけれども、あくつ委員がおっしゃっているように、今この場で具体例とかも申し上げたほうがいいのでしょうか。どのような意見を述べるのがよろしいのでしょうか。それぞれ改めて発言するのがいいのかどうか、今、よく分からなかったのです。あくつ委員のご発言を踏まえて、どう進めたらいいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"提案","question":"各委員から、多分、全国様々な提案、私もいろいろなところを提案させていただいているので、逆に、正副委員長一任でよろしいのかなというところです。九州は嫌だという発言を求めているのではないのだと思うので。正副委員長のご判断にお任せしたいと思うのですけれども、それでよろしいですか。どういう意見を求めているのか、私も少し分からなかったのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-024"},{"speaker":"山本委員","kind":"提案","question":"そちらで私は異論がございません。観光と官民連携以外のテーマで、時間が許して、ほかにも回れるというものが見つかりそうであれば、追加的にご提案をするのがいいのかなと思ったのですが、そういう理解でよろしいでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も、山本委員がおっしゃるとおりだと思いますし、またテーマ的にも、九州で、自治体によっては、例えばこれは所管が違いますけれども、新庁舎を建てられたようなところもありますし、そういうところで窓口のところ、戸籍住民課は区民委員会の所管でありますので、区民対応、書かない窓口であるとか、おくやみ窓口ということも、いろいろと議会でもこの間取り上げてきたので、もしそういうところがあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。学校プールの実施について、１点教えていただきたいのですが、実施する全７校はエリアにばらつきがあるように思うのですが、これは実施できる学校をどのように選んでいらっしゃるのでしょうか。","respondent":"三井スポーツ推進課長","answer":"こちらは以前よりまず教育委員会で、プール開放可能な８校を提示いただいておりまして、例年であれば、こちらの資料に記載の７校に、第四日野小学校を加えた８校が開放の対象になっておりますが、現在、第四日野小学校は工事の関係で今年度は開放がございませんで。","voiceIndex":74,"id":"exchange-027"},{"speaker":"山本委員","kind":"意見","question":"８校までというのは決まっているというか、教育委員会で決めていらっしゃるということなのですね。分かりました。エリアの偏りがあるように思いますが、夏のプールは楽しいと思いますので、多くの子どもたちがエリアに偏ることなく利用できるように、今後ご検討いただけたらと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-028"},{"speaker":"えのした委員","kind":"質問","question":"一般質問でもありましたが、熱中症対策について、屋外水泳場、また学校プールともに、クーラーボックスの用意ですとか、お水、冷水機があるのか。下が熱くなっていますから、サンダルを履いていいですよとか、あと、監視員の方というのがどのぐらい配置されているのか、熱中症対策についてお伺いしたいと思います。","respondent":"三井スポーツ推進課長","answer":"監視員の数については、すみません、手元に詳細な資料がございませんので、個別にご説明させていただければと思いますが、監視員については基本的に入札で業者を選定しておりまして、監視員がいるような状態だと考えています。","voiceIndex":78,"id":"exchange-029"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認させてください。プールの予約方法なのですけれども、ホームページに掲載する予約専用サイトで予約を受付ということで、恐らくインターネットをご利用になる方がほとんどなのかなとは思うのですけれども、万が一インターネットが使えない状況の方等がいらっしゃった場合にはどのように対応されるのか、確認させてください。","respondent":"三井スポーツ推進課長","answer":"現在、予約システムはどうしてもインターネットを使うような形になってしまっておりますので、もしそういう声があるようでしたら、また今後検討させていただければと思います。","voiceIndex":81,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16466,"voices":84}},{"id":"r05-20230704-7","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"厚生委員会","time":"午前１０時００分～午後 ４時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立八潮南特別養護老人ホーム等の増改築","agenda":"品川区立八潮南特別養護老人ホーム等の増改築","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"ご説明ありがとうございました。医療的ケアが必要な方が来られることになると思うのですけれども、呼吸器ケア等されている方がここに通所可能なのかということを確認させていただきたいです。","respondent":"松山障害者支援課長","answer":"私のほうから、重症心身障害者通所事業についてのご質問にお答えいたします。ピッコロですが、令和３年度から、定員５名から６名に変更しております。今は、現在の登録の方は、利用者は７名ということでお通いいただいております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほど説明会をしてくださるということだったのですけれども、その説明会につきましても、ぜひ今通っている方々、また、そのほかの方々にも広く周知していただいて、ここがこのように変わるのだというところを区民の方々に示していただきたいなと考えていますので、その周知方法について、今後どのように検討しているかという点についても教えてください。","respondent":"東野福祉計画課長","answer":"既存の施設に入っている方々へも周知を行う予定でおりますので、そういった形で進めていきたいと考えています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何点か伺いたいのですが、グラウンドが移設をして、そのグラウンドのところに増築するということなのですけれども、ちょっとここの状況がよく分からないので教えていただきたいのですが、グラウンドが移設するところというものは、今まで何があってどのような状況になっていたところにグラウンドが移設できることになったのかということを１つ教えていただきたいと思います。その点お願いします。","respondent":"東野福祉計画課長","answer":"多少は増える可能性もあります。定員のほうは約１５０名ということで、増やしていきたいと。全体の定員を１００名から１５０名に増やす予定です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この八潮南の特別養護老人ホームというものは、個室しつらえへの大部屋、多床室という形の、かなり品川区が工夫してつくられた特別養護老人ホームになっていて、個室のような形で料金は多床室と同じ料金で利用できるということで、私はすごくいい施設だなと思っていたのですけれども、これはぜひ残していただきたいなという思いがしているのですが、そこのところはちょっとどうなるのか。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"増築棟のほうが、現在進めているのがユニット型で増築棟のほうは考えておりまして、そうしますと、その辺を加味していくと、従来型のところを現在の多床室のところへ若干移すような形で。私のほうからは、在宅介護支援センター等の機能拡充についてのご質問にお答えします。","voiceIndex":15,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。特別養護老人ホームのほうは、そうすると大部屋というか、多床室のほうは多床室として残しながら、増築するところは個室ユニット型という、そのようなことの整備になっていくのは、ちょっとその辺のところで、個室ユニット型と多床室の割合、その辺ももう方向が出ているのであれば、ちょっとそれも教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"まだ設計の段階というところなので、増減はあろうかと思いますが、現在多床室が約４８あるところを半分程度にしまして、従来型個室のところが既存棟の３階、４階にありますので、そこの部分はできるだけ活かしていく形を取ろうと考えているところです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ残していただきたいということで、要望もさせていただきたいと思いますが、ちょっとその確認をお願いしたいと思います。そこのところはどうなのかということが１点です。呼吸器をつけた方が通うところがないということは、ずっと議会の中でも取り上げ続けてきましたけれども、呼吸器をつけた方も通えるような施設にしていただきたいと思っているのですが、その点も１点伺います。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"一部改修等が生じるところもありますが、そのようなところについた分については、また別のところへ配置するなど、できるだけ残していきたい考え方です。そのため、人員体制につきましても、通常の生活介護よりも手厚い人員配置になっておりますし、また、その医療的ケアの中身につきまして、その状況ですとか、あるいは医療連携、今後どういった医療連携が必要なのかにつきましても。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"それと、あと呼吸器をつけた方も基本的に通える施設として整備されていくのか、その点も伺いたいと思います。それからあと、住民説明会は８月に開催予定となっているのですけれども、ここを利用されている方だけではなくて、当事者、家族の方々への説明会というものも行うべきではないかなと思うのですが、その予定があるのか、あったらいつ頃考えられているのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"次に団体や家族に対しての説明についてお答えいたします。通所されているご家族のみならず、団体の方に対しましては、情報提供する予定です。まだ日程的には決まってはおりませんが、できるだけ早く情報提供させていただきたいと考えております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"確認","question":"それなので、落ち着いている場合は、呼吸器をつけている方でも通えるようになるのか、その点だけちょっと確認をさせてください。","respondent":"松山障害者支援課長","answer":"個別具体的な話になりますので、呼吸器をつけていて一般的には落ち着いている方でも、区としては通っていただきたいと考えていますが、また、そのほかの状況によって、その事象だけではなく、やはりご本人の体調等の変化や、少しずつの、例えば気温ですとか。","voiceIndex":25,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"特別養護老人ホームの個室しつらえを残すということで、すごくうれしく思います。これは区としても、すごく工夫して工夫してそのような形をつくって、品川区独自の、本当に編み出したというか、本当にいい施設だと思っていますので、ぜひ残していただくということで、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回増設される中で職員宿舎６名とあるのですけれども、これは宿直用などの宿舎ということでしょうか。","respondent":"東野福祉計画課長","answer":"宿直などではなくて、介護職員の確保のために、何といいますか、通常のアパートなどを借りるのではなく、そこに宿舎として準備をするというものです。","voiceIndex":29,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"職員用の住居ということで、ちなみに今回の増改築によって、どれぐらいの職員数が増えるという見込みでいらっしゃいますでしょうか。","respondent":"東野福祉計画課長","answer":"今後法人の運営ということになりますので、ここをして定員などにつきましてもご提案をいただくということになります。ですから、今のところ何名増えるなどというところでは、明らかになった数字というものを持っているものではございません。","voiceIndex":31,"id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"というのは、八潮というのは非常にアクセスが悪くて、ちょっと陸の孤島感があるところで、やはり遠くから通うということは結構大変で、そういう意味でも職員の確保というものがより難しい、介護職員自体、職員の確保は難しいと思うのですけれども、より難しさの増すところなのかなということは個人的に感じておりますので、例えばこういった職員宿舎をもう少し増やすとか、もしくは。","respondent":"東野福祉計画課長","answer":"他の施設の方でも入れるものとして想定をしています。とはいいましても、なかなかほかの地域からこちらへ通う、また、こちらからほかの地域へ通うということは難しいという部分もあると思いますので、こちらの職員寮の使い方につきましては、十分考えていきたいと考えています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。今回この介護職員の人員確保対策として、職員の宿舎の整備ということになっているので、前提として区のお考え方として、介護職員というものはやはり人員不足で、どこの介護施設も基本的には人員確保に苦労しているというような認識というように考えてよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今のところ区の介護事業者のほうから、直接人員の確保が厳しいというお声は、直接は聞いてはいないところがあるのですが、例えば訪問介護の事業者などのお話を聞きますと、今いらっしゃる方たちが、もう２０年ぐらいずっと働いていてどんどん高齢化している。","voiceIndex":35,"id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ごめんなさい。ちょっと今聞き間違いだったらごめんなさい。今働いている方が２０年ぐらい働いて高齢化していて、それに伴って今後は人材確保が難しいというようなお話でよろしいですか。すみません。もう１回。","respondent":"菅野高齢者福祉課長","answer":"私が伺った訪問介護、ヘルパーの事業者については、そのような傾向が強いというように伺っております。","voiceIndex":37,"id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ちょっと私の現場感覚と大分乖離があるかなと思います。２０年働いているというヘルパーがいるということ自体がかなり驚きでして、かなり持続率の高い職場です。もしそういったところで人材が不足しているなど、そういった要望があれば、そういった対策も区のほうで前向きにしていただけるということでよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"介護人材についての事業者への支援等につきましては、現在も、介護人材の確保戦略というものを令和３年度に、事業者のヒアリング等もさせていただきながら取り組んでいるところです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"２点お伺いしたいと思います。１点は、先ほども質問が出ておりましたけれども、このピッコロの移設で拡張ということで、先ほど区としては、いわゆる、これからも医療的ケアの、何というのですか、依存度の高い方もできるだけ受け入れてくださる、そういう姿勢で、お考えでいらっしゃるということは確認させていただきました。これ初めてですか。宿舎をつくってくださるということは。","respondent":"松山障害者支援課長、菅野高齢者福祉課長、東野福祉計画課長","answer":"これからその認識に向けて、具体的にきめ細かく、区民のお声も伺いながら詰めていく、一歩一歩行かなければならないというところだと考えております。私のほうからは、職員の住宅確保支援についてお答えします。元芝アパート跡地のほうにつきましては、都における設計のほうがもう進んできておりまして、職員宿舎を設ける予定ではないということです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"先ほどのご答弁をお聞きしていると、その体制をつくるためには、看護師の問題だとか、いろいろな人員体制というか、そうしたものも必要だということなので、まずはお考えがきちんとされた上で、その体制をどうこれからつくっていくかということだと思いますので、ぜひ前向きに、その辺の体制を、区と事業者と体制を、できるだけ受け入れられる体制をつくっていただいて、依存度の高い方も。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"八潮のところにつきましては、現在通常のワンルームアパートのような形のものを予定しています。あまり華美な形ではないのですけれども、十分な生活環境ができるようなスペースを用意したいという考えです。できるだけ区も、運営事業者も、受入れ体制については積極的な姿勢を一致しておりますので、あとは人員体制、それからまた、人員でもスキルのある人員をそろえていただけなくてはならないという課題がありますので。","voiceIndex":47,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"在宅介護推進のためには、ショートステイというものは重要な役割を果たすと思っているのですけれども、現在この八潮南特別養護老人ホームのショートステイの定員は１１名かと思うのですが、今回ショートステイの定員は増やされるご予定はあるのかということと、この今のショートステイの利用状況をお伺いいたします。","respondent":"菅野高齢者福祉課長、東野福祉計画課長","answer":"ですから、今後につきましても、この地区でショートステイがどのぐらい必要なのかというところは、運営事業者といろいろと相談しながら減らした経緯等もありますので、検討していかなくてはいけない課題だと捉えているところです。先ほどほかの委員からのご質問にもありましたとおり、ショートステイの人数につきましては、同規模程度のものを考えているものです。","voiceIndex":51,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどの職員宿舎のことでちょっと伺いたいのですけれども、これは利用料というものは、利用料、利用料は何円か、ちょっとそれを教えていただきたいということと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"家賃です、家賃。それから、希望者がどの程度あるのか、希望者がたくさんあったときはどのようにして入居者を選ぶのか、その需要の状況というものもちょっと教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"運営事業者とも確認しなくてはいけないことなので、現時点では、利用料が幾らとか、どういった方をということは、細かい部分までは決まっていないのですけれども、先ほども申し上げたとおり、ほかにも借り上げ型の住宅ということで。","voiceIndex":56,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も看護師になったばかりのときは看護師の寮に入って、職場に通っていましたけれども、かなり看護師の場合の寮というものは、希望者が全員入れるぐらいの、すごいたくさんありまして、それが本当に当たり前というような形になっていたのですが、そういうところからすると、介護職員も職場にくっついていなくてもいいと思いますので、これだけ介護人材の確保が大変なときに、やはり私は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-021"}]},{"id":"topic-02","title":"品川区障害者計画および障害福祉計画・障害児福祉計画策定のための基礎調査結果報告","agenda":"品川区障害者計画および障害福祉計画・障害児福祉計画策定のための基礎調査結果報告","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"内容に入る前に、３点ほどお伺いします。２点目です。こちらの回収結果のところで、区内事業所からの有効回収率３４.５％で回収を受けておられますが、今回こちらの資料の報告のほうには、特にこういった事業者からの回答についての結果等は出ていませんけれども、詳細の２００ページ以上の資料のほうには載るのでしょうか。３点目、こちらのほうが、６ページ、７ページの障害児調査の結果のところです。","respondent":"川崎障害者施策推進課長","answer":"今回介助者、第１介助者、第２介助者というものを２人まで、初めてこちらの設定はさせていただいたのですけれども、実際の詳細については分かりかねます。","voiceIndex":63,"id":"exchange-022"},{"speaker":"ひがし委員","kind":"確認","question":"回収率のところについて少し気になるので、確認をさせてください。","respondent":"川崎障害者施策推進課長","answer":"設問数増加と回答率の低下というものは比例する傾向がありますので、今後区としても、次回の調査以降、設問数を見直して項目の精査を進めていく必要はあるかなと考えております。","voiceIndex":67,"id":"exchange-023"},{"speaker":"ひがし委員","kind":"質問・要望","question":"５７.５％から減った、１５ポイント大きく減少していますというところになるのですけれども、ここのところ、この内容自体は減っているなと思うのですけれども、逆に無回答がすごく増えてしまっていると思うのですが、この分析というものはどのように考えているか、ご説明いただけますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"無回答の方がまた増えたというところですけれども、区としては様々な働き方、パートで働きたいという方もいれば、やはり正社員として働きたいという方もいますし、そういった多様な働き方を今後支援体制として整備していく方向に動かしていきたいなと考えております。","voiceIndex":69,"id":"exchange-024"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私も看護師をしておりまして、患者様と接しているときに、仕事は続けたい、でもできない、このような状況があるのだという声をとてもよく聞くので、そのような方々も地域で働きたいという意思は絶対あると思いますので、働けるようなサポートをという内容をしっかりと酌み取っていただければいいなと思いますので、また質問のところについてはその項目を足していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ですから、かなりいろいろと中身についてもよく分かる中身になって、改めて障害者の方々の理解が進むなと思ったのですけれども、私はぜひ、障害者の問題というものは障害者種別に様々抱えて、課題がありますので、希望なのですが、この全ての、概要版ではなくて報告書も配っていただきたいということで、これは要望させていただきたいと思います。","respondent":"川崎障害者施策推進課長","answer":"私どもとしても、回答の期間、ウェブ回答も含めて、回答のしやすさというものを整備したのですけれども、残念ながら、結果的には前回よりも減少したというところになりますので、次回以降、やはり設問の項目内容というものはより精査を進めていく必要があるなと考えます。","voiceIndex":73,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからあと障害者の方は、もう本当に障害の種別によって、かなり、何というのですか、要望も違いますし、抱えている課題も本当に違うので、例えばここの５ページのところで、同居家族というところも、グラフになると、父親、母親、配偶者・パートナーというようなことで数として出ていますけれども、でも、例えばクロス集計を見ないと、知的障害の方は７割近くが母親だったりなどというようなことで。","respondent":"川崎障害者施策推進課長","answer":"前回発達障害、高次脳機能障害の方に特化した質問というものもさせていただいて、ただ、今回はその属性の中に満遍なく回答を得るために載せさせていただいたのですけれども、障害福祉計画の策定のほうでも、発達障害の方と高次脳機能障害の方、区民公募。","voiceIndex":75,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから１５ページなのですけれども、「医療的ケアについての困りごと」というものが、今回改めて取っていただいたということなのですが、これはｎが５４ということになっているのですけれども、これ回答いただいた方が５４ということなのでしょうか。医療的ケア者のところも何人かということが分かったら教えていただけたらと思います。","respondent":"川崎障害者施策推進課長","answer":"今、区として捉えている数字ということですけれども、令和４年度、医療的ケア児支援関係機関連絡会、こちらのほうでも報告させていただきましたが、区として令和５年２月末現在、合計３０人の方、医療的ケア児の状況として認識をしています。","voiceIndex":77,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問","question":"すみません。医療的ケア児の方が３０人で、回答された方が５４人ということは、それはどうしてそのように、ケア児の方よりも多い人数になっているのか、また、医療的ケア者の人数も分かったら教えていただけたらと思うのですが。","respondent":"松山障害者支援課長","answer":"その３０人というものが、区としてのサービスをお使いいただいている方、または相談中の方に対して３０人ということで、実質つかんでいる人数なので、また実際は在宅にいらっしゃる方ということで、恐らく５４人の方につきましては、入院中だったりした方もいらっしゃいますし。","voiceIndex":79,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"回答された方が全員ではないと思うので、医療的ケア児の方が何人かという総数としては、区としてはなかなかこれ捉えるのが難しいということでずっと言われているのですけれども、最大でというか、区として捉えている人数というものが分かったら、これは回答いただいたのが５４人なので、それ以上いらっしゃるということだと思うのですけれども、その区として捉えている人数が、ケアの子どもだけでなく。","respondent":"松山障害者支援課長","answer":"医療的ケアの方は、比較的変化が激しいということがありますので、そのたびごとに数字というものは変更があるものと考えておりますが、ただし、今の段階では、この２つの数字以外には、区としては捉えているものはございません。","voiceIndex":81,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問","question":"医療のほうに関わっているので、保健所などと連携しても、なかなか難しい部分はあるのかなと思うのですけれども、実数をどうしたら品川区内で、およそ医療的、本当にレセプトなどを見ないと分からないのかなと思ったりもするのですが、ではどうしたら、つかむすべというものはなかなか難しいという状況のところから、なかなか出ないでしょうか。","respondent":"松山障害者支援課長","answer":"医療的ケア児者の区内の人数ですが、委員おっしゃられるとおり、なかなか、正確な数字をつかむということが非常に難しい状況です。保健所とも連携をした数字になっておりますので、その３０人という数字は確かな数字です。","voiceIndex":83,"id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いします。区内の事業所へのアンケートなのですけれども、当然内容は、こちらに記載していただいているご利用者の方へのアンケートと大分内容は異なると思うのですが、具体的にどのような設問をご用意されていますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今回事業所の方に対しては、事業所の経営状況であるとか、それから事業所の職員の状況、また、事業所のサービス向上や安全確保の取組について、また医療的ケア・重症心身障害児者の対応について、こういったところを質問として挙げさせていただきました。","voiceIndex":86,"id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。有効回収率が３４.５％ということで、かなり低いかなというように認識して、私自身はそう思うのですけれども、この数字についてはいかがお考えでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そうですね。うちとしても１３９事業所に送らせてはいただいたので、やはり半数近く回答が上がれば、私どものほうでも事業所で抱えている実態というものをつかめますので、ここは委員のおっしゃるとおりだとは思います。","voiceIndex":88,"id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。１００％にする必要はないと思いますけれども、やはり、いくらなんでも３４は、ちょっと実態を把握するのには少し心もとない数字かなと思います。ぜひ数字を上げていただきたいと思いますので、そのために何か、来年度や次回のアンケートでこのようなことをしてみようとか、そういった施策というものは、お考えはありますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"はやはり周知のところも含めて、事業所様とは日々私どもも連携を取りながら、障害者の、そして障害児の実態というものをつかむために、事業所様とも日々の連携の中から前もっての周知をさせていただきつつ、実効的な回答を得られるように、私どもも工夫をしてまいります。","voiceIndex":90,"id":"exchange-034"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えばですけれども、今回アンケートに協力いただけなかった事業所に、ちょっと１本電話してみて、このようなアンケートを取って、もう締切りは終わってしまったのですけれども、ちなみにどのような理由でアンケートを答えられなかったのですかというような感じのことを伺って、それを次回に活かすなどということは、お考えというか、検討していただけますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そういったご提案も含めて、私どもも工夫は図ってまいりたいと思います。","voiceIndex":92,"id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"恐らくですけれども、私は現場というか、こういった事業所が忙し過ぎて、多分こういったアンケートにまで手が回らなかったのではないかなというものが個人的な感想ですが、実際問題どうなのかということをぜひ、電話で聞いて答えるぐらいだったら、恐らく事業所もしてくれると思いますし、当然自分たちの意見というものを区政に反映してほしいなどということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-036"},{"speaker":"おぎの委員","kind":"意見","question":"こちらは質疑というよりも希望です。品川区の実態が分かる、すばらしいアンケートだと思って拝見させていただいています。６ページの、例えばこちら、障害児の調査で、障害児のお子さんを見ているのは圧倒的にお母さんが多い。お父さんは第２介助者とはなっていますが、ふだんはお仕事されているのかなという背景が見えます。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-037"},{"speaker":"こしば副委員長","kind":"確認","question":"確認なのですけれども、在宅の障害者の方で、障害福祉サービス未利用者の方は無作為抽出ということなのですが、これは要は区に登録されていない方で、国民健康保険被保険者など、そういったところから抽出されてくるのかなと。これの関連性というものはあるのかどうかも含めて、今後に向けた考え、取組を教えていただければと思います。","respondent":"松山障害者支援課長","answer":"発達障害の方が正職員として働きたいというご希望を示されているという、その声は私どもも伺っているところですし、アンケートでも明らかにこのような結果になっているということですので、今後対策といたしましては、超短時間就労を今進めておりまして。","voiceIndex":98,"id":"exchange-038"},{"speaker":"こしば副委員長","kind":"質問","question":"年齢との関連性をちょっと教えてもらいたい。１８歳から３９歳までの方は、正職員として働きたいというパーセンテージが多いから、多分リンクはしているのかなとは思うのです。","respondent":"松山障害者支援課長","answer":"これは発達障害者支援施設に関しましても、比較的若い、この１８歳から３９歳までの方が多くいらっしゃるということはありますので、こちらのほうとしましては、発達障害の中の比較的若い年齢層で働きたいと思っていらっしゃる方は、今後働けるように。","voiceIndex":100,"id":"exchange-039"},{"speaker":"こんの委員","kind":"質問","question":"先ほどのご説明で、今回の設問で新たに「相談時の困りごと」ということをお伺いしましたというご説明でした。いわゆる、このお困り事を設問として加えようと思った、どのような背景というか、どのようなことでしたのか、その点をひとつお願いしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"この情報アクセシビリティの観点から、アクセスの重要性については今後検討していかなければならないと考えております。やはり相談支援体制の充実・強化に向けて、基幹相談支援センターにおける相談機能、また、地域の相談支援機関、それぞれの役割、それから連携ですね。","voiceIndex":103,"id":"exchange-040"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうしても相談体制の、いわゆる、そうしたお声というものはこれまでもよく聞いてきたことですし、区としても、それをどのようにというお考えも、これまでもお聞きしたこともありますしというところなのですが、あえてこの中に設問としてきちんと取り上げていただいて、確認をする、ニーズを把握していく、どうそれをアプローチというか、したらいいのかということの材料にされたということは。","respondent":"川崎障害者施策推進課長","answer":"今委員おっしゃられましたように、必要なサービスを必要な方に受け入れていただけるように、私どもも実情のほうに対応していきたいと思います。","voiceIndex":105,"id":"exchange-041"}]},{"id":"topic-03","title":"令和４年度品川区障害福祉計画実績","agenda":"令和４年度品川区障害福祉計画実績","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区障害福祉計画実績についての２ページのところの目標値についてなのですが、この目標値の2)施設入所者数のところ、目標値としては２７１人を超えないとなっているのですが、現在の入所施設の状況、定員数について教えていただきたい。この目標設定をした、この値を設定した理由についての背景も教えていただきたいです。","respondent":"松山障害者支援課長","answer":"施設入所者数の状況について、まずお答えします。状況的には、２ページに実績がありますけれども、令和４年度につきましては、３月末時点で２７５人となっています。区内の入所施設、２か所ございまして、合計で１３０人の方が区内の施設に入所しております。","voiceIndex":112,"id":"exchange-042"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この２７１人というのは、国から決まって、品川区の令和元年の値が２７１人だから、そこを超えないとなっている。今後、この目標値の設定についても検証していく予定なのか、また、その方法についても教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"前回も議論の中で、やはり５０人もお待ちいただくのだから、もう少し数字を上げたほうがいいのではないかという議論も実はございました。その中で、実際に地域移行者数、これとは別に地域自立支援協議会、この２ページの下にあります。","voiceIndex":114,"id":"exchange-043"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ入れないという方々も入れるように、今後計画していっていただきたいと思うのと、評価および改善のところに、地域移行を支える社会基盤の充実を図るため、地域移行支援、自立生活支援、地域定着支援の事業所誘致を図ったが開設には至らなかったという点について、ここをやはり上げるためには、こういう開設というのも必要だとは思うのですが。","respondent":"松山障害者支援課長","answer":"こちらには、開設に至らなかったというのは令和４年度のところに書いてあるのですが、実は令和５年度に区が補助金を予算立てしまして、自立生活援助という、一人暮らしの方に対して、要は地域生活が継続できるよう訪問するというアウトリーチ事業を開設をいたしましたので。","voiceIndex":116,"id":"exchange-044"},{"speaker":"ひがし委員","kind":"意見","question":"やはりこういう事業所のご意見というのもとても重要だと思っていますし、医療業界、介護業界通しまして人材不足というのはとても深刻な問題だと思いますので、この話はしっかりと聞きながら、実際に建ててもそれが運用できない、利用者の方々のニーズに対応できないとなってしまうと問題だと思いますので、これについてはしっかりとヒアリングを行いながら前向きに検討、そして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問","question":"障害者支援課長が足をけがされているので、着座での答弁をお願いしたいのですけれども、よろしいですか。多分、この後も質問が出るので、毎回立つのは大変だと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１ページの(3)なのですけれども、令和２年のところと３年４年と数字がすごく大きく変わっているのですが、令和２年のときにこれだけ低いという、その理由を教えていただきたいのが１点です。だから、令和２年のときがすごく少ないのか、このような形で増えてきたのか、そこだけの状況を教えていただきたい。","respondent":"坂野保健予防課長","answer":"コロナで申請の延長、それがあったせいで年度がずれ込んでいるので、こういう数字になっています。","voiceIndex":122,"id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。この入所されている方がグループホームに移れば、地域移行という形になると思いますので、施設を待っている方とグループホームを待っている方というのは質が違うのではないかと思うのですけれども、地域移行をしなければならない、それが求められる施設入所の方というのが、どれぐらい入所を待っている方がいらっしゃるのかというのを教えていただけたらと思います。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"こういうグループホームだったら入れるけれども、こういうグループホームは難しいといったような、受け側の施設側のといったこともあります。今後も民間の活力を使いながら、グループホームの整備、増やしていきたいと考えております。","voiceIndex":124,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"続けて４ページのところも伺いたいのですけれども、４ページのところの目標値の次の主な内容というところで、２番目の緊急時の受入れというところで、２つ目の段落のところで、医療的ケアを要する障害児者に対する医療短期入所事業を実施したということで書かれているのですけれども、これは本当に医療的ケアの方のショートステイというのは求められていたところなのですが。","respondent":"川崎障害者施策推進課長、松山障害者支援課長、榎本荏原保健センター所長","answer":"私のほうから、整備費補助、令和４年度の実績についてですが、１件ございました。こちらは、医療的ケアがあり、なかなか通常のショートステイでは受入れができない方向けに開始しているものですので。開催時期につきまして、今年度は１１月から１２月ぐらいを予定しております。","voiceIndex":127,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どこにどんな働きかけをされたのかも伺いたいと思います。入るのかと思うのですけれども、その課題というのは本当にたくさんありまして、その解決というのは様々求められているところだと思うのですけれども、年１回でそこら辺のところが進んでいくのかと思っているのですが、これは区としては年１回で足りると考えられているのか、今後また増やすという考えはあるのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"これまで設置以降、なかなかコロナ禍の中の状況で、実際に参加する委員の方々が現場の方がほとんど、あるいは医師の方がいらっしゃるということで、本当にコロナ対応に追われていた方々の集まりということですので、残念ながら１回しかなかなか開催できませんでしたが。","voiceIndex":131,"id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうですね。分かりました。それがどれくらいされたのか、これは品福がされたものなのか、そこら辺のところも教えていただきたいのですけれども、開催の状況、年何回ぐらい行って、何人くらい参加して、実際に移動支援の仕事に就く人がどれぐらい養成できたのか、足りない実態がどれぐらい改善されてきたのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"という状況です。なかなか移動支援としては、今後もより充実させていかないと、お声に応え切れない部分もありますので、より力を入れて実施していきたいと考えています。","voiceIndex":133,"id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"よろしくお願いします。この在支の６か所も指定特定相談支援事業所ということでいいのですよね。そこら辺のところの状況も改めて伺いたいのと、拠点の相談支援センターが、訪問による支援というのは、具体的にどんなことが支援されたのかということも教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"地域拠点相談支援センターというのは、委員がおっしゃられるとおり、５か所あります。","voiceIndex":135,"id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"事業者をもっと誘致というか、が求められているのかと思うのですけれども、そこら辺は区としてどう考えられて、これからどういう手を打たれようとしているのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"実際、相談のほうも、ぽつぽつですけれども、うちのほうにも放課後等デイの事業所の相談開設というのも入っていますし、うちのほうも今後事業所の誘致というのを積極的に努めて、やはり放課後等デイ、親御さんにとってみれば、障害児の支援としては必要な場所になりますので。","voiceIndex":137,"id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ拡大できるようにということで、区としても取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問","question":"１８ページに実績のほうですけれども、こちらの数字が見込みが１,６６４人に対して実績が１,３８３人で、これに関して、移動支援事業の人材的なもの、下回っているのは人材不足とかもあるのかと思うのですが、その辺のご見解はいかがですか。","respondent":"松山障害者支援課長","answer":"移動支援事業に対する実績の要因ということについてお答えいたします。人材の確保というのが、移動支援事業については、比較的マンツーマンで対応するというものです。特にお子さんになりますと、通学等時間帯が同じ時間帯に集中するという傾向があります。","voiceIndex":141,"id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ご答弁ありがとうあります。ということで、恐らくこういった障害者福祉事業にも、やはり人手不足というのはあるのかと推測されますので、ぜひそういった移動支援ヘルパーを含めた人材確保、そして、研修等を積極的に実施していただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-056"},{"speaker":"こんの委員","kind":"質問・要望","question":"６ページの障害児支援の提供体制の整備等についてお伺いしたいと思います。この中で、まず目標値と主な実績のほうですけれども、保育所等の訪問支援の体制整備といったところをお伺いしたいと思います。この保育所等ということは、保育所のほか、どこの施設が入っているのか。改めて訪問支援という事業内容、確認をさせていただきたいと思います。そこをお願いします。","respondent":"松山障害者支援課長","answer":"保育所等訪問支援についてご説明いたします。「等」の中身ですけれども、例えば、具体的には、区立私立問わず、保育園、幼稚園、あるいは小学校、それから、学校という名がつくもの、恐らく専門学校まで含むということで、すごく幅広いです。","voiceIndex":145,"id":"exchange-057"},{"speaker":"こんの委員","kind":"確認","question":"ありがとうございました。確認させていただきました。保育園も幼稚園もということで、現状は今、区立の保育園と幼稚園だけですかね。それを認めたくないというような保護者もいらっしゃる。ここをどうにかしたいといったところでの訪問支援というのが必要だと取り上げさせていただきましたけれども、その後はどのようになっていますでしょうか。私立の体制も、今現状どうなっていますでしょうか。","respondent":"松山障害者支援課長","answer":"ただし、１回だけの説明ではなかなか難しいというところがございまして、私立も僅かですけれども、少数ですが、ご理解いただいているような園につきましては比較的スムーズなのですが、なかなか難しいところが、やはり受入れ側にご理解いただきながら、ご本人とご家族、そして園。","voiceIndex":147,"id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"現状今、行われている区立の保育園、私立のほうでは、いわゆるこの訪問支援員が入って、適切な療育なり、そうしたサポートにつながった例というのはどれぐらいあるのでしょうか。","respondent":"松山障害者支援課長","answer":"なかなかサポートにつながった例というのを数えてはいませんけれども、やはり比較的どうしても長期的な支援が必要なお子さん、あるいは園側、あるいは保護者側の納得も得た上でのものですので、なかなか実態的に、何名ですとは申し上げられないところなのですが。","voiceIndex":149,"id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"療育につなげるだけではなくて、園の中で、そのお子さんに関わる大人の方が、障害をその子の特性を理解して関わっていく体制が取れることによって、専門的な療育の場に行かなくても、園にいながら、あるいは家庭でも療育のそうした環境をつくっていくという意味では、サポートをしていただく支援員の方にアドバイスをもらって進めるというのは非常に大事だと思いますので、ぜひこれからも。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおり、お母様やお父様方、園の理解が本当に必要な、一番のお子さんにとってのサポートになるかと思いますので、そういった保護者の方や園側のお気持ちや体制に配慮しつつ、発達に応じて必要な支援を行ってまいります。","voiceIndex":151,"id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"１ページのところなのですけれども、障害児者の状況のところで、(3)の精神通院と手帳保持者数合計というのがありますが、年度を経るにつれ増えているのですけれども、ここから受け取ることは、精神障害の方が増加しているということでよろしいのでしょうか。","respondent":"坂野保健予防課長","answer":"これ、簡単なものではなくて、精神の手帳というのは、制度自体がすごく新しいのです。だからそれで増えている部分もあるでしょうし、実際に増えている部分もあるのかもしれません。なかなかそれは簡単には、こうですとは言い難いと思います。","voiceIndex":155,"id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"いろいろ難しい部分もあると思うのですけれども、制度が始まっての時間的なこともあると思うのですけれども、単純にこれ、増えているとは言えないのですか。","respondent":"坂野保健予防課長","answer":"要するに、制度が浸透しつつある過程なので。ただ、印象としては、若干増えている印象はあることはありますが、これは増えています、これは減っていますというのはなかなか簡単には言えないところかと思います。","voiceIndex":157,"id":"exchange-062"},{"speaker":"筒井委員","kind":"確認","question":"細かいことはまたお伺いしたいと思いますけれども、あと、２番目の成果目標の達成状況についてですけれども、この目標値というのはどういった基準で考えているのかということと、時々目標値の充実というところが出ていると思ったのですけれども、これは数値目標が難しかったところなのかということを確認したいと思います。","respondent":"松山障害者支援課長","answer":"あるいは、例えば、成果目標にありますように、精神障害にも対応した地域包括ケアシステムの構築といったような、これは国が基本指針で設定しているままの文言どおりのものを掲げさせていただいていますので、各自治体とも同じような目標にはなります。","voiceIndex":159,"id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。目標値の数字自体は自治体の実情に応じてということなのですけれども、それはやはり目標をクリアしやすい数字、ある程度現実的な目標値を区として考えて表示しているという理解でよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"先ほども、もう少し策定委員会でももっと意気込みを出してくれみたいなご意見もいただくことはあるのですが、ただ単に努力目標なのか、あるいは本当に現実に即した、実態に即した見込みを算定した数字なのかというところの、その中でも議論がございました。","voiceIndex":161,"id":"exchange-064"}]},{"id":"topic-04","title":"品川区医療的ケア児地域生活支援促進事業の仮移転","agenda":"品川区医療的ケア児地域生活支援促進事業の仮移転","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今度移るところは４２０m2ということなのですけれども、現在のインクルーシブひろばベルの平米数を教えていただきたいのが１点です。それから、これ、仮移転予定というのが来年の９月。それから、地域への説明とか、利用者とか、そういう関係する人たちへの説明会みたいなものはいつ頃されるのかについても伺います。","respondent":"松山障害者支援課長","answer":"地域または利用者への説明についてです。今後、本日の文教委員会でのご報告、それから、７月５日に行財政改革特別委員会でのご報告というのがございまして、それが終わってから地域のほうに説明をさせていただきたいと考えています。","voiceIndex":167,"id":"exchange-065"},{"speaker":"鈴木委員","kind":"意見","question":"旧耐震ではぎりぎりなのかという思いがするのですけれども、そこら辺の耐震性とか、そのようなところも改修で大丈夫なのかとか、そこら辺のところは、ここではないのかどうか分からないのですけれども、分かる範囲でお願いできたらと思います。","respondent":"松山障害者支援課長","answer":"建物についてのご質問です。昭和５８年に建築されておりまして、築３９年になります。今のところは改修で対応する予定です。","voiceIndex":169,"id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"仮移転先についてなのですけれども、利用者というのが送迎サービスで駐車場など、車を利用する方が多いと思うのですが、仮移転先に駐車スペース、また、送迎のサービスなどをつける予定はあるのか、教えてください。","respondent":"松山障害者支援課長","answer":"送迎についてです。現在もベルについては特に送迎というものはございません。仮移転先についても、特に今のところ予定しているものはございません。","voiceIndex":172,"id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問","question":"今現在通われている方々というのは、駐車スペースがなくて、送迎もないという状況であると、医療的ケアの必要な方々は荷物が多かったり、移動するのが大変だと思うのですが、今の現状で送迎を利用したいという声が出ていないのか、また、駐車スペースについての声も上がっていないのか、伺います。","respondent":"松山障害者支援課長","answer":"ただし、今のところ事業者側も、送迎サービスをやったほうがいいのではないかというところまでは、運営上、まだ踏み切れているわけではなく、仮移転なので、きちんと移転場所等が確立されて、また少し事業が軌道に乗ったら、送迎とかのサービスも考えようということで。","voiceIndex":174,"id":"exchange-068"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひその点について、これは要望になるのですけれども、やはり通う、また、相談に来たいと思っていても、なかなか足が遠のいてしまう理由に、交通の便というところは重要になってくると思いますので、もちろんＺｏｏｍなど、そういうところで相談できるというのも大切だと思うのですけれども、やはり行ってその場でお話をするというのと全然違うことだと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-069"},{"speaker":"こんの委員","kind":"確認","question":"確認だけです。大原児童センターの１階が、この医療的ケア児のベルだったのですけれども、そこが移転をする。というところの確認です。ベルのところは改修工事は行わないという理解でいいのか。いわゆる児童発達支援センターのほうは改修に伴うのですが、同じ１階のフロアとして、ベルのところはどうなるのか。その辺を確認させてください。","respondent":"松山障害者支援課長","answer":"改修後の１、２階の設定です。１、２階とも、児童発達支援センターとしてリニューアルはいたします。ベルについては、今のところ、想定では、児童発達支援センターの建物の中に戻ってくる予定です。","voiceIndex":178,"id":"exchange-070"},{"speaker":"こんの委員","kind":"質問","question":"私は、去年ですかね、視察させていただいて、施設の中も、現段階というか、あの視察をさせていただいたときには、このスペースで足りるかもしれないけれども、今後はやはり利用者が増えたときには、親子の交流の場というのももう少し広くあるといいというようなお声もあったかと思うのですが、仮移転先は４２０m2あるけれども、戻るとまた３００m2弱となってしまうとあれなので、そこら辺どのように。","respondent":"松山障害者支援課長","answer":"実際にスペース等の課題とかはありますけれども、改修設計を今年度予定しておりますので、その中でベルの運営事業者のお声も聞きながら、どのように新たな２か所目の児童発達支援センターとして有効に機能させていくかというところにつきましては、今後。","voiceIndex":180,"id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問","question":"今度の新しくできるときは建物の１、２階部分を児童発達支援センターということで、その一部にベルが入るということなのですけれども、ベルはＮＰＯ法人フローレンスが今やっていただいていますが、それは引き続いてずっとフローレンスがやっていただいて、児童発達支援センターは発達支援センターで、ベルを除いたところで公募か何かして決めていくという考え方なのか、そこら辺のところも教えてください。","respondent":"松山障害者支援課長","answer":"実際の児童発達支援センター等の運営の方法なのですが、まだ運営の方法については、今後、検討ということになっております。","voiceIndex":184,"id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問","question":"１ページの２の要介護認定状況というところなのですが、この要介護認定者数の認定率のところで、要支援の認定率が何％、要介護の認定率が何％ということで書かれているのですけれども、令和５年の３月の時点で、要支援が品川の場合４０.７％で、全国平均は２８％なので、要支援の割合というのが全国平均に比べて非常に高いと思うのですが、これは品川区としては、なぜ要支援がこれだけ多いのか。","respondent":"菅野高齢者福祉課長","answer":"審査は適正に行われており、その結果が全国構成比と比較して要支援の割合が高くなっているものと認識しているところです。続きまして、介護認定の結果の通知等についてです。委員おっしゃるとおり、本来ならば１か月以内に結果の通知ということになっております。","voiceIndex":190,"id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問","question":"適正に行われているということで言われているのですけれども、多分、全国も適正にされていると思うのです。それであるにもかかわらず、１２.７％も品川区が要支援が多いというのを、区としてなぜこんなに全国平均と比べて違うのかというところはどう捉えられているのか、そのことを伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"運営状況の中でも、１２ページ、１３ページに総合事業等の実施状況を掲載しておりますが、多くの介護予防事業を行っており、このような取組も一定程度効果が出ているのではないかと考えているところです。","voiceIndex":192,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"このようなところからすると、特定施設はピンからキリまでということで、十数万円から、地方に行けばそのようなところから、それから、区内の特定施設、有料老人ホームになると、１か月の利用料が５０万円とか７０万円とか、そういう利用料のところに介護財政が、例えば、要介護５であれば２６万円とか、利用料にプラスして支払われているというのが私は実態だと思うのですけれども。","respondent":"菅野高齢者福祉課長","answer":"３ページの特定施設の部分についてのお問合せです。特定施設につきましては、区内の特定施設、一定程度の定員数があるのですけれども、そのうちの大体４割ぐらいの方は区民の方が入居しているという状況で、それ以外の方は区外の方ということになります。","voiceIndex":194,"id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問","question":"私は、これは介護保険の矛盾ではないかと思っています。でも、これが１か月とか、１年丸々ではないということになると、これがもっと人数としては多くなるのかと思うのですけれども、滞納者の方の滞納されている理由というのを区として把握をされていたら、伺いたいと思います。滞納に対しての相談窓口というのはどこになっているのか、どんな相談がされているのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そこから一定程度、納めるものがないという場合には、徴収員という方を雇わせていただいておりまして、その方たちが丁寧に一軒一軒、滞納がたまっている方についてはお宅に訪問をさせていただいて、毎月少しずつ分納等を誓約している方が多いのですけれども。","voiceIndex":196,"id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問","question":"滞納の理由というのが、払いたくても払えないとか、貧困の状態だとか、そういうのがあって、こういう滞納の状況になっているのか。もしそういうことであれば、暮らし・しごと応援センターですとか、生保につなぐとか、そういう生活支援のほうにつなぐような相談というのが必要ではないかと思うのですけれども、そこら辺がどのようにされているのかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"もともと保険料は、前のページの９ページに保険料がありますが、その方の所得に応じて保険料というのが決められておりますので、普通徴収とはいえ、基準に則って保険料も決められておりますので、一定程度お支払いができるものと私どもは見込んでおりまして、公平性の観点から。","voiceIndex":198,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"多分、いろいろと全体像が、滞納者に対しての、区としてこんな状況になっているという状況をつかんで対応するというのが必要ではないかと思うのですけれども、一人一人に徴収員が出て、それに任せるというのではなくて、そこら辺のところがどうなっているのかというところを改めて伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今、こちらの保険料を納めているところは、高齢者福祉課の保険料係というところで対応しています。同じく高齢者福祉課には、高齢者支援第一、第二といって、いわゆる地域包括支援センター等の機能を果たしているような、そういった係もあります。","voiceIndex":200,"id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、最後に１つだけ確認なのですけれども、この滞納をされている方がもし介護サービスを使わなければならなくなったときには、ペナルティーが発生するという制度がありますけれども、仕組みになっていますが、品川区はそのように、滞納者に対してのサービスを制限するというペナルティーは課していませんというこれまでの答弁だったのですけれども、それは今もそういう形で。","respondent":"菅野高齢者福祉課長","answer":"今年度については４回開催をする予定となっておりまして、内容としては、８つのプロジェクトで推進していますが、その検証と、あとは、策定ということで、今後国の方針とかも出てきて、区の需給見込みとか、そういった部分を当てはめて保険料の設定とかもしていきますので。","voiceIndex":202,"id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"は２ページなのですけれども、事業所別のケアプラン作成割合なのですが、前提として、品川区は、いわゆる地域包括支援センターがほぼないといいますか、在宅介護支援センターという制度を設けられていますけれども、それはどういった理由というか、何か理念とか、そういったものをお聞かせいただきたいのですけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"そうすることによって、在宅介護支援センターで、例えば困窮されている方とか、虐待ケースとか、そういった気になる困難ケースがあったときに、即座に高齢者福祉課のほうで助言したりとか、場合によっては、そちらのほうで対応させていただいたりとかということで。","voiceIndex":205,"id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"つまり、そういった総合支援システム等があるので、いわゆる包括支援センターであるような、保健師とか社会福祉士が常駐していれば、そういったシステムというか、そういう体制は構築していなくても大丈夫だという判断ということでよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"ただ、現在の高齢者福祉課を統括型の、在宅介護支援センター、そして地域包括支援センターの直営とさせていただいて、各在宅介護支援センターをサブセンターという形で、サブセンターの地域包括支援センターという形にさせていただいて、そこで連携することによって。","voiceIndex":207,"id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。それで、在宅介護支援センターが２０か所あって、６８％ケアプランを作成されているということで、民間が３１.６％、これ、ほかの区と比べて割合というのはいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"品川区独自の在宅介護支援センターが、地域包括支援センターのサブセンターの役割を果たしているという、区と在宅介護支援センターとの関係性が他区とは少し違う、オリジナルというか、独自のものがありますので、他区と比較がなかなかできないとは思っております。","voiceIndex":209,"id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私が以前勤めていたほかの区に比べると、民間の割合が少ないかと思うのですけれども、それが何か決まった理由があるのかと思ったのですが、それはいかがですか。","respondent":"菅野高齢者福祉課長","answer":"民間居宅介護支援事業所の数等につきましては、これは自然に来ていただくものというか、特に民間居宅介護支援事業所に対しての厳しい規制とかをしているわけではございませんので、自然な形でこういう割合になっているのだと捉えています。","voiceIndex":211,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"かしこまりました。それとも、プラスアルファでそれ以外のいろいろな理由があるのか。そういったところをお聞かせいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"誰しもやはりご自分がずっと住み慣れた我が家で安心して生活をしたいというのがお望みだと思いますので、その部分を最優先に考えて、こちらの在宅介護に力を入れているというのが、第一の目的となっております。","voiceIndex":213,"id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"かしこまりました。１２ページ、７番の(1)の1)の柔道整復師による機能訓練訪問事業というものの概要をご説明いただきたいのですけれども。","respondent":"川原高齢者地域支援課長","answer":"こちらの柔道整復師による機能訓練訪問事業、目的としては、要介護状態にならないために、一人で外出するのが不安な方や閉じ籠もりがちな方の外出を支援するために、身体機能の向上のサポートを強化、充実させる必要があるという目的の下。","voiceIndex":215,"id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、訪問リハビリの要素が強いという理解でよろしいですか。","respondent":"川原高齢者地域支援課長","answer":"こちらの認識としては、柔道整復師を機能訓練指導員として、利用者の居宅を訪問して、自立支援を目標とした、外出の支援のための、その方に応じた身体的な動きの目標を設定して、運動指導ですとか歩行訓練を実施するような形です。","voiceIndex":217,"id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"柔道整復師はどのように募集してというか、どういう形で派遣されていらっしゃるのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"公益財団法人の東京都の柔道整復師会品川支部に委託をしている形です。","voiceIndex":219,"id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"品川支部に委託していると。これ、もし継続してこのサービスを持続していく場合、例えば、区内にある整骨院とか、柔道整復師がいらっしゃるようなところから派遣されるとか、そういったことはお考えでしょうか。","respondent":"川原高齢者地域支援課長","answer":"実際に訪問していただいているのは、区内の整骨院の柔道整復師がご自宅に訪問しているような形です。","voiceIndex":221,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"かしこまりました。それで、そのまま１２番の下の介護予防ケアマネジメントの予防事業なのですけれども、その実績なのですが、前年比とか、この数年で比べて伸び率といいますか、利用率というのは、回数とかというのはいかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"それに併せまして、事業対象者およびこちらを利用する、サービスを利用する要支援者のケアプランの作成実績１,４８８人に対して、令和３年度は１,５２７人という形で、こちらも併せて減っているという状況です。","voiceIndex":223,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"なので、ぜひこういったところに積極的に力を入れていただきたいと思っておりまして、それがある種、介護関係の支出の抑制にもつながるかと思っておりまして、それで、１点、これ、建設関係になってしまうかもしれないのですけれども、例えば、こういう予防できる施設のところにコミュニティバスが止まるみたいな、要は、なかなかケアマネジャーとお話ししていて、例えば、リハビリさせたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-090"},{"speaker":"こんの委員","kind":"確認","question":"現状だけ確認させてください。活動実績から想像すると、なかなか登録はしたけれども、活動ができていないのか。この実績はどのように捉えていますでしょうか。このポイント事業は始まってからかなり年数がたっているかと思いますけれども、この事業を今後どのように展開しようとお考えなのか、その辺をお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"こちら、社協に委託をしている事業でして、定期的に社協と連絡会議をして、今後の対応についても話し合っているところでございまして、今後の展開というところで、やはり高齢化が進む中で、実際に登録の人も７５歳以上の方で登録されている方がすごく多くいらっしゃるので。","voiceIndex":227,"id":"exchange-091"},{"speaker":"こんの委員","kind":"提案","question":"コロナ、そうですよね。数字だけを見ると、見直しというか、今後の展開というのはどうなってしまうのだろうかと思ってしまうところですけれども、引き続きそうした皆さんが社会参加できるようなメニューも、そうするとそろえていくということになるのでしょうか。具体的にこういうボランティア活動があるといいという提案できるものは今ないのですけれども、いかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"そういったところで、それを受講した方がさらなるボランティアの担い手として、今度新しく利用する方を、ボランティアとして支援してくださっている、そういった事業を増やしている中で、ボランティアの活動の場もより増やしていきたいと考えています。","voiceIndex":229,"id":"exchange-092"}]},{"id":"topic-05","title":"品川区立健康センター指定管理者候補者の公募","agenda":"品川区立健康センター指定管理者候補者の公募","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"健康センターが平成２１年度から指定管理者制度になっているということなのですけれども、こういうことは今まで５年ごとだと３回ぐらいされていると思うのですが、現在は住友不動産エスフォルタ・ＮＴＴファシリティーズとの共同事業体ということになっていると思うのですけれども、その前の２回というのはどんな事業者がなっていたのか。これまでの経過を教えてください。","respondent":"若生健康課長","answer":"過去の指定管理者の指定に関してですが、今期は令和元年度から開始しておりますので、その前の期、平成２６年度から平成３０年度につきましては、住友不動産エスフォルタ・ＮＴＴファシリティーズ・住友不動産リフォーム共同事業体という。","voiceIndex":236,"id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その確認と、それから、荏原健康センターは、今度、今建て替えのために、旧第一日野小跡に移っていくと思うのですが、そこのところで、保健センターのほうは元にまた建て替えして戻るけれども、健康センターのほうは、旧第一日野小学校、ＴＯＣに貸し出していたところにそのまま残るという方向だと説明を受けていますが、そこになるときにはまたこの５年間の後になるのかということで。","respondent":"若生健康課長","answer":"委員ご指摘のとおり、荏原健康センターにつきましては、保健センターは改修後戻る予定ですけれども、健康センターについては、旧一日野の仮移転の場所に、これは予定では令和１１年度まで仮にというか、そこの現在の移転の施設で運営を行って、その後につきましては。","voiceIndex":238,"id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後の予定のところから確認なのですが、聞き漏らしていたら申し訳ありません。公募についての説明会というのは行わないのでしょうかというところです。これまで３者共同事業体で行っていたということなので、公募して、募集をかけて、それ以外のところと競争原理が働く中でよりいいところを選んでいただきたいと思うのですけれども、その点はいかがでしょうか。","respondent":"若生健康課長","answer":"ここに関しての説明会ですけれども、こちらについては、参加申込みの資料のほうに、７月下旬に品川健康センターのほうで説明会と施設見学会、それからその後、荏原健康センターのほうでも見学会を併せて行う予定です。","voiceIndex":241,"id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで大体どういう会社が来られて、その後、応募してくるのかというところだと思いますけれども、これまで、そんなにというよりも、声は聞いたことはあまりないのですけれども、１期２期と共同事業体でされてきた中での健康づくりの事業、運営、これについては、特段、利用者さんの声とか、あるいは、もっとこうしてほしい要望みたいなものとか、あるいは逆で、課題などとか。","respondent":"若生健康課長","answer":"これまでの指定管理者についての実績といいますか、評価ですが、１期から一貫して住友不動産エスフォルタが代表指定管理者として、共同事業体ということで運営していただいておりまして、その間、利用者数のほうは。","voiceIndex":243,"id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、評価をお聞きをしましたので、この事業者が応募してきた場合、こうしたところも視点に一つ入るのだと思うのですけれども、いろいろな利用者が利用しやすい、コンビニでも健康づくりができますみたいな、簡単にできる健康スポーツセンターみたいなものも出てきておりますので、より利用者が利用しやすい体制みたいなところの視点も持ち合わせて選定してみるというのもいいのかと思うところですけれども。","respondent":"若生健康課長","answer":"しかも、コース型のプログラムですとか、フリーはもちろん、そういったところも年々充実させていっておりまして、利用者の層ですとかニーズも日々聞き取った上で、そういったところをできるだけ反映したプログラムを、お子さんとか親子で参加できるものから、高齢の。","voiceIndex":245,"id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"フィットネスクラブ、今、お答えいただきましたけれども、いろいろな形態が出てきているというところですが、それは一つの例で、区としての行政がやる特有のというか、サービスとしてのいろいろな視点からのと。これから、先ですけれども、第４回定例会で上程されるということですので、また事業者がどのように決まったのかというのは、そのときに伺っていきたい。このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-098"},{"speaker":"筒井委員","kind":"質問","question":"今回、指定管理に当たって、品川区指定管理者制度活用に係る基本方針に則っていると思うのですけれども、これ、今回、設置条例というのはないのですか。","respondent":"若生健康課長","answer":"健康センターに関しては、公の施設になりまして、条例の根拠を持っております。健康センター設置条例というのを制定しています。","voiceIndex":249,"id":"exchange-099"},{"speaker":"筒井委員","kind":"質問・要望","question":"その健康センター設置条例に、それで指定管理者を選ぶということなのですか。それとも、指定管理者を選考するのは、あくまでも基本方針で選んでいくということなのでしょうか。その辺りを整理させていただきたいと思います。","respondent":"若生健康課長","answer":"そもそも地方自治法で公の施設の管理というところの規定がございまして、指定管理者を選べるものとして公の施設というのがありますので、そういったところで、公の施設に指定管理者を置く場合は、条例でその根拠を定めるということになっておりますので、条例のほうにも。","voiceIndex":251,"id":"exchange-100"},{"speaker":"筒井委員","kind":"質問","question":"それで、今現在、住友エスフォルタが３期続けてやられているのですけれども、ほかに１期２期と住友が指定管理者と決定されたわけですが、１期２期の公募のときに、ほかのある意味競争相手となる業者というのは何者かあったのでしょうか。","respondent":"若生健康課長","answer":"２者で行ったという。２期につきましては、これは住友不動産エスフォルタ・ＮＴＴファシリティーズ・住友不動産リフォーム共同事業体以外の応募者についてはなしということで、１者のみと。３期につきましては、選定以外の候補者がほかに２者ございました。","voiceIndex":253,"id":"exchange-101"},{"speaker":"筒井委員","kind":"提案","question":"公正かつ厳正な審査をお願いしたいと考えておりますけれども、その点、区のご見解はいかがでしょうか。","respondent":"若生健康課長","answer":"これまでも３期にわたって、結果的には同じというか、主要な指定管理者については変わらずというところになっておりますけれども、その都度、選定に関しては、条例ですとか指定管理者の基本方針等に則って、公正かつ厳正な審査を行ってまいりましたので。","voiceIndex":255,"id":"exchange-102"}]},{"id":"topic-06","title":"荏原保健センター等複合施設大規模改修工事","agenda":"荏原保健センター等複合施設大規模改修工事","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"今利用されている方も多くいる施設になっていると思いますので、仮移転先でもしっかりと利用者が利用しやすい状況をつくっていただきたいというのと、居ながら工事というところでありますと、きっと居ながらというのは、工事しながら近くでということなので、きっと工事の音などでいろいろとご意見とかが出てくるのではないかというのは推測されますので。","respondent":"菅野高齢者福祉課長","answer":"第一に、入居者の方には、入居の申込みのときに、既に１年ぐらい前から、令和５年７月から大規模改修工事をしますということで、ご了解の上、入居をしていただいているというところと、あとは、居ながら工事ということですが、前例がございまして。","voiceIndex":263,"id":"exchange-103"},{"speaker":"ひがし委員","kind":"質問・要望","question":"きっと事前に説明されていて、分かったといって入ったとしても、実際に行われていくと、今までと違うという状況で、いろいろなご意見というのが出てくると思いますので、今、ご答弁いただきましたように、しっかりと入っている方々の声を聞きながら、対応策というところもその都度立てていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、そのような工事を保健センターのほうが１７日までに提供して、その後、特養ホームの仕様に保健センターのほうを変えて、特養ホームがそこに移って、それから特養ホームの改修となるのかと思うのですけれども、そこら辺のスケジュールがここのところでは見えないのですが、特養ホームの移れるまでの改修というのは、保健センターのほうはいつぐらいまでにして、特養ホームがこちらに移って。","respondent":"榎本荏原保健センター所長","answer":"今後、施工業者が決まった段階で、併せてチラシ等の配布を近隣の住民の方に行い、都民住宅の方にも説明会を行うような計画になっております。","voiceIndex":267,"id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問","question":"保健センターというのは多くの区民が利用する施設でもありますし、また、改修というのも、これは大規模改修なので、かなり近隣に対しての騒音ですとか、いろいろな、そういう点では負担もかけることになっていくと思いますので、近隣の方皆さんが参加できるような説明会というのは必要ではないかと思うのですけれども、８月から準備工事が始まるわけですから。","respondent":"榎本荏原保健センター所長","answer":"最後に、先ほども申し上げましたとおり、チラシ配布等で施工者と区が併せて近隣住民の方のところに回っていくことで、今回は対応を考えています。","voiceIndex":269,"id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"町会長から町会の会員のところに、その説明をするようにということを求めるというわけにはなかなかいかないと思いますので、チラシ配布というだけだと、中身がよく分からないですし、特に保健センターにしても、特養ホームにしても、多くの区民が関わる、こういう施設ですから、私は近隣への説明会というのは、ぜひ説明会という形でやっていただきたいと思うのですけれども。","respondent":"榎本荏原保健センター所長","answer":"大規模改修工事におきましては、先ほど、現に住んでいる方、都民住宅とか、近隣の方には、一定程度の説明をしてやっていくということで、今までも改修工事については、そんな形で行っていたということで、今回はそのような対応となっております。","voiceIndex":271,"id":"exchange-107"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今までもそうだということなのですけれども、ふれあい掲示板ですとか、チラシとか、町会長というだけでは私は十分ではないのかと思います。もしこれから地域の方からの声が上がったりとかということがあれば、途中でもぜひ説明とかは丁寧にしていただきたいということで、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-108"},{"speaker":"こんの委員","kind":"確認","question":"既にされているかと思いますけれども、保健センターも、オアシスルームも、健康センターも、仮移転のところで運営ということですので、利用者には既にこのことは伝わっているのですよねという確認と、あと、保健センターのほうでは、乳幼児の健康診査なども行われるので、これが約２年半ぐらい、仮移転の場所までそちらで健診を受けるという体制になるというところでは。","respondent":"榎本荏原保健センター所長","answer":"予定というよりも、仮移転をいたしますので、その後、間違えていらしてしまう方もいらっしゃると思いますので、健診の日などについては、職員を配置して、丁寧にご案内するという形で対応したいと考えています。","voiceIndex":275,"id":"exchange-109"},{"speaker":"こんの委員","kind":"確認","question":"乳幼児健診のほうがすごく気になったところだったので、地図上で見たら、延長線上にあるような感じなので、距離にすると結構あるし、山坂というところでもあるという感じも受けなくはないのであれですけれども、ご理解をいただきながらするしかないと思いますので、すみません、丁寧にしてくださるということですので、お声がけと、それから紙ベースでとおっしゃっていましたけれども、乳幼児のママたち。","respondent":"榎本荏原保健センター所長","answer":"ホームページにも仮移転のお知らせということで、地図も含めて掲示をしております。更新した後も、またそれに合わせて変えて、内容をより分かりやすくお知らせをする必要があると考えておりますので、そんな形で対応したいと思います。","voiceIndex":277,"id":"exchange-110"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"こんの委員","kind":"提案","question":"確認ですが、今提案された方向性、明石市のほうと。ちなみに、明石市のほうは何のテーマでこちらを選ばれたのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":285,"id":"exchange-111"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、これ、全部のテーマが、一つの自治体で全部調査ができるというところを選んでいるということですか。そういう理解でいいですか。多分、この中の一つのテーマとして明石市が、例えば、障害者福祉が明石市は事例として見てきたほうがいいというふうに選ばれているのではないかと思ったのですが、そうではないのですか。その辺、確認させてください。","respondent":"松永委員長","answer":"それ以外にも、健康推進のほうでも関西方面で、例えば、大阪のほうでもやっているところがありますので、それも含めて今考えている最中ですので、今検討中です。","voiceIndex":287,"id":"exchange-112"},{"speaker":"こんの委員","kind":"質問","question":"繰り返しになりますが、明石市については何のテーマと決まっていらっしゃるのですか。要するに、障害福祉なのか、高齢福祉なのか、精神福祉なのか、はたまた地域共生なのかというところは見えていらっしゃるということなのですか。","respondent":"松永委員長","answer":"高齢者福祉に関しては、先ほどの在宅高齢者の生活支援の移動の支援とか、もう一つは、フレイル予防について等も含めて今検討中であります。明石市のほうでやっているということなので、そちらのほうにと考えています。","voiceIndex":289,"id":"exchange-113"},{"speaker":"こんの委員","kind":"提案","question":"分かりました。ほかのテーマについても関西方面でというふうに、周辺でといったところだと思いますので、何かこちらも提案できるものがあれば、探してみたいというか、研究テーマとしてしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":291,"id":"exchange-114"},{"speaker":"鈴木委員","kind":"提案","question":"兵庫県明石市を中心にということで、その近辺で行ける範囲のところであれば、これからまだ提案をしても検討いただけるということで、いつ頃までに提案とかというのはあるのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":293,"id":"exchange-115"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました。先ほど１０月２５日から１１月２日までということなのですけれども、これはもちろんコロナが今は５類になって、取りあえず落ち着いているということを前提にして、それがもしもまた本当に第９波が拡大したとかといったときには、またどうするかというのは検討することはあるということですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":295,"id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":84189,"voices":304}},{"id":"r05-20230704-8","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"建設委員会","time":"午前１０時００分～午後 ４時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を89件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"八潮五丁目地区まちづくりガイドラインの策定検討状況","agenda":"八潮五丁目地区まちづくりガイドラインの策定検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"実際には入ってきてしまっているという話も聞いているのですけれども、１３ページの真ん中辺りのところなのですが、そこは区がどう考えているのかというのを伺いたいと思います。その下、事業所が１０６か所あるということなのですが、クリニックとか、パトリアのところを考えてみても、１０６か所いかないなと思っておりまして、どういったところが入っているのかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２３ページの２段目の移動手段というところで、ここで記載する移動手段も含めて、八潮団地内の今回のガイドラインにつきましては、何か具体的な再開発等があるわけでもございませんで、現状進めている各主体が、取り組んでいることを、地域の課題・魅力を共有しながら。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、事業所は、店舗があるところだけでなく、どこかマンションの１室で事業をやっている方とかもいるということですか。分かりました。それと、八潮団地ができてから４０年ぐらいたとうとしているということで、建物の建て替えとか修繕費用がこれから様々かかってくると思うのですが、そこについて、区として何か支援できることがあるのかも含めて、お考えを伺いたいと思います。","respondent":"森道路課長、河内環境課長、鈴木都市計画課長","answer":"八潮団地内の３ｔ規制につきましては、少しお時間をいただいて、後ほど答弁させていただければと思います。区のほうから値上げ分補助があるかですが、東京熱供給株式会社から説明を受けた内容によりますと、高騰するエネルギー費用。意見募集で主なご意見として記載させていただきました、入浴設備のあるシルバーセンターというところで、計画の案の中では、２４ページの２の２段目。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"熱供給のところでは、今回、臨時的ということなので、課題として捉えるというお話だったので、ぜひ区としても支援ができるのではないかと思いますので、そういった点でもご検討いただければと思います。具体的な要望も伺ったのでお話ししたいのですけれども、今、八潮は郵便局が１つしかないということで、そこのＡＴＭが１つで、スペースとしても狭いということで、外に並ばなければいけないと。緑の件です。","respondent":"鈴木都市計画課長、森道路課長","answer":"いただいたＡＴＭ等については、やはり様々な生活支援機能について、利便性ですとかそうしたところの充実というのは、しっかり事業者にも働きかけていかなければいけないですけれども、地域活動課で所管しておりますまちづくり。通過車両が実際３ｔ以上のものが入ってきている可能性があるですけれども、区としてつぶさに把握してはいませんが、そういった規制があるということですので、警察のほうと情報共有しながら、対応してまいりたいと考えております。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"緑のところでも、適切にということなのですが、当然倒木とかしてしまっては困るのですけれども、大量に伐採されると、住民の方たちは樹木がなくなったということで、心配というか、これまで育ててきた緑がなくなってしまうということになってしまうので、そこは十分説明もしながら、緑を保全していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、全戸配布などでアンケートなども行っているわけなのですけれども、この案をつくるに当たって、ワークショップをやられて、参加されたのが７５人ということで、１回当たりにすると８人ぐらいなのかなというところなのですが、八潮の住民の多くの方がここに参加できているという状況ではないと思いますので、やはりガイドラインをつくっていくに当たって、より多くの方に参加していただくということと。","respondent":"鈴木都市計画課長","answer":"八潮みらい懇談会の中で説明し、意見をいただいて、８月以降、策定・公表を今目指しているものですが、これまでも、コロナ禍の中での検討ということで、時間はかかっておりますが、平成３１年のまちづくりアンケートから始まって。","voiceIndex":16,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"確認したいと思います。目的ですが、これは何のためのまちづくりガイドラインなのでしょうか。現状把握のところがありますが、５ページ、６ページのところ、団地に住んでいる方々、分析をいろいろしているのですけれども、どういう構図になっていくのということです。それをどう捉えて、これから何年先の八潮地区の状況を考えながらこのガイドラインをつくろうとしているのか、まずそこを確認させてください。","respondent":"鈴木都市計画課長","answer":"その様々な主体が課題や魅力を共有することで、連携を深め、さらにまちづくりを進め、魅力を高めていっていただきたいということでのガイドラインでございまして、今ご説明した高齢化あるいは単身世帯の増加等については、この計画の中でもコミュニティというところで。","voiceIndex":19,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"だけど、このまちづくりガイドラインは、八潮地区のグランドデザインですね、これから１０年先、２０年先を踏まえた形で、どういうまちにしていくのですかという議論につながると私は思っていました。だったら、もっとそれを、どういうふうに次の世代につなげていくのですか、次の八潮の姿をどう考えていくのですかというふうにつなげていかないとおかしいのではないですか。そこの考え方を教えてください。","respondent":"鈴木都市計画課長","answer":"当然ながら、ほかの団地再生の事例を見ても、団地の更新というのは非常に長い期間検討がされて、そこに向かって機運を高めていって、地域の人と一緒に考えながら、どういう機能更新が必要か。","voiceIndex":21,"id":"exchange-007"},{"speaker":"西本委員","kind":"提案","question":"今だからこそ、やらなければいけないのではないですか。その場合、長くかかるわけです。私が、提案の中で幾つかありますけれども、７、８ページを見ていただくと、八潮地区というのは様々な教育施設がたくさんあるのです。ソフト的な開発というか特徴を活かすというのであれば、八潮地区は教育ではないですか。だって、これだけ立派な施設がそろっているではないですか。難しいかもしれない。非常に残念です。","respondent":"鈴木都市計画課長","answer":"八潮地区に目を向けますと、１０年前のまちづくりマスタープラン策定、それ以前は、品川区のまちづくりビジョン的なものもあるわけですが、各地区ごとでのまちづくりの方針、目標というのはマスタープランのほうでも定めております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"今、広域的な役割というのがありました。八潮地区はそこに近いわけです。そこまで広げて、地域の方々と夢を語ってほしいのです。あそこが足りない、ここが足りないという、そういう足りない足りないという話ではなくて、これからどういうふうに夢のある八潮地区にしていきましょうかというふうに話し合って進めていただきたいと私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"そういうものを一つ一つ丁寧に改善することによって、バリアフリー化、バリアフリーの改善をしなければいけないと思いますし、また、構造的にまちのつくりとして、Ａ地点からＢ地点に行く場合に、健常者は段差も越えて直線で行けるような地域も、例えば車椅子を利用されている方にとると、大きく迂回しないとたどり着けないようなところが実は結構ありまして、そういった視点からのバリアフリー化。","respondent":"鈴木都市計画課長、森道路課長","answer":"本来、そうした内容をぎゅっと網羅的に記載するという書き方もなくはないと思うのですが、まさに先ほどご説明したように、八潮はこれまでガイドラインあるいはビジョン的なものが一切なかったという中での第一歩としての計画として。ガイドラインの１２ページに記載しておりますが、八潮団地内の周辺の区道につきましては、数年かけましてバリアフリー工事をさせていただきまして、歩道の幅員を広げたり、段差を解消したりという形で対応しています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"一方で、先ほどの都市計画課長のお話だと、第一歩のプランだということではあるのですけれども、これはもっと重要視、何というのですか、もっと突っ込んだというか、せっかくつくるのであれば、もっとしっかりとしたような、西本委員のご指摘に同感でありまして、しっかりとしたプランにすべきだと考えています。","respondent":"鈴木都市計画課長","answer":"区としては、地域の声もお聞きしながら、この計画にも位置づけておりますが、団地内のバリアフリー化に向けて、これからまず計画をつくって、様々なお声もお寄せいただくことになると思いますので、いろいろとお声を聞きながら、地域の声に耳を傾けながら。","voiceIndex":30,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"一方で、高齢化が進んでいる中で、ここにはあまり書いていないのですけれども、若い世代を再び呼び戻そうとする取組というのでしょうか、住宅系は全て品川区外のものなので、住宅のものはつくれないのかもしれませんが、ファミーユなどは中堅ファミリー層の方を対象にした住宅政策ですが、そういったものを区が率先してこの中につくって、高齢者の方にも優しいまちづくりをする一方で。","respondent":"長尾建築課長、鈴木都市計画課長","answer":"今、八潮団地の中にある私有の通路につきまして、劣化を補修するという観点以上のバージョンアップといいますか、質を高めていくような工事というところは、基本的にどこまで併せて対応できるかというところは。ファミーユ等、区として居住機能の新設というご質問をいただきましたが、八潮団地内は、現在のところ、居住機能については、都営、民間も含めて、それぞれが敷地に立地しているというところでございまして、今。","voiceIndex":32,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"２８ページにありました一団地認定の関係なのですけれども、大きな団地をつくるときには一団地として認定することのメリットはありますが、経過とともにそれぞれの建替えが進む中では、これは外さないと個別の対応ができなくなるので、私も都議会でも少し触れたのですけれども、いわゆる区においての地区計画を前提にしていけば、一団地一斉にではなくて、個別に。","respondent":"鈴木都市計画課長","answer":"建築基準法上の一団地というのはなかなか外せないところがありますが、ただ、建築基準法上の一団地というのは、一敷地一建物という考え方ではなくて、例えば先ほどご説明したエレベーターをつくるような場合に、全体の中で申請を出していただくという手続上のお話ですので。","voiceIndex":35,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"ありがとうございました。４０年以降、今後、５０年、６０年に向けて、八潮の皆さんにとって住みやすい環境づくりに向けて、このガイドラインが活かされるように期待し、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"簡単に確認だけ。今の一団地規制のお話で、都市計画法は今もう外されて、建築基準法のほうは残っていると。関わりがあってもなくても、考え方として、それは全部オーナーの考え方でしょうけれども、住んでいる方にとっては大変大きな影響、今の３０代、４０代、５０代の方は住み続けるのであれば、現実にそういう時期が見えてきているという時期でもあるとは思うので、今、考え方だけ教えてください。","respondent":"鈴木都市計画課長","answer":"そうしますと、一団地の手続的なところを残して行うのか、それを使いながらというか、残しながらやるのか、あるいは、一定程度広い範囲で整理をして、新たな一団地なのか、また違う方法でまちづくりを進めていくかは、各建物所有者とも意見交換をしながら。","voiceIndex":39,"id":"exchange-015"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"１つは、防犯カメラなのですけれども、現状、防犯カメラは区道になしということで、これからつけていきますという計画がありましたが、これ、なしというのは、もともと八潮の自治会から、要は防犯カメラ取付の助成もありますけれども、声がなかったのかというのを教えていただきたいのと、駐車場は、今、団地にもいろいろあると思うのですけれども、駐車場の稼働率というのですか、きちんと埋まっているのか。","respondent":"森道路課長、鈴木都市計画課長","answer":"防犯上というところもありますけれども、基本的には見通しのいい区道が連続しているということもありますので、そこまで区道に設置することの必要性というところは、ほかと比べてはないのかなと考えています。アンケートの結果ですが、今回３２％ということで、まちづくりアンケートのほうでも、総数はもっと数が多かったのですけれども、同様の３０％前後の回収率というところで、一般的な回収率よりも多少低いところはありますが、一定。","voiceIndex":42,"id":"exchange-016"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"防犯カメラは、見通しがいいということで、自治会から要望が特にあるわけではないということですね。駐車場のほうも、おっしゃるとおり、だんだん免許を返す方もいらっしゃるので、自治体とよく話し合って、今後、まちづくりではないですけれども、うまく活用していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"一つだけ、今話を聞いていて思ったのですが、これから区が、こういう団地というのはどんどん高齢化していくということで、どこの団地もそうなのでしょうけれども、これから若者が帰ってくるような、何か若者を呼び戻すようなアイデアというものを考え、そういう計画というものは絶対に考えられないことなのかどうか。それがあれば、お聞かせください。","respondent":"鈴木都市計画課長","answer":"それからあと、声として伺っているのが、今、テレワークが進む中で、こうした水辺あるいは緑豊かな環境で、自宅でテレワークを進めるに当たっては非常にいい環境、あるいは、ここにサテライトオフィスではないのですけれども、１室借り切って。","voiceIndex":47,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"やはり行政側からどんどんと、団地イコール高齢というのが完全についている、決まっているような状況、そういうふうに思っているのですが、そこに、今言われたように、何か行政側が若者が集まるようなアイデアをどんどん出していく、もしそういうことができれば、またお願いをしたいなと思います。これは要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"}]},{"id":"topic-02","title":"東京港第９次改訂港湾計画","agenda":"東京港第９次改訂港湾計画","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"この事業自体は東京都のものなので、品川区との関わりについて確認させていただきたいのですが、これは１０年ごとに改訂されるということで、まず１つは、品川区に関わる部分だけでいいです、全部ではなくて。それら含めて、品川区に係る部分で、今後、２１日に協議していくわけですので、その辺、教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"一つは、できるだけ貨物が並んで待機することがないように、様々な技術革新で、スムーズに、計画的にトラック貨物を受け入れられるような取組を進めていきますと。現在も進めているところですがと伺っているところです。","voiceIndex":54,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"これはやはり品川区にも非常に関わってくるものだと思うのです。値段の問題もありながら、結構早くなっているのです。そうすると、品川区にもやはりその影響が大きく出てくる部分はあるのかなという思いがあるのですけれども、その中で、これから将来に向けて、品川区としてはこういう観点で確認していきたいとか、そういう課題とかがあれば、教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"港湾計画自体が、貨物的な目標の数字をしっかり定めて、それに向かって整備を進めていくという基本的なことがありますけれども、区としましては、やはり臨海部の、特に物流貨物として使われている反面、裏を返すと、品川区が水辺に接している区でありながら。","voiceIndex":56,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"それで、今、この計画の中で、環境の脱炭素というところが書かれておりますけれども、船の排気ガスというのですか、そこの規制があまりないという私の認識なのですが、今、それはどうなっているのか。それは脱炭素社会に向けて規制などしていくべきではないかなと。公害も含めてですね、必要ではないかなと思っているのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"環境の側面ですが、本編の１７ページの未来へつなぐグリーンポートというところで、様々、未来へつなぐ技術的な、港湾の中でも導入を進めていくという位置づけがされているところです。","voiceIndex":59,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"船の、排気ガスと言うのか分からないですけれども、そこの環境規制というのは現状どうなっているのかというのが分かれば伺いたいのと、そこの区の考えも伺えればと思います。","respondent":"鈴木都市計画課長","answer":"申し訳ございません。船舶に関する排気量ですとか、そうしたところの規制があるかどうかというのは、現在、把握してございません。","voiceIndex":61,"id":"exchange-023"}]},{"id":"topic-03","title":"大井・西大井地区における密集住宅市街地整備促進事業の開始","agenda":"大井・西大井地区における密集住宅市街地整備促進事業の開始","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"昨年１１月に説明会を実施したということで、そこの参加人数と、どういった意見が出されたかというのを伺いたいと思います。今回、道路ですとか公園ですとか、整備の方針がいろいろ出されているわけですけれども、これを実施していったときに、住宅街なので、住宅への影響がどれだけのものになるのかと。何棟立ち退かなければいけないのかというところが分かれば伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"初めに、昨年１１月に行われました説明会の参加人数ですが、説明会は計２日実施しておりまして、合計で３２名の方にご出席いただいてあります。","voiceIndex":67,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"そうしたところで合意形成がどこまでできているのかなと思うのですが、区の認識を伺いたいと思います。今、立ち退きではないということなのですが、すみません、そこは言葉のあれですけれども、道路、場所によってということでしたが、全体として道路を整備したらどれくらい、あるいは公園を整備したらどれくらいというのは把握されているのではないかと思うのですが、いかがですか。","respondent":"小川木密整備推進課長","answer":"こちらの地区に関して、平成２１年から検討が広く行われておりまして、地域での検討会等でも、平成２１年からですが、３７回、また、意見交換会、説明会等も積み重ねてありますので、かなり丁寧な事業の計画等が進められてきているのかなと考えているところです。","voiceIndex":69,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど道路では９５軒ということなのですが、そうすると、６ｍのところで、１本当たり３０軒ということですよね。それを要望しておきたいと思います。そして、この計画の中に補助３１号線が書かれておりますけれども、整備計画図がありますが、３１号線を整備していくという前段階にならないようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"小川木密整備推進課長","answer":"補助３１号線に関しましては、現段階の事業計画の中では優先路線として位置づけられておりませんので、整備については未定なところですが、こういった道路に接続するということで、今回、整備計画をつくらせていただいてあります。","voiceIndex":71,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"補助３１号線、ご説明のとおり、整備路線にもなっておりませんし、地域でも反対の声が上がっているというものですので、これは進めないように強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"いろいろ確認します。ここは努力義務ですから、すぐというわけにいっていないのです。街路灯も当然ながらあるわけで、そこもきちんと整備しなければいけないですから、それと同時に考えられているのか。それで、別紙の図を見ると、滝王子通りの線があって、３０ｍという青っぽい色があるのですけれども、この３０ｍというのは、ここも全部整備対象になるということなのでしょうかということが２点目。","respondent":"森道路課長、小川木密整備推進課長","answer":"拡幅がある程度見えてきたところで、無電柱化についても計画していく必要があるだろうと考えています。進めていく予定ではおりますけれども、その時期がまだ見えないので、今のところは構想段階という形です。細かく分かれていて土地がなくなってしまう、かかっている方にとっては死活問題といったところですが、こちらに関しましては、拡幅で譲っていただける部分に関しましては、しっかりと区のほうで購入させていただきまして、また。","voiceIndex":75,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"滝王子通りのところはこれからまだまだ進めていくということなので、引き続きお願いしたいと思います。なので、そこにチャレンジするわけですから、すごいなと思いますけれども、頑張っていただきたいと思いますが、いずれにしても、地域の方々には、先ほど説明会に３２人とか言っていましたけれども、まだ他人事、情報は行っていません。私もいただいています。あおっているわけではないですからね。","respondent":"小川木密整備推進課長","answer":"令和３年度・４年度も戸別訪問をやらせていただいておりまして、今年度、令和５年度も引き続きやらせていただいて、粘り強くこの事業の内容については説明をさせていただきたいと考えています。","voiceIndex":78,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、この議題とは外れてしまうかもしれませんけれども、防災対策という意味では、やはり別の意味でも、地域防災ということでは、地域の方々、一生懸命やっているのですよ、すごく一生懸命考えてやっているのですけれども、そちらも含めて、ハード的な整備ももちろん必要なのですが、まち全体で火災をしない、出さないというような取組なんかも、ぜひ強烈に進めていただきたいと考えていますので。","respondent":"小川木密整備推進課長","answer":"この地区に関しましては、委員おっしゃるとおり、道路基盤であったり老朽木造住宅であったりが密集しているところではありますが、我々も本事業、計画を基にしっかりと進めていきたいと考えています。","voiceIndex":80,"id":"exchange-030"}]},{"id":"topic-04","title":"大崎駅東口第４地区におけるまちづくり","agenda":"大崎駅東口第４地区におけるまちづくり","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１ページ目というか、１枚の資料のほうですけれども、今後のところで、都市計画の策定に向けた協議を行っていくと書かれておりますけれども、それは再開発事業の都市計画の決定に向けて協議を行っていくということなのか、そこを伺いたいと思います。それと併せて、そういった面も、新しい建物もありますので、合意形成の状況が、そういった話合いとかがされているのかも含めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"その当初のものについても、その中身に市街地再開発事業を中心とした事業の推進というところで進められてきているまちづくりが行われているところですので、都市計画につきましても、再開発に向けて進めていきたいというふうに考えてあります。","voiceIndex":94,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"今、約９０％弱の方が参加されているということで、それは、２つ準備組合があると思うのですが、どちらが何％なのか、どちらも伺いたいと思います。山手通り側の方々も、約９０％弱ということですから参加しているのだと思いますけれども、既に建てたりとかしてきている中で、今回こうした再開発に向けて進めていくというところで、どのようにお考えなのか、声を聞いているところがあれば伺いたいと思います。","respondent":"中道都市開発課長","answer":"権利者ですが、西地区におきましては、土地所有者が４６名、借地権者が７名です。東地区では、土地の権利者が２１名、借地権者が２名です。お互いに９０％弱の加入率です。","voiceIndex":96,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ協力しながらやっていくということだったのですが、資料のガイドラインの５ページのところに、この地域はポテンシャルが高いということで書かれておりますけれども、ほかの課題のところにも、駅至近のふさわしいまちなのかということで、計画されていないということで書かれておりますけれども、住民の方たちからすると、そういうポテンシャルとか、ふさわしいというのは、ある意味。","respondent":"中道都市開発課長","answer":"ポテンシャルですが、やはりこういった駅の近いところで、地元の方々もそうした地域特性を生かして、自分たちでまちづくりを考えていきたいというところで進めてきたというところは聞いてあります。","voiceIndex":98,"id":"exchange-033"},{"speaker":"のだて委員","kind":"意見","question":"様々ご説明いただきましたけれども、いろいろ課題を挙げて再開発を進めていこうというような内容なのかなと、再開発しなければ解決できない内容なのかというふうに受け止めておりますということだけ最後に言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"少し地理的に不明瞭なところがあるので、場所が違うということであれば指摘していただきたいのですが、まず、接合部分ということで、百反隧道です。その辺も利便性とか、それからにぎわいゾーン、人が集まるということを考えると、あそこの隧道の問題は、少し整備を考えていただきたいということが１つ。あの問題は、やはり解決できないものなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"飛んでしまいますけれども、あそこを一体的にやるとしたら、やはりそれは継続的な審議をされている、検討されているのではないかなと非常に大きな期待をして質問したいと思うのですが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"隧道におかれましては、今、委員言われたように、坂道の部分まで、このまちづくりの中で手がつけられるかどうかというのは１つありますが、地区内の道路をループ状に整備していって、そこからまた南にある高架下の道路の部分も、歩行者、自転車が安全に通れるように。","voiceIndex":103,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、接合部分です。継続的に協議しているということで要望もされていると思うのですが、なかなか解決策はないかもしれないのですけれども、やはり諦めずに、区は交渉していただきたいというふうに思います。人が代わってくると思うので、交渉する相手も、それはしていただきたいと思います。最後に、喫煙所、この周辺は喫煙所の問題も結構あって、解消されたのでしたかという確認をさせてください。","respondent":"長尾建築課長","answer":"コンテナ型喫煙所につきましては、大崎駅の東口側に最初に１つできまして、また今度、西口側のほう、バスの停留所のある付近に今年の４月にできたところです。","voiceIndex":105,"id":"exchange-037"},{"speaker":"西本委員","kind":"確認","question":"喫煙所、東口のほうの喫煙所も整備されて解決しましたという認識でよろしいですか。もう一度、確認させてください。","respondent":"長尾建築課長","answer":"道路上の部分に設置するに当たって、建築課のほうで許可の手続を申請を受けて行っておりましたので、私が把握している範囲でお答えさせていただきました。","voiceIndex":107,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"少し所管が違ったかもしれないです。喫煙所になると区民委員会だったかもしれません。人が集まるというのは、当然ながら、自転車、自動車、それからそこに集うわけですから、たばこの問題があって、ごみの問題、それからトイレの問題がいろいろ絡んでくると思うのです。なので、それは先々を考えていただいて、まちづくりをしていただければなというふうに思っておりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"各地区、様々、再開発、まちづくりが進められる中で、ここでの１つの特徴は、水辺に親しむということで親水性を求めてまちづくりが行われていますが、ここは鉄道との親和性といいますか、鉄道の存在もうまくループ道路沿い側の建物のつくり方だとかは、鉄道と共生するといいますか、鉄道に親しむというか、そういった観点のポイントが入ったまちづくりで、そこも特徴かなと思うのですが。","respondent":"中道都市開発課長","answer":"ですので、やはり見る、見られるというところもありますので、ＪＲのほうにもそういった要望を伝えて、一体的なまちづくりを進めていきたいと考えています。","voiceIndex":111,"id":"exchange-040"},{"speaker":"田中委員","kind":"意見","question":"ぜひ、ＪＲのイメージアップにもつながると思いますので、私は積極的に協力していただけるだろうと思いますので、そういった視点での働きかけもぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-041"}]},{"id":"topic-05","title":"戸越公園駅交通広場に関する都市計画手続き","agenda":"戸越公園駅交通広場に関する都市計画手続き","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"交通広場のところで関わる地権者の方、また、地権者の方の人数を伺いたいと思います。それで、説明会が２月に行われたということで、そこで様々意見が出たと思うのですけれども、そういった住民の方の声があったのか伺いたいと思います。併せて、都市計画案の意見書の受付もしたということですので、そこでもどういった意見があったのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"は駅前広場取付道路の整備における地権者の方の人数ですが、まだ正確には出ておりませんが、駅前広場と取付道路で現時点で約２６画地、地権者数については、今後の都市計画決定後に用地測量を実施し確定するものですので、現時点ではまだ未定ですが。","voiceIndex":118,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"正確な人数は分からないということですけれども、２６画地が関わるということで、やはり大きな住民の方たちの暮らしが変わるということです。先ほど説明会の中でも幾つか意見が出ているということで、私も参加させていただきましたけれども、その中でも交通広場が必要なのかという声がありました。むしろ自動車中心のまちづくりになっていくのではないかと思うのですが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"具体的に申しますと、連続立体化は、踏切の除却だけではなく、事業の効果を最大限に高めるとともに、効率的に事業を実施するという観点から、交通広場や周辺の道路を一体的に整備し、バス、タクシー等々の交通機関の連携や交通アクセスの改善など。","voiceIndex":120,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"まちの様相が変わるということなのですけれども、様相が変わることも、やはり自動車中心というまちが進められていく。それに沿った計画を進めていくということになってしまうと思います。そうすると、実際、区が掲げているウォーカブルなまちづくりということにはならないと思うのですが、改めて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"こちらは木密地域にもなってございまして、そういった課題も１つありますので、そことの接続、避難路の確保だとか、あとは、先ほど申したとおり、駅前広場のにぎわい、ゆとりのある空間を形成するために、ウォーカブルという視点も当然ございまして。","voiceIndex":122,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は、２９号線は必要ないと考えていますけれども、その歩きやすいまちづくりという意味でも、道路ができることによって、交通量も増え、歩きにくい、事故の可能性も増えていくというふうになると思いますので、区としても、こうした認識も持っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"この立体化はいつ頃と想定されているのでしょうか。多分２９号線の整備はまだまだ時間がかかるだろうという思いがあるのです。それに合わせて、この高架化を想定したということもあると、どちらかというと、こちらが先になってしまうのかな、何となくこのまちづくりという中で、その時期的なところが少し見えないので、どういうことを想定されているのかお聞きしたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"連立事業は、ほかの事業を見ましても、１０年とは言わないのですけれども、数年から数十年ぐらいかかりますので、事業認可取得後にしっかりと設計をした中で、その辺が明らかになってくるものと考えています。","voiceIndex":126,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"補助２９号線のところが令和７年度は非現実的だなと思うのです。まだまだかかるだろうなというふうに思っております。今度、反対側、駅前のほうは、まだ今、再開発を進めておりますけれども、そこは、東急ですか、スーパーが入るのですよね。人の流れも大分変わってくる可能性はありますので、それを踏まえて考えていただきたいというふうに思いますが、その考え方についてお聞きしたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、今回、高架化されることによりまして、高架下空間の利用が都市側で使えるという、貸付面積の可能とする１５％程度が使えるということもありますので、そちらにつきましては、行政需要だとか地域の皆様のご意見を踏まえまして。","voiceIndex":128,"id":"exchange-047"}]},{"id":"topic-06","title":"粗大ごみの品目別手数料の改定","agenda":"粗大ごみの品目別手数料の改定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"単価が上がっているものと下がっているものがあるというのは、今のご説明の中で、重量が軽くなっているということですね。それともう１つ、資料のところで見方が少し分からなかったのですけれども、最初の表になっている粗大ごみ手数料改定というものと、一番最後についている粗大ごみ手数料、区分２以上の改定というのがついているわけですが、この違いが分からなかったので伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"申し訳ございません。区分２のほうは、差し替えのほうの資料を見ていただければと思いますので、よろしくお願いします。","voiceIndex":134,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"すみません、今の机上配付と、事前にというところでは、何が違うのですか。１枚の説明文と、それから、添付資料が３ページあるのです。どれを対応させればいいですか。","respondent":"品川品川区清掃事務所長","answer":"以前の配っている資料の一番最後のページを省いているものが机上配付された資料ですので、よろしくお願いいたします。","voiceIndex":137,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"で見ます。料金が上がるというのは、このご時世、仕方ないかなというふうに思っています。本当にこれ、助かるのですよね。本当に助かっておりまして、私もよく利用するのですけれども、区のほうでやっていただくということは、とてもありがたいなというふうに思っています。ただ１点、お願いしたいのが、ホームページのほうで収集日とかを選ぶわけです。なので、そこの工夫は何かありますでしょうか。","respondent":"品川品川区清掃事務所長","answer":"ですので、該当しない品目が出てきてしまうのは、これはやむを得ないというところがあります。そういう場合に、粗大ごみ受付センターのほうに連絡していただくというのは通常のやり方になっておりますが、今年度、粗大ごみシステムを全面改修する予定になっております。","voiceIndex":139,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"ぜひ分かりやすいようにお願いいたします。これは関係ないとは思うのですけれども、学校でやっている地域の資源回収がありますよね。関係なかったら関係ないと言っていただいていいのですけれども、あれもとても有効活用できるのです、非常に助かっています。なので、そこら辺もご案内をしていただくと、より分かりやすくなるのかなと思いますが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"非常にそういうところで意識の高い方等、リサイクルのほうに回してくれる方もいらっしゃいますので、こういう部分につきましては、今後も周知方法をいろいろ工夫しながら、皆様に伝えて利用していただくように努力してまいります。","voiceIndex":141,"id":"exchange-051"}]},{"id":"topic-07","title":"自転車ヘルメット購入助成申請の受付開始","agenda":"自転車ヘルメット購入助成申請の受付開始","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１点は、保険加入というところなのですが、先ほど入られていない方にはご案内するということだったのですが、大体、保険にもよると思うのですが、幾らぐらいかかるものになるのでしょうかということが１点。それから、私もいろいろ考えて、ネットとかで見ているのですけれども、いろいろあります。それは信じていいのでしょうかという、少し不安になっているのですけれども、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"区民交通傷害保険ですと、自動車損害賠償保険については１,４００円からの掛金で対応しています。一般の生命保険もしくは傷害保険に附帯しているものについては、これにはプラス１００円で１億円の保証がついているものというようなものもあります。多種多様です。","voiceIndex":147,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"ですから、買った当時は保険に入っていないけれども、それから入っても補償は、２,０００円の助成はあるという理解でいいのでしょうかということが１点と、あごひもなのですけれども、チラシに書いていないですよね。それと、対象の安全基準が、何とかマークと一応なっています。","respondent":"工藤交通安全担当課長","answer":"それと２点目、あごひもがついていなくて安全基準のマークがついているということなのですけれども、こちらは、そういう条件であるので、あごひもがついたものということを推奨はするのですけれども、助成対象ということで受け付けたいと考えております。","voiceIndex":149,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"それをどこに置くかというと、多分、買物かごに置くと思うのです。そうすると、盗難も往々にしてあるかなと。そこら辺も、今後気をつけていただきたい。もしかしたら盗難は当然出てくる話かなというふうに思っていますので、そこはこれから問題として起きるかなというふうに思いますので、そこも注視していただきたいと思います。これは意見という形でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"周知を十二分にしていただきたいということで、先ほど、自転車商、それから子どもの公共的な施設というお話がありまして、その中に、もう端的に加えていただきたいというか、自転車商協同組合に入っていない自転車商、いろいろな大小規模があったりして、規模の大きなところはズラーッと自転車がこれでもかというぐらい並んで、ご商売ですので。","respondent":"工藤交通安全担当課長","answer":"どうしたらいいかというご相談なのですけれども、こういったところに対しても、区としましては、チラシを配布し協力を求めていくというような形で今後進めていきたいと考えています。","voiceIndex":153,"id":"exchange-055"}]},{"id":"topic-08","title":"バリアフリー工事（ゼームス坂通り３工区）","agenda":"バリアフリー工事（ゼームス坂通り３工区）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それをなくして、下の２工区のような景観というか、そういう状況になっていくという理解でよろしいでしょうか。何cmぐらい高くしなければいけないとかということがあるのですけれども、そこら辺を、上の図、現況写真を見ると、通路側との境界線の段差は、これは維持されるという、そういうイメージでよろしいのでしょうか。","respondent":"森道路課長","answer":"それは車が少し入っても、そこで跳ね返されるように、そういう段差をつけるというふうになっているのですけれども、セミフラット型といって、歩道と車道の段差を５cm程度にしかとらない場合でも、その間のブロックを１５cm確保していって。","voiceIndex":161,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"ただ、民家のところとか、駐車場が道路側にあるとかというところは、あれは坂というか、斜面というか、ブロックで１５cmというのではなくて、そこはお宅のほうと協議しながらの整備という理解でよろしいですか。","respondent":"森道路課長","answer":"今回は車道を上げるわけですけれども、歩道と車道の差を少なくして、そこの間のブロックも２cmなり５cmなりというような低いブロックで整備をしますので、それによって車が入りやすく、しかも、歩道は波打たないというような形でつくっていきたいと思っています。","voiceIndex":163,"id":"exchange-057"}]},{"id":"topic-09","title":"Ｐａｒｋ－ＰＦＩ制度を導入する公園（東品川海上公園）","agenda":"Ｐａｒｋ－ＰＦＩ制度を導入する公園（東品川海上公園）","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"この間、いろいろ調査をされてきたということで、利用者アンケートは１項目出ておりますが、ほかにはどのようなことを聞いて、利用者の方のお答えはどのような答えだったのかということを伺いたいと思います。マーケットサウンディング調査のほうでも、ほかにどういった調査をされて、提案も含めて、どういったものが出てきているのかというところを伺いたいと思います。","respondent":"高梨公園課長","answer":"そのほかには、例えばですけれども、公園の中に農園を設置して貸し農園、菜園のようなものをつくったらどうかというような提案もございましたし、また、ドッグランをつくって、ドッグランの運営を収益施設として行いたいというような提案もあったところです。","voiceIndex":169,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"それと、今回、この東品川海上公園で施設をつくるということになるのかなと思うのですが、それはどのくらいの規模、何m2ぐらいを見込んでいるのか伺います。","respondent":"高梨公園課長","answer":"建設される施設の規模ですが、これは提案を広く求めますものですから、区として何m2ということで縛る予定はございませんが、一定程度、カフェ等の収益施設を設置する際には、２００m2から３００m2ぐらいの建築面積がないと、お客さんを呼んで。","voiceIndex":171,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"というのは、いろいろ用途とか利用者の状況を考えると、例えば、五反田ふれあい水辺広場も、使い方によっては、水辺環境によっては、とてもいい使い方ができると思うのです。それから、文庫の森です。どこまで調査して、こういう結果になっているのかなと思うのですが、いかがですか。","respondent":"高梨公園課長","answer":"今回１４社に手を挙げていただきましたけれども、その際には、区のほうから、細かな公園の立地であるとか、そういった説明は特になく、事業者のほうで各公園を調べていただいて提案していただくといったところでございました。","voiceIndex":174,"id":"exchange-060"},{"speaker":"西本委員","kind":"提案","question":"やはりこちらサイドでの提案ということもある程度必要なのかなと。なので、そこは品川区も、ある程度、こういうまちづくり、こういう公園とか、こういうふうにしていきたいとかということは、ある程度伝えて、もちろんこの海上公園については、公募の方向性があると思いますけれども、この前の段階で、もう少し品川区の意見を言ってもよかったのではないかなと思うのですけれども、いかがですか。","respondent":"高梨公園課長","answer":"そこの中では、今、委員おっしゃられたような地域の特性であるとか、そういったものをしっかりと公募の指針の中に盛り込んで、それに合致した提案を求めるという形で進めていきたいというふうに考えてありますので、その辺りはしっかりと地域の特性であったり、また。","voiceIndex":176,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"これからなのだろうと思います。そこは、その特徴、Ｐａｒｋ－ＰＦＩの制度を見ながら、やはり品川区にとってという形でいろいろと工夫をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"公募の指針をこれからつくっていくということで、地域の声、意見を反映させていくということなのですが、どういった形で反映させていくのかというところを伺いたいと思います。","respondent":"高梨公園課長","answer":"地域の方々の意見は法の縛りはございませんが、やはり区といたしましては、Ｐａｒｋ－ＰＦＩでできる施設を地域の方々に愛してしっかり使っていただきたいという思いがありますので、今現在、東品川海上公園周辺で活動していただいている各団体の方々へのヒアリングや、また。","voiceIndex":180,"id":"exchange-063"}]},{"id":"topic-10","title":"（仮称）勝島人道橋およびしながわ花海道における都市計画決定","agenda":"（仮称）勝島人道橋およびしながわ花海道における都市計画決定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、公園にするということですよね。それで、私が伺った中では、今回この整備が２０億円かかるということで、今、物価高とかコロナで暮らしが大変なところに２０億円かけるのかと、反対だという声も聞いているのですけれども、そうした声が区のほうには届いているかどうか伺いたいと思います。","respondent":"高梨公園課長、森道路課長","answer":"今回、人道橋の整備に合わせまして都市計画公園とするわけですが、都市計画審議会等を経て、現在も土地所有者というか、護岸は東京都港湾局が所有している上を借りて児童遊園にしているわけなのですけれども、今回。２０億円必要だというところで、今もそのぐらいの事業費になるだろうというふうには区として考えておりますけれども、１０月に行いました説明会の中でも、一部そういったお話はございましたけれども、２０億円をしっかりと。","voiceIndex":186,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"場所をもう少し教えていただきたいのですけれども、今、公園になっていないですよね。公園になっているところですか。それで、結局、花海道ですから、向こう側も道があるのでしたか。そこら辺も含めて、全体的な、これを機に、あそこの発展をしていただきたいという思いがあるのですけれども、ほかのところとの協調性というか、協力体制とか、調和性とかについてはいかがでしょうか。","respondent":"高梨公園課長","answer":"今回、都市計画公園とするに当たりましても、そういった地域の皆様の力で管理していただいている、またそれで生み出されたにぎわいをしっかりと末永く担保していきたい、これからも将来にわたって公園としてしっかりと位置づけていきたいといった思いもありますので、今回。","voiceIndex":190,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"本当にここは地域の方々のお力が非常に関わっているところですので、説明会が２６日にあるということなのですけれども、やはり発展的なイメージが沸くように、ぜひ説明をしっかりしていただきたいと思っています。なので、そうではなくて、それをさらによくしていくよという感じで、ご説明のほど、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の都市計画決定ということで、都市計画公園を選定するということなのですけれども、去年の１０月２０日の説明会のときの質問に対する回答ということで区の資料なども見させていただいているのですが、先ほども出ましたけれども、まず最初は２０億円経費がかかる、４０％国庫補助を求めているという流れがあったと思っていたのですが、１０月２０日の説明会の回答では。","respondent":"森道路課長、高梨公園課長","answer":"ですので、特に最初から変わったというふうには区としては考えていないというところです。１０月２０日の説明会の中では、ルート３というお話も参加された方からはいただきました。都市再生整備計画で位置づけられた３つの基幹事業についてですが、今回のご報告では、人道橋としながわ花海道の整備についてご報告をしていますが、都市再生整備計画上の３つの基幹事業の残り１つの新浜川公園の整備につきましても。","voiceIndex":194,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"費用の関係でいうと、すみません、ここの資料だけでの読み方でいうと、工事費が幾らぐらいかでおおむね２０億円と、補助率が４割だけれども、区の負担は１２億円かといったことに対しては、いや、そうではなく、基本的には区の単独費用となるというような書かれ方なので、そこはもう１回改めてと、すみません、これ、総額２０億円としたときの最終的な決定は、１億８,０００万円以上の工事なので。","respondent":"森道路課長","answer":"１０月２０日に開催した説明会の後、質問をいただいた中で、それに対する区の考え方をホームページに示させていただいておりまして、今、委員からご紹介いただいたものについては、補助額が４割だとすると、残りの１２億円を区が負担するのかというお話の質問に対して。","voiceIndex":197,"id":"exchange-068"},{"speaker":"田中委員","kind":"質問","question":"分かりました。プラス、児童遊園を都市計画公園にすることによって、公園としての管理のランクが上がるので、いわゆる交付金が、都からなのか、入るということの、この４割プラス財源確保というような観点も含め、あと、回遊性の精度を高めるということも含め、都市計画公園にするという、そういうことでしょうか。","respondent":"高梨公園課長","answer":"先ほど申し上げましたとおり、将来において公園を末永く担保する意味で都市計画決定を行うところですが、そのことによりまして、今、委員からもご紹介のありました都市計画交付金等の公園整備に係る費用の一部について補助金が獲得できるところは事実ですので。","voiceIndex":199,"id":"exchange-069"},{"speaker":"田中委員","kind":"質問","question":"都市計画公園の指定を受けるに当たりまして、現状の児童遊園の部分だけ、花海道で使っている護岸のところだけでも指定はされるのでしょうか。要は、今回の人道橋をつくって初めて都市計画公園として認定されるのか、人道橋がなくても認定されるのか、そこら辺はいかがでしょうか。","respondent":"高梨公園課長","answer":"今回、人道橋を架設するといったところを契機に、もし人道橋を位置づけないと、では、この人道橋の位置づけ、道路なのか、公園なのかといったところが宙に浮いてしまいますので、この人道橋の架設を機に。","voiceIndex":201,"id":"exchange-070"},{"speaker":"田中委員","kind":"確認","question":"もう１点、別の観点で確認をしたいのですが、南海トラフ巨大地震の震災時の想定で津波が発生したときに、勝島の、正にこの人道橋が建設されるとするその先が、いろいろ数字がありますが、２.３８ｍの津波が来るというような想定がありますが、今回、形状からすると、勝島運河の両側に、いわゆる出島のような形で造って橋を渡すということなのですが、耐震性だとか、そういった観点では。","respondent":"森道路課長","answer":"当然、構造の耐震性ということは、それも与条件として検討しておりますので、それについては、今の設定条件としては問題ないというふうに考えています。","voiceIndex":203,"id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"今、高潮の部分で次に触れようかなと思ったのですが、正に東京湾沿岸海岸保全基本計画で、２１００年の時点の想定があって、一方、今回の人道橋は、Ａ.Ｐ.＋５.８ｍだったか、５.６ｍに対して、今、課長も触れられた想定では、２１００年の想定ではＡ.Ｐ.＋５.９ｍということで、想定のほうが少し高いのですが、２１００年のことを想定している数字なので、その後どう変わるかも分かりませんし、また。","respondent":"森道路課長","answer":"ですので、そういった部分について、区としても、どうですかというお話をさせていただきましたけれども、港湾局のほうでは、今の計画でやっていただきながら、それを踏まえた護岸の整備計画を立案していくというようなお話をされていますので。","voiceIndex":205,"id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"私も、勝島運河にときどきですが行きますが、地元の方には親しまれているような場所でもある中で、２０億円かけて人道橋を造って回遊性を求める、都市計画公園にする、そこの判断はいろいろあるかと思いますが、品川区の年間の一般会計予算の１％分の金額をここに充てることの評価、これは、私はある意味、真剣に考えなければいけないと思いますし、また、極力区の負担は、先ほどの交付金をはじめ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-073"}]},{"id":"topic-11","title":"しながわ水族館リニューアルに向けた今後の進め方","agenda":"しながわ水族館リニューアルに向けた今後の進め方","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"区民アイデアを取り入れる展示を検討していくということですので、この間もそういった形でやってきたと思いますので、ぜひそれはやっていただきたいと思います。それで、今度、リニューアルした後、指定管理者制度を活用していく予定だということで、今回、指定管理者制度にしていく理由を伺いたいのと、そうすると、何が変わるのか伺います。","respondent":"高梨公園課長","answer":"現在、公園施設の管理許可という形で業務を事業者にお願いして運営をしているわけですが、現在、ほかの施設等を見ましても、民間事業者へのこういった委託に関しましては、指定管理者制度を利用した委託が常になっているといったところと、指定管理者とすることで。","voiceIndex":213,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"何が変わるかというところは、透明性が高まるということなのですか。この間も指定管理者にしようとすればできたのではないかと思うのですが、今回、出されてきたというところは、何かできなかったハードルがあるのかどうか伺いたいのと、この委託をするに当たって、今までと、この指定管理者で見込まれる経費は、比較すると、どちらが高いか安いのかを伺いたいと思います。","respondent":"高梨公園課長","answer":"経費に関しましては、指定管理者への委託料、あと、水族館運営等の収支につきましては、現在検討していますけれども、原則的な考えとしましては、水族館の運営の中でまかなっていただくといったところを基として考えているところですが、これから公募を行う中で、事業者とも。","voiceIndex":215,"id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"収支は今は分からないということなのですけれども、そうすると、やはり指定管理者を導入していく区の狙いがあるのかなというふうに思ってしまうのですけれども、この間、例えば、夜の営業はあまりやってこなかったと思うのですが、そういったことをやるようにするためなのか、何かそういった区の狙いがあるのか伺いたいと思います。","respondent":"高梨公園課長","answer":"夜の営業に関しましては、特段、指定管理者制度であるからできるというようなものではなく、現在も、協議等が整えばできないわけでもないですが、一定、リニューアルが営業時間をもう１回考え直すよい機会であるというふうに考えてありますので、この間、運営準備委託。","voiceIndex":217,"id":"exchange-076"},{"speaker":"西本委員","kind":"確認","question":"確認を少々したいと思うのですが、まず、改めて、このしながわ水族館、水族館を区でというのは、なかなかほかの自治体ではなく、撤退ですよね、そこをあえて品川区がやるという結論に達したという、いろいろ思いがあると思うので、本当に、私も長年、しながわ水族館の皆さんの取組を見て、やはり続けてほしいなというすごく強い思いがあったので。","respondent":"高梨公園課長","answer":"万が一、いろいろと今後もまた感染症対応とかで赤字になることもあろうかと思いますけれども、やはり事業者にそれを押しつけるというか、持っていただくというのは、区立の水族館としては望ましくない形であるというふうに考えてありますので、そういった際の取組についても。","voiceIndex":220,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"思いがすごく伝わっておりますので、ぜひその思いを継続して維持していただきたいと思っています。なので、そこをどう活用されるかということをお聞きしたいと思います。それから、イルカたちです。今後、リニューアルに際して、イルカはどうなってしまうのかと、また違うスターをつくるのかなとか、いろいろ考えられていると思いますけれども、その辺のイルカの先行きのお考えをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"そういったお話を区としても認識してございまして、関係各所の職員を集めてプロジェクトチームをつくって、こういった、今、委員からもお話がありました周辺の観光施設であったりとか、学校との連携、それと環境面。","voiceIndex":222,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"イルカについては、やはり皆さんに、なるべく多くの方に見ていただきたいというふうに思いますので、よろしくお願いします。それと、このイルカの話もそうなのですけれども、意外と他地域から来られる方がとても多いのです。最後に、３番の設計委託ということで確認なのですが、簡易型、運営準備事業者が選ばれて、それで、設計業者は運営準備事業者が選ぶという形になるということですよね。","respondent":"高梨公園課長","answer":"ただ、その設計事業者と運営事業者との連携はいいのですけれども、区としても、そこは設計、計画をしていく中では、しっかりと物申していきたいという思いがありますので、契約は運営事業者と区、それと設計事業者と区ということで、それぞれ区と契約していただく形で。","voiceIndex":224,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そういうものも含めて選定していただきたいなというふうに、決して肩を持つわけではないのですけれども、今までの歴史とか経験なども十分に加味した形でお願いしたいというふうにお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"耐震化事業のほうでお聞きしますが、この一時滞在施設等で１９か所は、これはどこに、どういう条件の下でここになるのでしょうか。下水管はたくさんあると思うのですけれども、この１９か所は、どういうところでの１９か所なのか教えてください。","respondent":"北原河川下水道課長","answer":"令和３年３月に下水道局が新しく経営計画を見直しまして、その中で一時滞在施設を新たに追加されたことから、今実施しているものでして、区のほうで帰宅困難者に対して帰宅が可能になるまで一時的に待機する場所を民間と協定を結んだりして決まっているところがございまして。","voiceIndex":231,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"これ、避難所の、例えば小中学校の避難所のところも、たしか同じような工事がなかったでしたか。下水管の補強という形であったような気がしたのですけれども、それと同類の工事ですという理解でよろしいですか。","respondent":"北原河川下水道課長","answer":"避難所につきましては、過去に実施を、下水道局と品川区で役割分担をしながら進めてきておりまして、そちらと同様の工事をすることによって、こちらでも下水道管の機能を地震時も確保できるという工事になります。","voiceIndex":233,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"これ、以前に避難所のところで耐震化事業があったときに、避難所のトイレの問題がいろいろあって、大分それが回避できるというふうに思ったのです。なので、認識としては、今の区の避難所になっているところの下水の工事は、ある程度、工事がなされていて、かなり耐久性がありますという認識でよろしいのですか。","respondent":"北原河川下水道課長","answer":"避難所につきましては、平成２５年ぐらいまでに避難所に選定されている箇所を順次やってきまして終わっておりまして、その後、また新たに避難所に設定された場所なども順次やってきておりまして、全て終わっているわけではないのですけれども。","voiceIndex":235,"id":"exchange-083"},{"speaker":"田中委員","kind":"質問","question":"耐震化事業に関してなのですが、東京都としては、２０１１年の東日本大震災以降だったと思いますが、地震によってマンホールが浮き上がってしまったことの対策として、こういう取組に力を入れ始めたかなと思うのですが、そこからすると大分経過している中で、今回、新たに１９か所ということなのですが、そもそも東京都の事業が、都の役割分担というか。","respondent":"北原河川下水道課長","answer":"下水道局は、過去にまずは避難所ですとか、区役所ですとか、災害復旧拠点であったり、そういったところを優先的に整備をしてきまして、２３区たくさんありますので、そのうちの一部を区役所に委託して、両方とも、下水道局も施工しますし。","voiceIndex":238,"id":"exchange-084"},{"speaker":"田中委員","kind":"提案","question":"それで、もう１つの再構築事業のことでありまして、下水道管の復旧の中で、１つ提案というか、老朽化というか、下水道管の延命として、東京都がダイエットレシピといって、要は、各家庭で油をそのまま流すことによって、それが下水道管の老朽化につながってしまうというようなこともあって、油をなるべく使わないような家庭でのレシピを発表されているのですけれども、正に東京都は大都市事務。","respondent":"北原河川下水道課長","answer":"ダイエットレシピについてですけれども、油が管の中につかないということで、老朽化という側面もあるかもしれないのですが、下水がつまらないということで、汚水が路上に噴き出してしまったり、浸水の原因になったりしないという側面もありますので。","voiceIndex":240,"id":"exchange-085"},{"speaker":"若林委員","kind":"質問・要望","question":"再構築事業のほうで、まず、下の東五反田一丁目・二丁目の、いわゆる対象路線と対象流域の数字が抜けているのはなぜでしょうかということが１つ。それから、目的の中にある、これ、もう少しご説明いただきたいと思いました。老朽化に伴う道路陥没というところのご説明、それから、排水能力の増強、この２つの目的について、もう少し重ねての説明をお願いしたいと思います。","respondent":"北原河川下水道課長","answer":"当時整備した下水道管が、都市化が進む以前の想定で、雨水が、雨が降ったときに、大体５０％ぐらいは土に浸透します、残り５０％が下水道に入ってきますという形で整備されていまして、最近は、大体８０％ぐらいが下水道管の中に入ってきてしまうということで。","voiceIndex":243,"id":"exchange-086"},{"speaker":"若林委員","kind":"質問","question":"排水能力の増強というのは、要するに、管を太くするという、そういう意味なのでしょうかというお尋ねをさせていただいて、もう１つ最後に、これ、いわゆる部分的な、多分、再構築の全体像があって、今回、それの一部分の工事を受託するという意味だと思うのですけれども、全体像、今から何か資料ということではないのですが、何か言葉で全体像を説明できるものがあれば、参考にお聞きしたいと思います。","respondent":"北原河川下水道課長","answer":"１点目の質問についてですが、こういった工事をやるに当たって、まず、事前に調査を行いまして、やる場所を選定するのですけれども、１年間にできる事業量とかも考えましてエリアを設定していまして、また、周辺のほかの工事の状況とかも含めてエリアを設定しておりますので。","voiceIndex":245,"id":"exchange-087"},{"speaker":"若林委員","kind":"確認","question":"その目黒川の北側、川は蛇行しているので、場所によっては西になったり、東になったりすると思うのですけれども、ざっくり北側が古くて、南側が比較的、管の新しさでいうと新しいという理解でいいのか確認をします。","respondent":"北原河川下水道課長","answer":"目黒川の左岸側が古い、右岸側から大田区側といいますか、そちら側が比較的新しいということになります。","voiceIndex":249,"id":"exchange-088"}]},{"id":"topic-12","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"従前どおり２泊３日ということなのですが、今後、コロナの感染状況を踏まえ、できれば日帰りにしたほうがいいのではないかというふうに、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-089"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":91441,"voices":276}}]);
